export function randomWeapon(rng = Math.random, tierBias = 0) {
  const roll = rng() + tierBias;
  let pool = LOOT_POOL.common;
  if (roll > 0.985) pool = LOOT_POOL.mythic;
  else if (roll > 0.93) pool = LOOT_POOL.legendary;
  else if (roll > 0.75) pool = LOOT_POOL.epic;
  else if (roll > 0.4) pool = LOOT_POOL.rare;
  return pool[Math.floor(rng() * pool.length)];
}

export function weaponDps(w) {
  if (!w) return 0;
  const pellets = w.pellets || 1;
  return (w.damage * pellets) / Math.max(0.05, w.fireRate);
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';

/* ────────────────────────── helpers ────────────────────────── */

const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const lerp = (a, b, t) => a + (b - a) * t;
const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function paint(geo, color) {
  const c = new THREE.Color(color);
  const n = geo.attributes.position.count;
  const arr = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { arr[i * 3] = c.r; arr[i * 3 + 1] = c.g; arr[i * 3 + 2] = c.b; }
  geo.setAttribute('color', new THREE.BufferAttribute(arr, 3));
  return geo;
}

function box(w, h, d, x, y, z, color, rotY = 0) {
  const g = new THREE.BoxGeometry(w, h, d);
  paint(g, color);
  if (rotY) g.rotateY(rotY);
  g.translate(x, y, z);
  return g;
}

function cyl(rt, rb, h, x, y, z, color, seg = 7) {
  const g = new THREE.CylinderGeometry(rt, rb, h, seg);
  paint(g, color);
  g.translate(x, y, z);
  return g;
}

function rock(r, x, y, z, color, detail = 0) {
  const g = new THREE.IcosahedronGeometry(r, detail);
  paint(g, color);
  g.scale(1, 0.72 + Math.random() * 0.4, 1);
  g.rotateY(Math.random() * Math.PI);
  g.translate(x, y, z);
  return g;
}

function merge(list, material) {
  if (!list.length) return null;
  const geo = mergeGeometries(list, false);
  const mesh = new THREE.Mesh(geo, material);
  mesh.frustumCulled = true;
  return mesh;
}

function canvasTexture(text, bg, fg, w = 256, h = 128) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const ctx = c.getContext('2d');
  ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = fg; ctx.lineWidth = 6; ctx.strokeRect(8, 8, w - 16, h - 16);
  ctx.font = `900 ${Math.floor(h * 0.42)}px Impact, Arial Black, sans-serif`;
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillStyle = fg;
  ctx.shadowColor = fg; ctx.shadowBlur = 18;
  ctx.fillText(text, w / 2, h / 2 + 4);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 2;
  return tex;
}

/* ────────────────────────── terrain ────────────────────────── */

function makeHeightFn(map) {
  const bunker = { x: -58, z: -120, r: 16, y: 14 };
  return function heightAt(x, z) {
    let h = 2.2
      + Math.sin(x * 0.025) * 1.25
      + Math.cos(z * 0.021) * 1.05
      + Math.sin((x + z) * 0.052) * 0.45;

    // Cordillera al norte
    const ridge = Math.exp(-Math.pow((z + 145) / 58, 2))
      * (13 + 9 * Math.sin(x * 0.019) + 7 * Math.cos(x * 0.043 + 1.7));
    h += Math.max(0, ridge);

    // Volcán
    const vd = Math.hypot(x - 10, z - 105);
    if (vd < 80) {
      const t = 1 - vd / 80;
      h += Math.pow(t, 1.65) * 48;
      if (vd < 15) h -= (1 - vd / 15) * 14;
    }

    // Meseta de la ciudad
    const cd = Math.hypot(x - 95, z + 40);
    if (cd < 68) h = lerp(h, 2.6, smoothstep(68, 34, cd) * 0.94);

    // Meseta del pueblo
    const pd = Math.hypot(x + 95, z - 35);
    if (pd < 52) h = lerp(h, 2.3, smoothstep(52, 24, pd) * 0.92);

    // Búnker (solo posapocalipsis)
    if (map.ruined) {
      const bd = Math.hypot(x - bunker.x, z - bunker.z);
      if (bd < bunker.r) h = lerp(h, bunker.y, smoothstep(bunker.r, 7, bd));
    }

    // Caída al agua en los bordes
    const r = Math.hypot(x, z);
    h -= smoothstep(168, 210, r) * 22;
    return h;
  };
}

function buildTerrain(scene, map, heightAt) {
  const size = 420, seg = 108;
  const geo = new THREE.PlaneGeometry(size, size, seg, seg);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const c = new THREE.Color();
  const rng = mulberry32(map.id === 'neon' ? 77 : map.id === 'posapocalipsis' ? 42 : 13);

  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    const y = heightAt(x, z);
    pos.setY(i, y);

    const inCity = Math.hypot(x - 95, z + 40) < 68;
    const inVillage = Math.hypot(x + 95, z - 35) < 52;
    const volcano = Math.hypot(x - 10, z - 105);
    const mountain = z < -92;

    if (volcano < 82) {
      const t = 1 - volcano / 82;
      c.set(map.lava ? '#3d241e' : '#3a3a3a').lerp(new THREE.Color('#1a1414'), t * 0.75);
      if (volcano < 20) c.lerp(new THREE.Color('#ff5a1f'), (1 - volcano / 20) * 0.5);
    } else if (inCity) {
      c.set(map.ruined ? '#3f3b36' : map.toxic ? '#262033' : '#4a4640');
    } else if (inVillage) {
      c.set(map.ruined ? '#4a4433' : map.toxic ? '#2a2438' : '#4e6b35');
    } else if (mountain) {
      c.set(map.ruined ? '#4a4a45' : map.toxic ? '#2c2440' : '#5d5548');
    } else {
      c.set(map.ruined ? '#55503f' : map.toxic ? '#2a2138' : map.ground);
    }
    const n = (rng() - 0.5) * 0.09;
    c.offsetHSL((rng() - 0.5) * 0.015, 0, n);
    colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geo.computeVertexNormals();
  const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.receiveShadow = false;
  mesh.name = 'terrain';
  scene.add(mesh);

  // Agua / borde
  const water = new THREE.Mesh(
    new THREE.PlaneGeometry(900, 900),
    new THREE.MeshBasicMaterial({
      color: map.toxic ? 0x0b1a24 : map.lava ? 0x2a1612 : 0x14252e,
      transparent: true, opacity: 0.9,
    })
  );
  water.rotation.x = -Math.PI / 2;
  water.position.y = -0.4;
  scene.add(water);
  return mesh;
}

/* ────────────────────────── structures ────────────────────────── */

function buildCity(ctx) {
  const { map, heightAt, buildings, windows, neonStrips, signs, colliders, rng } = ctx;
  const palette = map.toxic
    ? ['#1d1730', '#241a3a', '#191226', '#2b1c44', '#120e20']
    : map.ruined
      ? ['#3e3a34', '#4a453d', '#35312c', '#524b40']
      : ['#6b6154', '#7a6c5b', '#5c554c', '#8a7a64', '#4f4a44'];

  const cell = 27;
  const startX = 58, startZ = -98;
  for (let ix = 0; ix < 4; ix++) {
    for (let iz = 0; iz < 4; iz++) {
      if (rng() < 0.12) continue; // plaza / callejón abierto
      const cx = startX + ix * cell + (rng() - 0.5) * 4;
      const cz = startZ + iz * cell + (rng() - 0.5) * 4;
      const w = 10 + rng() * 9;
      const d = 10 + rng() * 9;
      const baseY = heightAt(cx, cz);
      let h = 8 + rng() * (map.toxic ? 46 : 30);
      if (map.ruined) h *= 0.45 + rng() * 0.3;
      if (map.toxic) h = Math.max(h, 18);

      const color = palette[Math.floor(rng() * palette.length)];
      buildings.push(box(w, h, d, cx, baseY + h / 2, cz, color));
      colliders.push({ minX: cx - w / 2, maxX: cx + w / 2, minY: baseY - 1, maxY: baseY + h, minZ: cz - d / 2, maxZ: cz + d / 2, tag: 'building' });

      // Tejado / antena
      if (!map.ruined && rng() < 0.6) {
        buildings.push(box(w * 0.5, 0.6, d * 0.5, cx, baseY + h + 0.3, cz, '#2c2a28'));
      }
      if (map.ruined) {
        for (let k = 0; k < 3; k++) {
          const rw = 3 + rng() * 4, rh = 1 + rng() * 3;
          buildings.push(box(rw, rh, 3 + rng() * 4, cx + (rng() - 0.5) * w, baseY + rh / 2, cz + (rng() - 0.5) * d, color));
        }
        for (let k = 0; k < 4; k++) {
          ctx.rocks.push(rock(0.8 + rng() * 1.6, cx + (rng() - 0.5) * (w + 8), baseY + 0.4, cz + (rng() - 0.5) * (d + 8), '#4b463d'));
        }
      }

      // Ventanas emisivas
      const rows = Math.max(1, Math.floor(h / 3.4));
      const cols = Math.max(1, Math.floor(w / 3.2));
      const lit = map.toxic ? ['#ff3ea5', '#35f0ff', '#ffd166', '#a06bff'] : map.ruined ? ['#ffb35a'] : ['#ffd98a', '#ffb35a', '#9fd8ff'];
      for (let face = 0; face < 4; face++) {
        if (map.ruined && face > 1) continue;
        const isX = face < 2;
        const sign = face % 2 === 0 ? 1 : -1;
        const faceCols = isX ? cols : Math.max(1, Math.floor(d / 3.2));
        for (let ry = 0; ry < rows; ry++) {
          for (let cxi = 0; cxi < faceCols; cxi++) {
            if (rng() < 0.38) continue;
            const off = (cxi + 0.5) / faceCols - 0.5;
            const wx = isX ? cx + sign * (w / 2 + 0.06) : cx + off * w;
            const wz = isX ? cz + off * d : cz + sign * (d / 2 + 0.06);
            windows.push({
              x: wx, y: baseY + 1.9 + ry * 3.3, z: wz,
              ry: isX ? Math.PI / 2 : 0,
              color: lit[Math.floor(rng() * lit.length)],
              sx: map.toxic ? 0.55 : 0.8, sy: map.toxic ? 0.18 : 0.9,
            });
          }
        }
      }

      // Tiras de neón
      if (map.toxic && rng() < 0.85) {
        const nc = rng() < 0.5 ? '#ff3ea5' : '#35f0ff';
        neonStrips.push({ x: cx - w / 2 - 0.1, y: baseY + h * 0.55, z: cz, sx: 0.12, sy: h * 0.7, sz: 0.12, color: nc });
        neonStrips.push({ x: cx, y: baseY + h - 0.3, z: cz - d / 2 - 0.1, sx: w, sy: 0.14, sz: 0.14, color: nc });
        if (rng() < 0.5) {
          const tex = ['LEUS', '24/7', 'RAMEN', 'CYBER', 'NO FUTURO', 'POLLO'][Math.floor(rng() * 6)];
          signs.push({ x: cx + w / 2 + 0.25, y: baseY + 5 + rng() * 6, z: cz + (rng() - 0.5) * d * 0.5, ry: Math.PI / 2, tex, w: 5 + rng() * 2, h: 2.2, color: nc });
        }
      }
    }
  }

  // Reactor nuclear (ciudad)
  const rx = 122, rz = -22, ry = heightAt(rx, rz);
  buildings.push(cyl(6, 7, 12, rx, ry + 6, rz, map.ruined ? '#3b3b38' : '#8b8f87', 10));
  buildings.push(cyl(7.4, 7.4, 1.2, rx, ry + 12.4, rz, '#2c2e2c', 10));
  buildings.push(cyl(3.2, 3.2, 4, rx, ry + 14.6, rz, '#4a4e4a', 8));
  colliders.push({ minX: rx - 7, maxX: rx + 7, minY: ry - 1, maxY: ry + 16, minZ: rz - 7, maxZ: rz + 7, tag: 'reactor' });
  if (!map.ruined) {
    neonStrips.push({ x: rx, y: ry + 7, z: rz - 7.1, sx: 1.2, sy: 4, sz: 0.2, color: '#7dffb0' });
  }
}

function buildVillage(ctx) {
  const { map, heightAt, buildings, colliders, rocks, rng } = ctx;
  const wall = map.ruined ? '#4a4336' : '#8a6a4a';
  const roof = map.ruined ? '#3a332a' : '#7a3f2e';

  for (let i = 0; i < 11; i++) {
    const a = (i / 11) * Math.PI * 2;
    const rad = 16 + rng() * 26;
    const cx = -95 + Math.cos(a) * rad;
    const cz = 35 + Math.sin(a) * rad;
    const by = heightAt(cx, cz);
    const w = 7 + rng() * 5, d = 7 + rng() * 5, h = 3.6 + rng() * 2.2;
    buildings.push(box(w, h, d, cx, by + h / 2, cz, wall));
    colliders.push({ minX: cx - w / 2, maxX: cx + w / 2, minY: by - 1, maxY: by + h, minZ: cz - d / 2, maxZ: cz + d / 2, tag: 'house' });

    if (!map.ruined) {
      const roofG = new THREE.ConeGeometry(Math.max(w, d) * 0.76, 2.4, 4);
      paint(roofG, roof);
      roofG.rotateY(Math.PI / 4);
      roofG.translate(cx, by + h + 1.2, cz);
      buildings.push(roofG);
    } else {
      buildings.push(box(w * 0.9, 0.5, d * 0.9, cx, by + h + 0.2, cz, roof));
      rocks.push(rock(1.2 + rng(), cx + (rng() - 0.5) * w, by + 0.4, cz + (rng() - 0.5) * d, '#5a5142'));
    }
    // Puerta
    buildings.push(box(1.2, 2.1, 0.2, cx, by + 1.05, cz + d / 2 + 0.08, '#241d17'));
    // Ventana
    buildings.push(box(1.2, 1.1, 0.2, cx - w * 0.28, by + h * 0.6, cz + d / 2 + 0.08, map.ruined ? '#1d1b17' : '#ffcf7a'));
  }

  // Cercas de campo
  for (let i = 0; i < 9; i++) {
    const x = -130 + rng() * 65, z = 10 + rng() * 55;
    const by = heightAt(x, z);
    const len = 5 + rng() * 9;
    buildings.push(box(len, 0.16, 0.16, x, by + 0.9, z, '#6b5a42'));
    for (let p = 0; p <= 4; p++) {
      buildings.push(box(0.18, 1.1, 0.18, x - len / 2 + (len * p) / 4, by + 0.55, z, '#5a4a36'));
    }
  }
  // Pacas de heno
  for (let i = 0; i < 7; i++) {
    const x = -120 + rng() * 45, z = 12 + rng() * 48;
    const by = heightAt(x, z);
    buildings.push(cyl(1.5, 1.5, 1.8, x, by + 0.9, z, '#b08a3e', 9));
  }
  // Torre de agua
  const tx = -68, tz = 54, ty = heightAt(tx, tz);
  buildings.push(cyl(0.4, 0.55, 9, tx - 2, ty + 4.5, tz, '#5a4a36', 5));
  buildings.push(cyl(0.4, 0.55, 9, tx + 2, ty + 4.5, tz, '#5a4a36', 5));
  buildings.push(cyl(3, 3, 3.2, tx, ty + 10.2, tz, map.ruined ? '#4a3a2a' : '#7a6a52', 9));
  colliders.push({ minX: tx - 3, maxX: tx + 3, minY: ty - 1, maxY: ty + 12, minZ: tz - 3, maxZ: tz + 3, tag: 'tower' });
}

function buildCordillera(ctx) {
  const { map, heightAt, rocks, colliders, buildings, rng } = ctx;
  for (let i = 0; i < 34; i++) {
    const x = -150 + rng() * 300;
    const z = -175 + rng() * 55;
    const y = heightAt(x, z);
    rocks.push(rock(1.4 + rng() * 4.2, x, y + 0.4, z, map.toxic ? '#2a2038' : map.ruined ? '#55514a' : '#665c4c'));
  }

  if (map.ruined) {
    // Búnker dentro de la montaña
    const bx = -58, bz = -120, by = 14;
    const wallC = '#4a4a44', dark = '#2b2b27';
    buildings.push(box(18, 0.5, 12, bx, by + 0.25, bz, dark)); // suelo
    buildings.push(box(18, 4.6, 0.6, bx, by + 2.5, bz - 6, wallC)); // pared norte
    buildings.push(box(18, 4.6, 0.6, bx, by + 2.5, bz + 6, wallC)); // pared sur
    buildings.push(box(0.6, 4.6, 12, bx - 9, by + 2.5, bz, wallC)); // pared oeste
    buildings.push(box(0.6, 4.6, 5, bx + 9, by + 2.5, bz - 3.5, wallC)); // pared este con puerta
    buildings.push(box(0.6, 4.6, 4, bx + 9, by + 2.5, bz + 4, wallC));
    buildings.push(box(18.6, 0.5, 12.6, bx, by + 4.85, bz, '#3c3c36')); // techo
    buildings.push(box(0.5, 4.6, 7, bx + 1.5, by + 2.5, bz, '#3a3a34')); // pasillo interior
    buildings.push(box(6, 2.4, 0.6, bx - 5, by + 1.7, bz + 2.2, '#55554e'));
    colliders.push({ minX: bx - 9.3, maxX: bx + 9.3, minY: by, maxY: by + 5, minZ: bz - 6.3, maxZ: bz - 5.7, tag: 'bunker' });
    colliders.push({ minX: bx - 9.3, maxX: bx + 9.3, minY: by, maxY: by + 5, minZ: bz + 5.7, maxZ: bz + 6.3, tag: 'bunker' });
    colliders.push({ minX: bx - 9.3, maxX: bx - 8.7, minY: by, maxY: by + 5, minZ: bz - 6, maxZ: bz + 6, tag: 'bunker' });
    colliders.push({ minX: bx + 8.7, maxX: bx + 9.3, minY: by, maxY: by + 5, minZ: bz - 6, maxZ: bz - 1, tag: 'bunker' });
    colliders.push({ minX: bx + 8.7, maxX: bx + 9.3, minY: by, maxY: by + 5, minZ: bz + 2, maxZ: bz + 6, tag: 'bunker' });
    colliders.push({ minX: bx + 1.2, maxX: bx + 1.8, minY: by, maxY: by + 5, minZ: bz - 3.5, maxZ: bz + 3.5, tag: 'bunker' });
    // Cajas
    for (let i = 0; i < 5; i++) {
      buildings.push(box(1.1, 1.1, 1.1, bx - 6 + rng() * 3, by + 1.1, bz - 3 + rng() * 6, '#6a5a3a'));
    }
    // Entrada iluminada
    ctx.neonStrips.push({ x: bx + 9.35, y: by + 3.2, z: bz + 0.5, sx: 0.2, sy: 0.25, sz: 3, color: '#ffb35a' });
  }
}

function buildVolcano(ctx) {
  const { map, heightAt, buildings, lava, rng } = ctx;
  const vx = 10, vz = 105;

  // Cráter brillante
  const crater = new THREE.Mesh(
    new THREE.CircleGeometry(13, 24),
    new THREE.MeshBasicMaterial({ color: map.lava ? 0xff5a1f : 0x552222, transparent: true, opacity: 0.9 })
  );
  crater.rotation.x = -Math.PI / 2;
  crater.position.set(vx, heightAt(vx, vz) + 0.15, vz);
  ctx.scene.add(crater);
  ctx.crater = crater;

  // Ríos de lava
  for (let r = 0; r < 7; r++) {
    const ang = (r / 7) * Math.PI * 2 + 0.3;
    const pts = [];
    for (let s = 0; s <= 14; s++) {
      const t = s / 14;
      const dist = 10 + t * (58 + rng() * 12);
      const wob = Math.sin(t * 7 + r) * 5 * t;
      const x = vx + Math.cos(ang) * dist + Math.cos(ang + Math.PI / 2) * wob;
      const z = vz + Math.sin(ang) * dist + Math.sin(ang + Math.PI / 2) * wob;
      pts.push(new THREE.Vector3(x, heightAt(x, z) + 0.25, z));
    }
    const curve = new THREE.CatmullRomCurve3(pts);
    const geo = new THREE.TubeGeometry(curve, 24, 1.4 + rng() * 1.2, 5, false);
    const mat = new THREE.MeshBasicMaterial({
      color: map.lava ? 0xff5a1f : 0x3a1a14,
      transparent: true, opacity: map.lava ? 0.92 : 0.45,
    });
    const mesh = new THREE.Mesh(geo, mat);
    ctx.scene.add(mesh);
    lava.push(mesh);
  }

  // Rocas del volcán
  for (let i = 0; i < 26; i++) {
    const a = rng() * Math.PI * 2;
    const d = 16 + rng() * 60;
    const x = vx + Math.cos(a) * d, z = vz + Math.sin(a) * d;
    ctx.rocks.push(rock(1 + rng() * 2.4, x, heightAt(x, z) + 0.3, z, '#3a2a24'));
  }
  // Fumarolas
  ctx.smokeOrigin.set(vx, heightAt(vx, vz) + 2, vz);
}

/* ────────────────────────── weather ────────────────────────── */

function buildWeather(scene, map) {
  const count = map.weather === 'neon' ? 500 : 380;
  const geo = new THREE.BufferGeometry();
  const positions = new Float32Array(count * 3);
  const seeds = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    positions[i * 3] = (Math.random() - 0.5) * 110;
    positions[i * 3 + 1] = Math.random() * 60;
    positions[i * 3 + 2] = (Math.random() - 0.5) * 110;
    seeds[i] = Math.random();
  }
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const color = map.weather === 'ash' ? 0xd8d0be : map.weather === 'neon' ? 0x7ef9ff : 0xffa060;
  const mat = new THREE.PointsMaterial({
    color, size: map.weather === 'neon' ? 0.16 : 0.34, transparent: true,
    opacity: map.weather === 'neon' ? 0.55 : 0.7, depthWrite: false,
    blending: map.weather === 'neon' ? THREE.AdditiveBlending : THREE.NormalBlending,
  });
  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;
  scene.add(points);
  return { points, positions, seeds, count };
}

/* ────────────────────────── main factory ────────────────────────── */

export function createWorld(scene, map, opts = {}) {
  const rng = mulberry32(map.id === 'neon' ? 9001 : map.id === 'posapocalipsis' ? 4242 : 1337);
  const heightAt = makeHeightFn(map);
  const colliders = [];
  const buildings = [];
  const rocks = [];
  const windows = [];
  const neonStrips = [];
  const signs = [];
  const lava = [];
  const smokeOrigin = new THREE.Vector3();
  const lootSpots = [];
  const chickenSpots = [];
  const gasMaskSpots = [];
  const group = new THREE.Group();
  group.name = 'world';

  // Sky dome
  const skyGeo = new THREE.SphereGeometry(420, 20, 12);
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false,
    uniforms: {
      top: { value: new THREE.Color(map.sky.top) },
      mid: { value: new THREE.Color(map.sky.mid) },
      bottom: { value: new THREE.Color(map.sky.bottom) },
    },
    vertexShader: `varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
    fragmentShader: `uniform vec3 top; uniform vec3 mid; uniform vec3 bottom; varying vec3 vP;
      void main(){ float h = normalize(vP).y; vec3 c = h > 0.05 ? mix(mid, top, smoothstep(0.05,0.7,h)) : mix(bottom, mid, smoothstep(-0.25,0.05,h)); gl_FragColor = vec4(c,1.0); }`,
  });
  const sky = new THREE.Mesh(skyGeo, skyMat);
  sky.frustumCulled = false;
  group.add(sky);

  const hemi = new THREE.HemisphereLight(map.hemi, 0x1a1512, 1.15);
  group.add(hemi);
  const dir = new THREE.DirectionalLight(map.sun, 1.9);
  dir.position.set(-80, 140, 40);
  group.add(dir);
  const fill = new THREE.DirectionalLight(map.accent2 ? new THREE.Color(map.accent2) : 0xffffff, map.toxic ? 0.7 : 0.25);
  fill.position.set(120, 60, -90);
  group.add(fill);

  buildTerrain(scene, map, heightAt);
  const ctx = { scene, map, heightAt, buildings, rocks, windows, neonStrips, signs, lava, colliders, smokeOrigin, rng };
  buildCity(ctx);
  buildVillage(ctx);
  buildCordillera(ctx);
  buildVolcano(ctx);

  // Merge static geometry
  const staticMat = new THREE.MeshLambertMaterial({ vertexColors: true });
  const cityMesh = merge(buildings, staticMat);
  if (cityMesh) { cityMesh.name = 'structures'; group.add(cityMesh); }
  const rockMesh = merge(rocks, new THREE.MeshLambertMaterial({ vertexColors: true, flatShading: true }));
  if (rockMesh) { rockMesh.name = 'rocks'; group.add(rockMesh); }

  // Ventanas instanciadas
  if (windows.length) {
    const wGeo = new THREE.BoxGeometry(1, 1, 0.1);
    const wMat = new THREE.MeshBasicMaterial({ toneMapped: false });
    const inst = new THREE.InstancedMesh(wGeo, wMat, windows.length);
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), e = new THREE.Euler();
    windows.forEach((w, i) => {
      e.set(0, w.ry, 0); q.setFromEuler(e);
      m.compose(new THREE.Vector3(w.x, w.y, w.z), q, new THREE.Vector3(w.sx, w.sy, 0.12));
      inst.setMatrixAt(i, m);
      inst.setColorAt(i, new THREE.Color(w.color));
    });
    inst.instanceMatrix.needsUpdate = true;
    if (inst.instanceColor) inst.instanceColor.needsUpdate = true;
    inst.name = 'windows';
    group.add(inst);
  }

  // Neón instanciado
  if (neonStrips.length) {
    const nGeo = new THREE.BoxGeometry(1, 1, 1);
    const nMat = new THREE.MeshBasicMaterial({ toneMapped: false });
    const inst = new THREE.InstancedMesh(nGeo, nMat, neonStrips.length);
    const m = new THREE.Matrix4(), q = new THREE.Quaternion();
    neonStrips.forEach((n, i) => {
      m.compose(new THREE.Vector3(n.x, n.y, n.z), q, new THREE.Vector3(n.sx, n.sy, n.sz));
      inst.setMatrixAt(i, m);
      inst.setColorAt(i, new THREE.Color(n.color));
    });
    inst.instanceMatrix.needsUpdate = true;
    if (inst.instanceColor) inst.instanceColor.needsUpdate = true;
    inst.name = 'neon';
    group.add(inst);
  }

  // Letreros de neón
  const signTextures = {};
  signs.slice(0, 22).forEach((s) => {
    if (!signTextures[s.tex]) {
      signTextures[s.tex] = canvasTexture(s.tex, '#120a1d', s.color);
    }
    const mat = new THREE.MeshBasicMaterial({ map: signTextures[s.tex], transparent: true, side: THREE.DoubleSide, toneMapped: false });
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(s.w, s.h), mat);
    mesh.position.set(s.x, s.y, s.z);
    mesh.rotation.y = s.ry;
    group.add(mesh);
  });

  // Niebla / ambiente
  scene.fog = new THREE.FogExp2(map.sky.fog, map.sky.fogDensity);
  scene.background = new THREE.Color(map.sky.fog);
  scene.add(group);

  const weather = buildWeather(scene, map);

  /* ── puntos de loot / pollos / máscaras ── */
  const isInside = (x, z) => colliders.some((c) =>
    x > c.minX - 1 && x < c.maxX + 1 && z > c.minZ - 1 && z < c.maxZ + 1);

  function scatter(n, minR, maxR, list, filter) {
    let tries = 0;
    while (list.length < n && tries < n * 40) {
      tries++;
      const a = rng() * Math.PI * 2;
      const r = minR + rng() * (maxR - minR);
      const x = Math.cos(a) * r + (rng() - 0.5) * 20;
      const z = Math.sin(a) * r + (rng() - 0.5) * 20;
      if (Math.hypot(x, z) > 195) continue;
      if (isInside(x, z)) continue;
      if (filter && !filter(x, z)) continue;
      list.push({ x, z, y: heightAt(x, z) });
    }
  }

  scatter(52, 18, 175, lootSpots);
  scatter(16, 20, 165, chickenSpots, (x, z) => {
    const city = Math.hypot(x - 95, z + 40) < 72;
    const village = Math.hypot(x + 95, z - 35) < 55;
    return !city || village || rng() < 0.2;
  });
  if (map.toxic) scatter(7, 30, 165, gasMaskSpots);

  // Ajustar puntos que caen en agua
  for (const list of [lootSpots, chickenSpots, gasMaskSpots]) {
    for (const p of list) {
      if (p.y < 0.6) p.y = Math.max(p.y, heightAt(p.x * 0.8, p.z * 0.8));
    }
  }

  /* ── raycast barato contra AABB + terreno ── */
  function segmentHit(from, to) {
    let bestT = 1;
    const dx = to.x - from.x, dy = to.y - from.y, dz = to.z - from.z;
    for (const c of colliders) {
      let tmin = 0, tmax = 1;
      // X
      if (Math.abs(dx) < 1e-8) { if (from.x < c.minX || from.x > c.maxX) continue; }
      else {
        let t1 = (c.minX - from.x) / dx, t2 = (c.maxX - from.x) / dx;
        if (t1 > t2) [t1, t2] = [t2, t1];
        tmin = Math.max(tmin, t1); tmax = Math.min(tmax, t2);
        if (tmin > tmax) continue;
      }
      if (Math.abs(dy) < 1e-8) { if (from.y < c.minY || from.y > c.maxY) continue; }
      else {
        let t1 = (c.minY - from.y) / dy, t2 = (c.maxY - from.y) / dy;
        if (t1 > t2) [t1, t2] = [t2, t1];
        tmin = Math.max(tmin, t1); tmax = Math.min(tmax, t2);
        if (tmin > tmax) continue;
      }
      if (Math.abs(dz) < 1e-8) { if (from.z < c.minZ || from.z > c.maxZ) continue; }
      else {
        let t1 = (c.minZ - from.z) / dz, t2 = (c.maxZ - from.z) / dz;
        if (t1 > t2) [t1, t2] = [t2, t1];
        tmin = Math.max(tmin, t1); tmax = Math.min(tmax, t2);
        if (tmin > tmax) continue;
      }
      if (tmin > 0.001 && tmin < bestT) bestT = tmin;
    }
    // Terreno (muestreo)
    const steps = 12;
    for (let i = 1; i <= steps; i++) {
      const t = i / steps;
      if (t >= bestT) break;
      const x = from.x + dx * t, y = from.y + dy * t, z = from.z + dz * t;
      if (y < heightAt(x, z)) { bestT = t; break; }
    }
    return {
      hit: bestT < 1,
      t: bestT,
      point: new THREE.Vector3(from.x + dx * bestT, from.y + dy * bestT, from.z + dz * bestT),
    };
  }

  /* ── colisiones de personaje ── */
  function resolveCollisions(pos, radius, height) {
    let onBox = null;
    for (const c of colliders) {
      if (pos.y + height < c.minY || pos.y > c.maxY) continue;
      const cx = clamp(pos.x, c.minX, c.maxX);
      const cz = clamp(pos.z, c.minZ, c.maxZ);
      const dx = pos.x - cx, dz = pos.z - cz;
      const d2 = dx * dx + dz * dz;
      if (d2 < radius * radius) {
        const d = Math.sqrt(d2) || 0.0001;
        if (d2 > 1e-6) {
          pos.x += (dx / d) * (radius - d);
          pos.z += (dz / d) * (radius - d);
        } else {
          // dentro del AABB: empujar por el eje más cercano
          const left = pos.x - c.minX, right = c.maxX - pos.x;
          const front = pos.z - c.minZ, back = c.maxZ - pos.z;
          const m = Math.min(left, right, front, back);
          if (m === left) pos.x = c.minX - radius;
          else if (m === right) pos.x = c.maxX + radius;
          else if (m === front) pos.z = c.minZ - radius;
          else pos.z = c.maxZ + radius;
        }
      }
      // Techo pisable
      if (pos.x > c.minX - 0.4 && pos.x < c.maxX + 0.4 && pos.z > c.minZ - 0.4 && pos.z < c.maxZ + 0.4) {
        if (pos.y <= c.maxY + 0.35 && pos.y >= c.maxY - 0.8) onBox = Math.max(onBox || -Infinity, c.maxY);
      }
    }
    return onBox;
  }

  function groundAt(x, z) { return heightAt(x, z); }

  /* ── update ── */
  let t = 0;
  const tmp = new THREE.Vector3();
  function update(dt, camera) {
    t += dt;
    // Partículas de clima alrededor de la cámara
    const arr = weather.positions;
    for (let i = 0; i < weather.count; i++) {
      const i3 = i * 3;
      if (map.weather === 'ember') {
        arr[i3 + 1] -= dt * (1.4 + weather.seeds[i] * 2.2);
        arr[i3] += Math.sin(t * 1.2 + i) * dt * 0.5;
      } else if (map.weather === 'ash') {
        arr[i3 + 1] -= dt * (2.4 + weather.seeds[i] * 3);
        arr[i3] += Math.sin(t * 0.7 + i) * dt * 1.3;
      } else {
        arr[i3 + 1] -= dt * (12 + weather.seeds[i] * 8);
      }
      if (arr[i3 + 1] < -2) {
        arr[i3 + 1] = 55;
        arr[i3] = camera.position.x + (Math.random() - 0.5) * 100;
        arr[i3 + 2] = camera.position.z + (Math.random() - 0.5) * 100;
      }
      if (Math.abs(arr[i3] - camera.position.x) > 60) arr[i3] = camera.position.x + (Math.random() - 0.5) * 90;
      if (Math.abs(arr[i3 + 2] - camera.position.z) > 60) arr[i3 + 2] = camera.position.z + (Math.random() - 0.5) * 90;
    }
    weather.points.geometry.attributes.position.needsUpdate = true;

    // Lava pulsante
    if (lava.length) {
      const pulse = 0.8 + Math.sin(t * 2.2) * 0.12;
      for (let i = 0; i < lava.length; i++) {
        lava[i].material.opacity = (map.lava ? 0.82 : 0.4) * pulse;
      }
      if (ctx.crater) ctx.crater.material.opacity = 0.65 + Math.sin(t * 3) * 0.2;
    }

    // Fumarola del volcán
    if (ctx.smokeOrigin && !ctx.smoke) {
      const n = 70;
      const g = new THREE.BufferGeometry();
      const p = new Float32Array(n * 3);
      for (let i = 0; i < n; i++) {
        p[i * 3] = ctx.smokeOrigin.x + (Math.random() - 0.5) * 8;
        p[i * 3 + 1] = ctx.smokeOrigin.y + Math.random() * 25;
        p[i * 3 + 2] = ctx.smokeOrigin.z + (Math.random() - 0.5) * 8;
      }
      g.setAttribute('position', new THREE.BufferAttribute(p, 3));
      ctx.smoke = new THREE.Points(g, new THREE.PointsMaterial({
        color: map.lava ? 0x4a4038 : 0x6a6a66, size: 5, transparent: true, opacity: 0.35, depthWrite: false,
      }));
      ctx.smoke.frustumCulled = false;
      scene.add(ctx.smoke);
    }
    if (ctx.smoke) {
      const p = ctx.smoke.geometry.attributes.position.array;
      for (let i = 0; i < p.length / 3; i++) {
        p[i * 3 + 1] += dt * 3;
        p[i * 3] += dt * 1.2;
        if (p[i * 3 + 1] > ctx.smokeOrigin.y + 30) {
          p[i * 3] = ctx.smokeOrigin.x + (Math.random() - 0.5) * 8;
          p[i * 3 + 1] = ctx.smokeOrigin.y;
          p[i * 3 + 2] = ctx.smokeOrigin.z + (Math.random() - 0.5) * 8;
        }
      }
      ctx.smoke.geometry.attributes.position.needsUpdate = true;
    }
  }

  function setEruption(on) {
    for (const m of lava) {
      m.material.color.set(on ? 0xff6a1f : 0x3a1a14);
      m.material.opacity = on ? 0.95 : 0.45;
    }
    if (ctx.crater) ctx.crater.material.color.set(on ? 0xff7a1f : 0x552222);
  }

  return {
    group, heightAt, groundAt, colliders, lootSpots, chickenSpots, gasMaskSpots,
    update, segmentHit, resolveCollisions, setEruption, weather,
    dispose() {
      scene.remove(group);
      scene.remove(weather.points);
      if (ctx.smoke) scene.remove(ctx.smoke);
      scene.fog = null;
      scene.background = null;
      scene.traverse((o) => {
        if (o.isMesh || o.isPoints) {
          o.geometry?.dispose?.();
          if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
          else o.material?.dispose?.();
        }
      });
    },
  };
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';

/* Utilidades de geometría coloreada */
function paint(geo, color) {
  const c = new THREE.Color(color);
  const n = geo.attributes.position.count;
  const arr = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { arr[i * 3] = c.r; arr[i * 3 + 1] = c.g; arr[i * 3 + 2] = c.b; }
  geo.setAttribute('color', new THREE.BufferAttribute(arr, 3));
  return geo;
}
function box(w, h, d, x, y, z, color, rx = 0, ry = 0, rz = 0) {
  const g = new THREE.BoxGeometry(w, h, d);
  paint(g, color);
  if (rx) g.rotateX(rx); if (ry) g.rotateY(ry); if (rz) g.rotateZ(rz);
  g.translate(x, y, z);
  return g;
}
function sph(r, x, y, z, color, sx = 1, sy = 1, sz = 1) {
  const g = new THREE.IcosahedronGeometry(r, 1);
  paint(g, color);
  g.scale(sx, sy, sz);
  g.translate(x, y, z);
  return g;
}
function cone(r, h, x, y, z, color, rx = 0, ry = 0, rz = 0, seg = 6) {
  const g = new THREE.ConeGeometry(r, h, seg);
  paint(g, color);
  if (rx) g.rotateX(rx); if (ry) g.rotateY(ry); if (rz) g.rotateZ(rz);
  g.translate(x, y, z);
  return g;
}
function cyl(rt, rb, h, x, y, z, color, seg = 6, rx = 0, rz = 0) {
  const g = new THREE.CylinderGeometry(rt, rb, h, seg);
  paint(g, color);
  if (rx) g.rotateX(rx); if (rz) g.rotateZ(rz);
  g.translate(x, y, z);
  return g;
}
function mergeMesh(list, mat) {
  const geo = mergeGeometries(list, false);
  const mesh = new THREE.Mesh(geo, mat);
  return mesh;
}

const FUR = {
  miguel: '#d9894a',
  miguelDark: '#b5652f',
  cream: '#f2d9b0',
  vest: '#3c4a34',
  vestDark: '#2a3526',
  strap: '#1d241a',
  glove: '#ff7a2f',
  claw: '#d9d9d9',
};

export function furPalette(seed = 0) {
  const palettes = [
    { fur: '#d9894a', dark: '#b5652f', cream: '#f2d9b0' },
    { fur: '#8f8f96', dark: '#6a6a72', cream: '#e8e2d4' },
    { fur: '#2f2b2a', dark: '#1c1918', cream: '#b9aa98' },
    { fur: '#e8dfd0', dark: '#c4b8a4', cream: '#fff6e8' },
    { fur: '#b06a3a', dark: '#7d4422', cream: '#f0d0a8' },
    { fur: '#6b5a4a', dark: '#4a3d31', cream: '#d8c4a8' },
  ];
  return palettes[seed % palettes.length];
}

const VESTS = ['#3c4a34', '#3a3f4a', '#4a3a34', '#2f3a3a', '#4a4430', '#352f42'];

/* Cuerpo base (cabeza, torso, orejas, ojos) fusionado */
function bodyGeo(pal, vest, gloves, stripes = true) {
  const g = [];
  // piernas / patas se añaden aparte en el jugador
  g.push(box(0.44, 0.34, 0.3, 0, 0.52, 0, pal.fur));
  g.push(box(0.46, 0.16, 0.32, 0, 0.62, 0.01, vest));
  g.push(box(0.5, 0.07, 0.34, 0, 0.72, 0, FUR.strap));
  g.push(box(0.08, 0.38, 0.34, 0, 0.53, 0.01, FUR.strap));
  // placa táctica
  g.push(box(0.2, 0.15, 0.04, 0, 0.6, 0.17, '#6b6f5a'));
  // cabeza
  g.push(sph(0.23, 0, 0.86, 0, pal.fur, 1, 0.94, 1));
  g.push(sph(0.15, 0, 0.8, 0.1, pal.cream, 1, 0.8, 0.8));
  // hocico
  g.push(sph(0.06, 0, 0.81, 0.21, '#f7b7a0', 1.2, 0.8, 0.9));
  // nariz
  g.push(box(0.045, 0.035, 0.035, 0, 0.835, 0.255, '#3a2424'));
  // ojos
  g.push(sph(0.042, -0.085, 0.89, 0.185, '#1a1a1a', 1, 1.15, 0.7));
  g.push(sph(0.042, 0.085, 0.89, 0.185, '#1a1a1a', 1, 1.15, 0.7));
  g.push(sph(0.012, -0.08, 0.9, 0.213, '#ffffff'));
  g.push(sph(0.012, 0.09, 0.9, 0.213, '#ffffff'));
  // orejas
  g.push(cone(0.09, 0.2, -0.14, 1.02, 0, pal.fur, 0, 0, -0.16));
  g.push(cone(0.09, 0.2, 0.14, 1.02, 0, pal.fur, 0, 0, 0.16));
  g.push(cone(0.05, 0.12, -0.14, 1.0, 0.02, '#e8a8a0', 0, 0, -0.16));
  g.push(cone(0.05, 0.12, 0.14, 1.0, 0.02, '#e8a8a0', 0, 0, 0.16));
  // rayas
  if (stripes) {
    g.push(box(0.05, 0.02, 0.22, -0.1, 1.045, 0, pal.dark));
    g.push(box(0.05, 0.02, 0.22, 0.08, 1.05, 0, pal.dark));
    g.push(box(0.24, 0.04, 0.02, 0, 0.71, -0.14, pal.dark));
  }
  // guantes
  if (gloves) {
    g.push(box(0.11, 0.11, 0.12, -0.31, 0.42, 0.02, FUR.glove));
    g.push(box(0.11, 0.11, 0.12, 0.31, 0.42, 0.02, FUR.glove));
    for (let i = -1; i <= 1; i++) {
      g.push(cone(0.018, 0.1, -0.34 + i * 0.03, 0.36, 0.08, FUR.claw, 0.5, 0, 0));
      g.push(cone(0.018, 0.1, 0.28 + i * 0.03, 0.36, 0.08, FUR.claw, 0.5, 0, 0));
    }
  }
  // mochila
  g.push(box(0.26, 0.24, 0.12, 0, 0.58, -0.2, '#3a3a2e'));
  return g;
}

/* ───────────────────────── Jugador ───────────────────────── */

export function createPlayerCharacter(scene, skin) {
  const pal = { fur: FUR.miguel, dark: FUR.miguelDark, cream: FUR.cream };
  const gloves = !!skin.gloves;
  const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
  const root = new THREE.Group();
  root.name = 'miguel';
  const rig = new THREE.Group();
  root.add(rig);

  const body = mergeMesh(bodyGeo(pal, FUR.vest, gloves), mat);
  body.castShadow = false;
  rig.add(body);

  // Brazos articulados
  const armGeo = (side) => {
    const g = [];
    g.push(box(0.1, 0.26, 0.1, 0, -0.1, 0, pal.fur));
    g.push(sph(0.075, 0, -0.25, 0, gloves ? FUR.glove : pal.cream, 1, 0.9, 1));
    if (gloves) {
      g.push(cone(0.02, 0.09, 0, -0.31, 0.02, FUR.claw, 0.3, 0, 0));
    }
    const m = mergeMesh(g, mat);
    m.position.set(side * 0.29, 0.74, 0);
    return m;
  };
  const armL = armGeo(-1), armR = armGeo(1);
  rig.add(armL, armR);

  // Piernas articuladas
  const legGeo = () => {
    const g = [];
    g.push(box(0.12, 0.28, 0.13, 0, -0.13, 0, pal.fur));
    g.push(box(0.14, 0.08, 0.2, 0, -0.29, 0.03, pal.cream));
    return mergeMesh(g, mat);
  };
  const legL = legGeo(), legR = legGeo();
  legL.position.set(-0.13, 0.36, 0);
  legR.position.set(0.13, 0.36, 0);
  rig.add(legL, legR);

  // Cola animada
  const tail = new THREE.Group();
  const tailSegs = [];
  const tailMat = new THREE.MeshLambertMaterial({ color: pal.fur });
  for (let i = 0; i < 3; i++) {
    const seg = new THREE.Mesh(new THREE.CylinderGeometry(0.045 - i * 0.008, 0.05 - i * 0.008, 0.2, 5), tailMat);
    seg.position.y = 0.1;
    const pivot = new THREE.Group();
    pivot.add(seg);
    pivot.position.set(0, i === 0 ? 0 : 0.18, 0);
    pivot.rotation.x = 0.5 + i * 0.15;
    tailSegs.push(pivot);
    if (i === 0) tail.add(pivot); else tailSegs[i - 1].add(pivot);
  }
  tail.position.set(0, 0.52, -0.18);
  tail.rotation.x = -0.4;
  rig.add(tail);

  // Arma en la mano derecha
  const weaponMount = new THREE.Group();
  weaponMount.position.set(0.34, 0.45, 0.06);
  rig.add(weaponMount);
  let weaponMesh = null;
  let muzzle = new THREE.Object3D();
  muzzle.position.set(0, 0.02, 0.35);
  weaponMount.add(muzzle);

  // Sombra falsa
  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.42, 12),
    new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.28, depthWrite: false })
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = 0.03;
  root.add(shadow);

  let walkPhase = 0;
  let bob = 0;
  let swing = 0;
  let aimBlend = 0;

  function setWeapon(id) {
    if (weaponMesh) { weaponMount.remove(weaponMesh); disposeObject(weaponMesh); }
    weaponMesh = buildWeaponMesh(id);
    weaponMount.add(weaponMesh);
    muzzle.position.set(0, 0.03, weaponMesh.userData.muzzleZ || 0.35);
  }

  function update(dt, speed, grounded, aiming, attacking) {
    const moving = speed > 0.3;
    walkPhase += dt * (moving ? speed * 6.2 : 2.2);
    aimBlend += ((aiming ? 1 : 0) - aimBlend) * Math.min(1, dt * 10);
    bob += dt * (moving ? speed * 5 : 1.5);

    const legSwing = moving ? Math.sin(walkPhase) * 0.65 : 0;
    legL.rotation.x = legSwing;
    legR.rotation.x = -legSwing;
    armL.rotation.x = -legSwing * 0.7 - aimBlend * 0.9;
    armR.rotation.x = legSwing * 0.7 - aimBlend * 1.25 + (attacking ? Math.sin(performance.now() * 0.03) * 0.4 : 0);
    armL.rotation.z = -0.08;
    armR.rotation.z = 0.08 + aimBlend * 0.18;
    rig.position.y = moving ? Math.abs(Math.sin(walkPhase * 2)) * 0.025 : Math.sin(bob) * 0.008;
    rig.rotation.z = moving ? Math.sin(walkPhase) * 0.035 : 0;
    rig.rotation.x = aimBlend * 0.06;
    tail.rotation.y = Math.sin(bob * 1.4) * 0.4;
    tail.rotation.x = -0.4 + Math.sin(bob * 1.1) * 0.12;
    for (let i = 0; i < tailSegs.length; i++) tailSegs[i].rotation.z = Math.sin(bob * 1.6 + i) * 0.18;
    shadow.position.y = 0.03;
    weaponMount.rotation.x = aimBlend * -0.15;
  }

  scene.add(root);
  return {
    root, rig, weaponMount, muzzle, shadow,
    setWeapon, update,
    setGloves(on) {
      // Reconstrucción ligera al alternar variante
      body.geometry.dispose();
      body.geometry = mergeGeometries(bodyGeo(pal, FUR.vest, on), false);
    },
    getWeaponMesh: () => weaponMesh,
  };
}

/* ───────────────────────── Bots ───────────────────────── */

export function createBotMesh(scene, seed = 0, map) {
  const pal = furPalette(seed * 7 + 3);
  const vest = VESTS[seed % VESTS.length];
  const gloves = seed % 9 === 0;
  const list = bodyGeo(pal, vest, gloves, seed % 3 !== 0);
  // piernas simples fusionadas
  list.push(box(0.12, 0.3, 0.13, -0.13, 0.18, 0, pal.fur));
  list.push(box(0.12, 0.3, 0.13, 0.13, 0.18, 0, pal.fur));
  list.push(box(0.14, 0.07, 0.2, -0.13, 0.035, 0.03, pal.cream));
  list.push(box(0.14, 0.07, 0.2, 0.13, 0.035, 0.03, pal.cream));
  // cola fusionada
  list.push(cyl(0.035, 0.05, 0.34, 0, 0.5, -0.32, pal.fur, 5, 0.9, 0));
  const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
  const mesh = mergeMesh(list, mat);
  const group = new THREE.Group();
  group.add(mesh);
  // arma simplificada
  const wm = buildWeaponMesh(seed % 4 === 0 ? 'ak47' : seed % 4 === 1 ? 'mp5' : seed % 4 === 2 ? 'remington' : 'm1911');
  wm.position.set(0.3, 0.48, 0.15);
  wm.scale.setScalar(0.9);
  group.add(wm);
  scene.add(group);
  return { group, mesh, weaponMesh: wm, palette: pal, vest };
}

/* ───────────────────────── Armas low-poly ───────────────────────── */

const matCache = new Map();
function lam(color, emissive = 0x000000, ei = 0) {
  const key = `${color}-${emissive}-${ei}`;
  if (!matCache.has(key)) matCache.set(key, new THREE.MeshLambertMaterial({ color, emissive, emissiveIntensity: ei }));
  return matCache.get(key);
}
function basic(color) {
  const key = `b-${color}`;
  if (!matCache.has(key)) matCache.set(key, new THREE.MeshBasicMaterial({ color, toneMapped: false }));
  return matCache.get(key);
}
function part(geo, mat, x, y, z, rx = 0, ry = 0, rz = 0) {
  const m = new THREE.Mesh(geo, mat);
  m.position.set(x, y, z);
  m.rotation.set(rx, ry, rz);
  return m;
}

export function buildWeaponMesh(id) {
  const g = new THREE.Group();
  const dark = lam(0x24262a), metal = lam(0x555a60), wood = lam(0x7a4a28), tan = lam(0x8a7a5a);
  const glow = basic(0xff4d6d);
  let muzzleZ = 0.35;

  switch (id) {
    case 'garras': {
      const clawMat = basic(0xffb02e);
      for (let i = -1; i <= 1; i++) {
        const c = part(new THREE.ConeGeometry(0.035, 0.42, 5), clawMat, i * 0.07, 0.02, 0.16, Math.PI / 2);
        g.add(c);
      }
      g.add(part(new THREE.BoxGeometry(0.16, 0.1, 0.16), lam(0xff7a2f), 0, -0.04, 0.02));
      muzzleZ = 0.34;
      break;
    }
    case 'bate': {
      const b = part(new THREE.CylinderGeometry(0.045, 0.075, 0.8, 7), wood, 0, 0, 0.28, Math.PI / 2);
      g.add(b);
      g.add(part(new THREE.CylinderGeometry(0.055, 0.045, 0.18, 7), dark, 0, 0, -0.14, Math.PI / 2));
      g.add(part(new THREE.BoxGeometry(0.14, 0.02, 0.1), basic(0xffd166), 0, 0.07, 0.45));
      muzzleZ = 0.66;
      break;
    }
    case 'chancla': {
      g.add(part(new THREE.BoxGeometry(0.18, 0.05, 0.5), basic(0xff4d9a), 0, 0, 0.18));
      g.add(part(new THREE.BoxGeometry(0.1, 0.06, 0.16), basic(0xffb02e), 0, 0.02, 0.12));
      g.add(part(new THREE.BoxGeometry(0.02, 0.08, 0.4), basic(0xffd166), 0, 0.05, 0.2));
      muzzleZ = 0.44;
      break;
    }
    case 'chismes': {
      g.add(part(new THREE.CylinderGeometry(0.06, 0.075, 0.55, 8), metal, 0, 0, 0.18, Math.PI / 2));
      g.add(part(new THREE.CylinderGeometry(0.11, 0.11, 0.3, 8), lam(0x8a2f2f), 0, -0.12, -0.1, Math.PI / 2));
      g.add(part(new THREE.ConeGeometry(0.12, 0.18, 8), basic(0xff7a2f), 0, 0, 0.48, Math.PI / 2));
      muzzleZ = 0.58;
      break;
    }
    case 'memes': {
      g.add(part(new THREE.BoxGeometry(0.18, 0.2, 0.5), lam(0x3a3a4a), 0, 0, 0.14));
      g.add(part(new THREE.CylinderGeometry(0.07, 0.09, 0.28, 8), basic(0xb06bff), 0, 0, 0.42, Math.PI / 2));
      g.add(part(new THREE.SphereGeometry(0.08, 8, 6), glow, 0, 0, 0.5));
      muzzleZ = 0.58;
      break;
    }
    case 'rpg': case 'javelin': case 'm79': {
      g.add(part(new THREE.CylinderGeometry(0.085, 0.085, 1.0, 8), lam(0x3f4a35), 0, 0, 0.2, Math.PI / 2));
      g.add(part(new THREE.ConeGeometry(0.14, 0.3, 8), lam(0x6a3a2a), 0, 0, 0.55, Math.PI / 2));
      g.add(part(new THREE.BoxGeometry(0.06, 0.16, 0.12), dark, 0, -0.12, 0.05));
      muzzleZ = 0.7;
      break;
    }
    case 'minigun': case 'm249': case 'm60': case 'pkm': {
      g.add(part(new THREE.BoxGeometry(0.2, 0.18, 0.55), lam(0x3a3f3a), 0, 0, 0.15));
      g.add(part(new THREE.CylinderGeometry(0.06, 0.06, 0.55, 8), metal, 0, 0.01, 0.48, Math.PI / 2));
      g.add(part(new THREE.CylinderGeometry(0.12, 0.12, 0.18, 8), dark, 0, -0.1, 0.12, Math.PI / 2));
      muzzleZ = 0.78;
      break;
    }
    case 'awm': case 'barrett': case 'mosin': case 'svd': case 'vss': {
      g.add(part(new THREE.BoxGeometry(0.1, 0.12, 0.7), lam(0x3a4238), 0, 0, 0.25));
      g.add(part(new THREE.CylinderGeometry(0.035, 0.035, 0.55, 6), metal, 0, 0.02, 0.68, Math.PI / 2));
      g.add(part(new THREE.BoxGeometry(0.12, 0.12, 0.26), dark, 0, 0.1, 0.12));
      g.add(part(new THREE.CylinderGeometry(0.05, 0.05, 0.2, 8), basic(0x7ef9ff), 0, 0.11, 0.12, Math.PI / 2));
      g.add(part(new THREE.BoxGeometry(0.06, 0.18, 0.1), dark, 0, -0.12, 0.1));
      muzzleZ = 0.95;
      break;
    }
    case 'remington': case 'doblecano': case 'benelli': case 'spas': case 'aa12': {
      g.add(part(new THREE.BoxGeometry(0.13, 0.13, 0.62), wood, 0, 0, 0.2));
      g.add(part(new THREE.CylinderGeometry(0.045, 0.045, 0.5, 6), metal, 0, 0.03, 0.62, Math.PI / 2));
      g.add(part(new THREE.CylinderGeometry(0.04, 0.04, 0.4, 6), metal, 0, -0.03, 0.6, Math.PI / 2));
      muzzleZ = 0.9;
      break;
    }
    case 'uzi': case 'mp5': case 'tec9': case 'p90': case 'vector': case 'mp7': {
      g.add(part(new THREE.BoxGeometry(0.13, 0.16, 0.38), dark, 0, 0, 0.12));
      g.add(part(new THREE.CylinderGeometry(0.03, 0.03, 0.22, 6), metal, 0, 0.03, 0.38, Math.PI / 2));
      g.add(part(new THREE.BoxGeometry(0.07, 0.2, 0.08), metal, 0, -0.13, 0.1));
      muzzleZ = 0.52;
      break;
    }
    case 'ak47': case 'm4a1': case 'scar': case 'fal': case 'g36': case 'm16': case 'famas': case 'galil': {
      g.add(part(new THREE.BoxGeometry(0.11, 0.14, 0.58), lam(0x333a32), 0, 0, 0.2));
      g.add(part(new THREE.CylinderGeometry(0.028, 0.028, 0.38, 6), metal, 0, 0.03, 0.62, Math.PI / 2));
      g.add(part(new THREE.BoxGeometry(0.08, 0.22, 0.09), dark, 0, -0.15, 0.14));
      g.add(part(new THREE.BoxGeometry(0.07, 0.12, 0.16), dark, 0, 0.09, 0.22));
      muzzleZ = 0.86;
      break;
    }
    case 'deagle': case 'magnum': {
      g.add(part(new THREE.BoxGeometry(0.1, 0.13, 0.34), metal, 0, 0.02, 0.14));
      g.add(part(new THREE.BoxGeometry(0.09, 0.18, 0.1), dark, 0, -0.1, 0.02));
      muzzleZ = 0.34;
      break;
    }
    case 'katana': {
      g.add(part(new THREE.BoxGeometry(0.035, 0.045, 0.95), basic(0xd8e6f0), 0, 0.02, 0.45));
      g.add(part(new THREE.CylinderGeometry(0.03, 0.03, 0.18, 6), dark, 0, 0, -0.06, Math.PI / 2));
      muzzleZ = 0.9;
      break;
    }
    case 'cuchillo': {
      g.add(part(new THREE.BoxGeometry(0.03, 0.06, 0.32), basic(0xc8d6e0), 0, 0.02, 0.2));
      g.add(part(new THREE.BoxGeometry(0.05, 0.05, 0.12), dark, 0, 0, -0.02));
      muzzleZ = 0.36;
      break;
    }
    case 'mazo': {
      g.add(part(new THREE.CylinderGeometry(0.03, 0.035, 0.55, 6), wood, 0, 0, 0.2, Math.PI / 2));
      g.add(part(new THREE.BoxGeometry(0.18, 0.18, 0.22), metal, 0, 0, 0.48));
      muzzleZ = 0.56;
      break;
    }
    case 'palanca': {
      g.add(part(new THREE.CylinderGeometry(0.025, 0.03, 0.8, 6), lam(0x8a3a2a), 0, 0, 0.3, Math.PI / 2));
      g.add(part(new THREE.BoxGeometry(0.12, 0.05, 0.1), metal, 0, 0.04, 0.7));
      muzzleZ = 0.7;
      break;
    }
    case 'bate_beisbol': {
      g.add(part(new THREE.CylinderGeometry(0.04, 0.07, 0.72, 7), wood, 0, 0, 0.26, Math.PI / 2));
      muzzleZ = 0.62;
      break;
    }
    default: { // pistolas genéricas
      g.add(part(new THREE.BoxGeometry(0.09, 0.12, 0.3), dark, 0, 0.02, 0.12));
      g.add(part(new THREE.BoxGeometry(0.08, 0.16, 0.1), lam(0x3a3a3a), 0, -0.1, 0.02));
      muzzleZ = 0.3;
    }
  }
  g.userData.muzzleZ = muzzleZ;
  return g;
}

export function disposeObject(obj) {
  obj.traverse((o) => {
    if (o.geometry) o.geometry.dispose();
  });
}

/* Círculo de selección / sombra compartida */
export function makeShadow() {
  const m = new THREE.Mesh(
    new THREE.CircleGeometry(0.42, 10),
    new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.3, depthWrite: false })
  );
  m.rotation.x = -Math.PI / 2;
  return m;
}

/* ═══════════════════════════════════════════════════════════
   MEME·SHOTER — Battle Royale
   Interfaz arcade / meme / móvil primero
   ═══════════════════════════════════════════════════════════ */

:root {
  --bg: #0d0a12;
  --panel: rgba(20, 15, 27, 0.82);
  --panel-2: rgba(30, 22, 40, 0.9);
  --line: rgba(255, 255, 255, 0.12);
  --orange: #ff7a2f;
  --pink: #ff3ea5;
  --yellow: #ffd166;
  --green: #7dffb0;
  --cyan: #35f0ff;
  --red: #ff3b4e;
  --text: #f6efe6;
  --muted: #a99fae;
  --display: Impact, "Arial Black", "Haettenschweiler", system-ui, sans-serif;
  --body: "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }

html, body {
  width: 100%; height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--body);
  overscroll-behavior: none;
  touch-action: none;
  user-select: none;
}

#app { position: fixed; inset: 0; overflow: hidden; }
#game-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; }

.hidden { display: none !important; }

.screen {
  position: absolute; inset: 0; z-index: 20;
  display: flex; flex-direction: column;
}

/* ───────────────────────── MENÚ ───────────────────────── */

.menu-screen {
  padding: clamp(14px, 2.6vw, 34px) clamp(16px, 4vw, 64px);
  background:
    radial-gradient(ellipse at 12% 10%, rgba(255, 122, 47, 0.22), transparent 45%),
    radial-gradient(ellipse at 88% 20%, rgba(255, 62, 165, 0.18), transparent 45%),
    radial-gradient(ellipse at 50% 110%, rgba(53, 240, 255, 0.1), transparent 50%),
    linear-gradient(160deg, #120b18 0%, #0a0810 55%, #140a10 100%);
  overflow-y: auto;
  justify-content: space-between;
  gap: 12px;
}

.menu-screen::before {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background-image:
    linear-gradient(rgba(255,255,255,0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.035) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: radial-gradient(ellipse at center, #000 10%, transparent 75%);
}

.menu-scanlines {
  position: absolute; inset: 0; pointer-events: none; opacity: 0.25; z-index: 0;
  background: repeating-linear-gradient(0deg, transparent 0 2px, rgba(0,0,0,0.35) 3px 4px);
}
.menu-glow {
  position: absolute; width: 60vw; height: 60vw; max-width: 700px; max-height: 700px;
  right: -18vw; top: -22vw; border-radius: 50%; pointer-events: none;
  background: radial-gradient(circle, rgba(255,122,47,0.16), transparent 65%);
  filter: blur(20px);
}

.brand { position: relative; z-index: 2; text-align: center; flex: 0 0 auto; padding-top: 4px; }
.brand-kicker {
  display: inline-block; font-size: clamp(8px, 1.1vw, 11px); font-weight: 800;
  letter-spacing: 0.22em; color: var(--yellow); opacity: 0.9;
  border: 1px solid rgba(255, 209, 102, 0.3); border-radius: 999px;
  padding: 5px 14px; background: rgba(255, 209, 102, 0.06);
}
.logo {
  font-family: var(--display);
  font-size: clamp(44px, 9vw, 104px);
  line-height: 0.88; letter-spacing: 0.015em;
  margin: 8px 0 2px;
  color: #fff;
  text-shadow:
    0 0 0 #fff,
    4px 4px 0 #7d2b12,
    8px 8px 0 rgba(255, 122, 47, 0.28),
    0 0 40px rgba(255, 122, 47, 0.4);
  transform: skewY(-1.5deg);
}
.logo span { color: var(--orange); text-shadow: 0 0 24px rgba(255,122,47,0.9); }
.logo-sub {
  font-size: clamp(9px, 1.25vw, 13px); letter-spacing: 0.24em; color: var(--muted);
  font-weight: 700;
}
.logo-sub b { color: var(--pink); letter-spacing: 0.18em; }

.menu-grid {
  position: relative; z-index: 2;
  display: grid; grid-template-columns: minmax(0, 1.65fr) minmax(280px, 0.85fr);
  gap: clamp(12px, 1.6vw, 22px);
  width: min(1180px, 100%); margin: 0 auto;
  flex: 1 1 auto; min-height: 0;
}

.panel {
  background: linear-gradient(160deg, rgba(28, 20, 38, 0.88), rgba(14, 10, 20, 0.94));
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: clamp(12px, 1.6vw, 20px);
  position: relative;
  box-shadow: 0 18px 60px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.05);
  backdrop-filter: blur(12px);
}
.panel::after {
  content: ""; position: absolute; inset: 0; border-radius: 18px; pointer-events: none;
  background: linear-gradient(120deg, rgba(255,122,47,0.1), transparent 35%, transparent 70%, rgba(53,240,255,0.06));
}
.panel-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.panel-head h2 { font-family: var(--display); font-size: clamp(16px, 1.8vw, 22px); letter-spacing: 0.06em; font-weight: 400; }
.panel-tag {
  font-size: 9px; font-weight: 900; letter-spacing: 0.16em; color: var(--orange);
  border: 1px solid rgba(255,122,47,0.35); padding: 3px 8px; border-radius: 6px;
}

.map-list { display: flex; flex-direction: column; gap: 8px; }

.map-card {
  display: grid; grid-template-columns: 64px 1fr auto; gap: 12px; align-items: center;
  padding: 10px 12px; border-radius: 12px; cursor: pointer;
  background: rgba(255,255,255,0.025);
  border: 1px solid rgba(255,255,255,0.08);
  transition: transform 0.15s ease, border-color 0.15s, background 0.15s;
  position: relative; overflow: hidden;
}
.map-card:hover { transform: translateX(3px); border-color: rgba(255,255,255,0.2); }
.map-card.active {
  border-color: var(--accent, var(--orange));
  background: linear-gradient(90deg, color-mix(in srgb, var(--accent, #ff7a2f) 18%, transparent), rgba(255,255,255,0.02));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent, #ff7a2f) 40%, transparent), 0 6px 24px rgba(0,0,0,0.35);
}
.map-card.active::before {
  content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--accent);
}
.map-thumb {
  width: 64px; height: 52px; border-radius: 8px; position: relative; overflow: hidden;
  display: grid; place-items: center; font-size: 26px;
  background: var(--thumb, linear-gradient(160deg, #4a1d16, #1b1216));
  border: 1px solid rgba(255,255,255,0.12);
}
.map-thumb::after {
  content: ""; position: absolute; inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 7px, rgba(0,0,0,0.18) 8px 9px);
