.map-info b { display: block; font-size: 13.5px; font-weight: 800; letter-spacing: 0.02em; }
.map-info small { display: block; font-size: 10.5px; color: var(--muted); margin-top: 2px; line-height: 1.35; }
.map-hazard {
  font-size: 8.5px; font-weight: 900; letter-spacing: 0.08em; text-align: right;
  color: var(--accent); max-width: 108px; line-height: 1.3;
}
.map-hazard span { display: block; color: var(--muted); font-weight: 700; margin-top: 3px; letter-spacing: 0.02em; }

/* Skin */
