.play-text { display: flex; flex-direction: column; align-items: flex-start; }
.play-text small {
  font-family: var(--body); font-size: 8px; font-weight: 800; letter-spacing: 0.14em;
  opacity: 0.75; margin-top: 2px; text-transform: uppercase;
}
.play-btn.small { flex: none; width: 100%; font-size: 20px; padding: 12px; }
.perf-badge { font-size: 9px; color: rgba(255,255,255,0.32); letter-spacing: 0.06em; }

/* Modales */
.modal {
  position: fixed; inset: 0; z-index: 90; display: grid; place-items: center;
  background: rgba(5, 3, 8, 0.78); backdrop-filter: blur(8px); padding: 18px;
}
.modal-card {
  width: min(760px, 100%); max-height: 88vh; overflow-y: auto;
  background: linear-gradient(160deg, #1d1428, #0f0b16);
  border: 1px solid rgba(255,255,255,0.14); border-radius: 18px;
  padding: clamp(18px, 3vw, 34px); box-shadow: 0 30px 100px rgba(0,0,0,0.8);
}
.modal-card h3 { font-family: var(--display); font-size: 34px; letter-spacing: 0.05em; margin-bottom: 12px; color: var(--yellow); }
.modal-card p { font-size: 12px; line-height: 1.55; color: var(--muted); }
.how-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin: 14px 0 18px; }
.how-grid > div { background: rgba(255,255,255,0.035); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 12px; }
.how-grid b { display: block; font-size: 12px; margin-bottom: 5px; color: var(--orange); letter-spacing: 0.06em; }
.pause-card { text-align: center; width: min(380px, 100%); }
.pause-card h3 { font-size: 46px; }
.pause-card .play-btn { margin-top: 16px; }
.pause-tip { margin-top: 14px; font-size: 10px; color: rgba(255,255,255,0.35); }

/* ───────────────────────── CARGA ───────────────────────── */

.loading-screen {
  z-index: 80; display: flex; align-items: center; justify-content: center; flex-direction: column; gap: 14px;
  background: radial-gradient(ellipse at 50% 40%, #241221, #08060c 70%);
}
.load-cat { font-size: 64px; animation: loadBounce 1.2s ease-in-out infinite; filter: drop-shadow(0 0 24px rgba(255,122,47,0.6)); }
@keyframes loadBounce { 0%,100% { transform: translateY(0) rotate(-3deg); } 50% { transform: translateY(-14px) rotate(3deg); } }
.loading-screen h2 { font-family: var(--display); font-size: clamp(24px, 4vw, 40px); letter-spacing: 0.1em; color: var(--yellow); }
.load-bar { width: min(360px, 72vw); height: 8px; border-radius: 999px; background: rgba(255,255,255,0.08); overflow: hidden; border: 1px solid rgba(255,255,255,0.1); }
.load-bar i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--orange), var(--pink)); transition: width 0.3s ease; box-shadow: 0 0 18px var(--pink); }
.loading-screen p { font-size: 11px; color: var(--muted); letter-spacing: 0.08em; }

/* ───────────────────────── HUD ───────────────────────── */

.hud {
  position: absolute; inset: 0; z-index: 30; pointer-events: none;
  padding: max(10px, env(safe-area-inset-top)) max(12px, env(safe-area-inset-right)) max(10px, env(safe-area-inset-bottom)) max(12px, env(safe-area-inset-left));
  font-family: var(--body);
}
.hud button { pointer-events: auto; }

.hud-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; }
.hud-left { display: flex; gap: 6px; }
.alive-pill, .zone-pill {
  display: flex; align-items: center; gap: 6px; padding: 6px 10px; border-radius: 9px;
  background: rgba(10, 7, 15, 0.68); border: 1px solid rgba(255,255,255,0.12);
  backdrop-filter: blur(8px);
}
.alive-pill b { font-size: 17px; font-weight: 900; color: #fff; line-height: 1; }
.alive-pill small, .zone-pill small { font-size: 7px; letter-spacing: 0.12em; color: var(--muted); font-weight: 800; }
.alive-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 10px var(--green); animation: pulse 1.6s infinite; }
@keyframes pulse { 50% { opacity: 0.35; } }
.zone-pill b { font-size: 11px; letter-spacing: 0.06em; color: var(--orange); }
.zone-pill.danger b { color: var(--red); animation: blink 0.8s infinite; }
@keyframes blink { 50% { opacity: 0.4; } }

.match-info { text-align: center; padding-top: 2px; }
.match-info span { display: block; font-size: 8px; letter-spacing: 0.2em; color: rgba(255,255,255,0.5); font-weight: 800; }
.match-info b { font-family: var(--display); font-size: 20px; letter-spacing: 0.08em; color: #fff; text-shadow: 0 2px 10px rgba(0,0,0,0.7); }

.hud-right { display: flex; align-items: flex-start; gap: 6px; }
#minimap {
  width: 118px; height: 118px; border-radius: 12px; border: 1px solid rgba(255,255,255,0.18);
  background: rgba(8,6,12,0.75); box-shadow: 0 8px 30px rgba(0,0,0,0.5);
}
.icon-btn {
  width: 34px; height: 34px; border-radius: 9px; border: 1px solid rgba(255,255,255,0.14);
  background: rgba(10,7,15,0.7); color: #fff; font-size: 14px; cursor: pointer;
  backdrop-filter: blur(8px);
}

.feed {
  position: absolute; left: max(12px, env(safe-area-inset-left)); top: 62px;
  width: min(330px, 42vw); display: flex; flex-direction: column; gap: 3px;
  pointer-events: none;
}
.feed-line {
  font-size: 10px; line-height: 1.35; color: rgba(255,255,255,0.78);
  background: linear-gradient(90deg, rgba(8,6,12,0.72), transparent);
  padding: 4px 8px; border-left: 2px solid rgba(255,255,255,0.18);
  animation: feedIn 0.2s ease; text-shadow: 0 1px 3px #000;
  max-width: 100%;
}
.feed-line b { color: var(--yellow); font-weight: 800; }
.feed-line.event { border-left-color: var(--pink); color: #ffd9ec; }
.feed-line.meteor { border-left-color: var(--orange); color: #ffe3c9; }
.feed-line.chicken { border-left-color: var(--yellow); color: #fff4c9; }
.feed-line.pigeon { border-left-color: var(--cyan); color: #d8fdff; }
@keyframes feedIn { from { opacity: 0; transform: translateX(-8px); } }

.killfeed {
  position: absolute; right: max(12px, env(safe-area-inset-right)); top: 170px;
  width: min(300px, 40vw); display: flex; flex-direction: column; gap: 3px; align-items: flex-end;
}
.kill-line {
  font-size: 9.5px; color: rgba(255,255,255,0.7); background: rgba(8,6,12,0.62);
  padding: 3px 8px; border-radius: 5px; border: 1px solid rgba(255,255,255,0.08);
  animation: feedIn 0.2s ease; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%;
}
.kill-line b { color: #fff; }
.kill-line .wep { color: var(--orange); font-weight: 800; }

.event-banner {
  position: absolute; top: 14%; left: 50%; transform: translateX(-50%);
  text-align: center; padding: 10px 26px; border-radius: 10px;
  background: linear-gradient(90deg, transparent, rgba(10,7,15,0.86) 20%, rgba(10,7,15,0.86) 80%, transparent);
  border-top: 1px solid rgba(255,255,255,0.12); border-bottom: 1px solid rgba(255,255,255,0.12);
  animation: bannerIn 0.3s ease;
  max-width: 90vw;
}
.event-banner b { display: block; font-family: var(--display); font-size: clamp(20px, 3vw, 34px); letter-spacing: 0.07em; color: var(--yellow); text-shadow: 0 0 30px rgba(255,209,102,0.5); }
.event-banner span { display: block; font-size: 10px; letter-spacing: 0.14em; color: var(--muted); font-weight: 700; margin-top: 2px; }
@keyframes bannerIn { from { opacity: 0; transform: translate(-50%, -8px) scale(0.96); } }

.drop-info {
  position: absolute; top: 22%; left: 50%; transform: translateX(-50%); text-align: center;
  padding: 10px 22px; border-radius: 10px; background: rgba(8,6,12,0.7);
  border: 1px solid rgba(255,255,255,0.14); backdrop-filter: blur(6px);
}
.drop-info b { display: block; font-family: var(--display); font-size: 22px; letter-spacing: 0.1em; color: var(--cyan); }
.drop-info span { font-size: 11px; color: var(--muted); letter-spacing: 0.1em; }

/* crosshair */
.crosshair {
  position: absolute; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%, -50%);
  transition: opacity 0.15s; opacity: 0.9;
}
.ch-dot { position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; margin: -1.5px; border-radius: 50%; background: #fff; box-shadow: 0 0 4px #000; }
.ch-l, .ch-r, .ch-t, .ch-b { position: absolute; background: rgba(255,255,255,0.85); box-shadow: 0 0 3px #000; }
.ch-l, .ch-r { top: 50%; width: 6px; height: 1.5px; margin-top: -0.75px; }
.ch-l { left: 0; } .ch-r { right: 0; }
.ch-t, .ch-b { left: 50%; width: 1.5px; height: 6px; margin-left: -0.75px; }
.ch-t { top: 0; } .ch-b { bottom: 0; }
.crosshair.hit .ch-dot { background: var(--red); transform: scale(2.2); }
.hitmarker {
  position: absolute; inset: -8px; display: grid; place-items: center;
  font-size: 20px; color: var(--red); opacity: 0; font-weight: 900;
  transition: opacity 0.08s; text-shadow: 0 0 8px rgba(255,59,78,0.8);
}
.crosshair.hit .hitmarker { opacity: 1; }

.hud-bottom {
  position: absolute; left: max(12px, env(safe-area-inset-left)); right: max(12px, env(safe-area-inset-right));
  bottom: max(10px, env(safe-area-inset-bottom));
  display: flex; align-items: flex-end; justify-content: space-between; gap: 12px;
}
.health-panel {
  width: min(320px, 42vw); padding: 9px 11px; border-radius: 12px;
  background: linear-gradient(160deg, rgba(14,10,20,0.88), rgba(10,7,15,0.72));
  border: 1px solid rgba(255,255,255,0.12); backdrop-filter: blur(10px);
  box-shadow: 0 10px 30px rgba(0,0,0,0.4);
}
.health-head { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
.avatar { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; font-size: 18px; background: rgba(255,122,47,0.14); border: 1px solid rgba(255,122,47,0.3); }
.health-head > div:nth-child(2) { flex: 1; min-width: 0; }
.health-head b { display: block; font-size: 10px; letter-spacing: 0.12em; color: #fff; }
.health-head small { display: block; font-size: 7px; letter-spacing: 0.1em; color: var(--muted); }
.hp-num { text-align: right; }
.hp-num b { font-family: var(--display); font-size: 25px; line-height: 1; color: var(--green); }
.hp-num span { display: block; font-size: 7px; color: var(--muted); letter-spacing: 0.08em; }
.hp-track { height: 9px; border-radius: 999px; background: rgba(255,255,255,0.08); overflow: hidden; position: relative; border: 1px solid rgba(255,255,255,0.07); }
.hp-track i { position: absolute; inset: 0; width: 100%; border-radius: 999px; background: linear-gradient(90deg, #3ad17a, var(--green)); transition: width 0.18s ease, background 0.3s; box-shadow: 0 0 14px rgba(125,255,176,0.5); }
.hp-track em { position: absolute; inset: 0; width: 100%; background: rgba(255,255,255,0.35); transition: width 0.6s ease 0.15s; border-radius: 999px; opacity: 0.35; }
.hp-track.low i { background: linear-gradient(90deg, #ff3b4e, #ff7a2f); box-shadow: 0 0 14px rgba(255,59,78,0.5); }
.status-row { display: flex; gap: 4px; margin-top: 6px; flex-wrap: wrap; }
.status-chip {
  font-size: 7.5px; font-weight: 800; letter-spacing: 0.06em; padding: 2px 6px; border-radius: 4px;
  background: rgba(255,255,255,0.05); color: var(--muted); border: 1px solid rgba(255,255,255,0.08);
}
.status-chip.danger { color: #ffb3bb; border-color: rgba(255,59,78,0.35); background: rgba(255,59,78,0.1); }

.weapon-panel {
  width: min(310px, 44vw); padding: 8px; border-radius: 12px;
  background: linear-gradient(160deg, rgba(14,10,20,0.9), rgba(10,7,15,0.74));
  border: 1px solid rgba(255,255,255,0.12); backdrop-filter: blur(10px);
  box-shadow: 0 10px 30px rgba(0,0,0,0.4);
}
.weapon-slots { display: flex; gap: 4px; margin-bottom: 6px; }
.wslot {
  flex: 1; height: 22px; border-radius: 5px; display: flex; align-items: center; gap: 4px;
  padding: 0 5px; font-size: 8px; color: var(--muted); background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.07); overflow: hidden; white-space: nowrap;
}
.wslot.active { background: rgba(255,122,47,0.16); border-color: rgba(255,122,47,0.5); color: #fff; }
.wslot b { font-size: 10px; }
.wslot i { font-style: normal; overflow: hidden; text-overflow: ellipsis; }
.weapon-main { display: flex; align-items: center; gap: 7px; }
.weapon-icon {
  width: 34px; height: 34px; border-radius: 8px; display: grid; place-items: center; font-size: 21px;
  background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.08);
}
.weapon-meta { flex: 1; min-width: 0; }
.weapon-meta b { display: block; font-size: 10.5px; letter-spacing: 0.02em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.weapon-meta small { display: block; font-size: 7px; color: var(--muted); letter-spacing: 0.1em; margin-top: 1px; }
.ammo { margin-top: 1px; }
.ammo b { display: inline; font-family: var(--display); font-size: 19px; color: var(--yellow); }
.ammo span { font-size: 9px; color: var(--muted); }
.ammo i { font-style: normal; }
.reload-btn {
  width: 30px; height: 30px; border-radius: 7px; border: 1px solid rgba(255,255,255,0.12);
  background: rgba(255,255,255,0.05); color: #fff; font-size: 16px; cursor: pointer;
  display: flex; flex-direction: column; align-items: center; justify-content: center; line-height: 0.8;
}
.reload-btn small { font-size: 6px; color: var(--muted); }
.special-row { margin-top: 5px; }
.special-btn {
  width: 100%; display: flex; align-items: center; gap: 6px; padding: 5px 7px; border-radius: 7px;
  background: linear-gradient(90deg, rgba(255,77,109,0.14), rgba(255,255,255,0.03));
  border: 1px solid rgba(255,77,109,0.28); color: #fff; cursor: pointer;
  position: relative; overflow: hidden; text-align: left;
}
.special-btn:disabled { opacity: 0.42; cursor: not-allowed; }
.special-btn > span:first-child { font-size: 14px; }
.special-txt { flex: 1; min-width: 0; }
.special-txt b { display: block; font-size: 8px; letter-spacing: 0.06em; color: #ffd0da; }
.special-txt small { display: block; font-size: 6.5px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.special-btn .cd { position: absolute; inset: 0; width: 0%; background: rgba(0,0,0,0.55); pointer-events: none; }
.special-btn.ready { box-shadow: 0 0 14px rgba(255,77,109,0.3); }

.interact-prompt {
  position: absolute; left: 50%; bottom: 26%; transform: translateX(-50%);
  padding: 7px 14px; border-radius: 8px; font-size: 11px; font-weight: 700;
  background: rgba(8,6,12,0.8); border: 1px solid rgba(255,255,255,0.18);
  backdrop-filter: blur(6px); display: flex; align-items: center; gap: 7px;
}
.interact-prompt kbd {
  font-family: var(--body); font-size: 9px; background: #fff; color: #111; border-radius: 3px;
  padding: 2px 5px; font-weight: 900;
}
.toast {
  position: absolute; left: 50%; bottom: 32%; transform: translateX(-50%) translateY(8px);
  padding: 7px 16px; border-radius: 8px; font-size: 11px; font-weight: 800;
  background: rgba(8,6,12,0.86); border: 1px solid rgba(255,255,255,0.16);
  opacity: 0; transition: all 0.2s; pointer-events: none; white-space: nowrap;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

.vignette {
  position: absolute; inset: 0; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 45%, rgba(255,20,40,0.55) 100%);
  transition: opacity 0.15s;
}
.vignette.hurt { opacity: 1; }
.vignette.zone { opacity: 0.7; background: radial-gradient(ellipse at center, transparent 40%, rgba(120,255,90,0.25) 100%); }

.float-layer { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.dmg-float {
  position: absolute; font-family: var(--display); font-size: 20px; color: #fff;
  text-shadow: 0 2px 0 #000, 0 0 10px rgba(0,0,0,0.8); transform: translate(-50%, -50%);
  will-change: transform, opacity; white-space: nowrap;
}
.dmg-float.crit { color: var(--yellow); font-size: 28px; }
.dmg-float.heal { color: var(--green); font-size: 16px; }
.dmg-float.meteor { color: var(--orange); }

/* ───────────────────────── CONTROLES TÁCTILES ───────────────────────── */

.touch-ui { position: absolute; inset: 0; pointer-events: none; }
.joystick {
  position: absolute; left: 22px; bottom: 118px; width: 104px; height: 104px; border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,0.18); background: rgba(10,7,15,0.35);
  pointer-events: auto; touch-action: none; backdrop-filter: blur(3px);
}
.stick {
  position: absolute; left: 50%; top: 50%; width: 44px; height: 44px; margin: -22px 0 0 -22px;
  border-radius: 50%; background: radial-gradient(circle at 35% 30%, #ffb27a, #ff7a2f 60%, #b23a12);
  border: 1px solid rgba(255,255,255,0.4); box-shadow: 0 4px 18px rgba(0,0,0,0.5);
}
.look-zone { position: absolute; right: 0; top: 15%; width: 52%; height: 55%; pointer-events: auto; touch-action: none; }
.touch-actions { position: absolute; right: 16px; bottom: 16px; width: 196px; height: 178px; pointer-events: none; }
.tbtn {
  position: absolute; border-radius: 50%; border: 1.5px solid rgba(255,255,255,0.22);
  background: rgba(14,10,20,0.62); color: #fff; font-size: 19px; pointer-events: auto;
  display: grid; place-items: center; backdrop-filter: blur(6px);
  box-shadow: 0 4px 16px rgba(0,0,0,0.4); touch-action: none;
}
.tbtn:active { background: rgba(255,255,255,0.2); transform: scale(0.94); }
.tbtn.fire { width: 78px; height: 78px; right: 0; bottom: 0; font-size: 30px; background: radial-gradient(circle at 35% 30%, rgba(255,120,80,0.95), rgba(210,30,50,0.9)); border-color: rgba(255,180,160,0.5); }
.tbtn.jump { width: 48px; height: 48px; right: 86px; bottom: 10px; }
.tbtn.reload { width: 42px; height: 42px; right: 4px; bottom: 86px; }
.tbtn.swap { width: 42px; height: 42px; right: 52px; bottom: 92px; }
.tbtn.special { width: 44px; height: 44px; right: 98px; bottom: 64px; font-size: 17px; border-color: rgba(255,77,109,0.5); }
.tbtn.aim { width: 42px; height: 42px; right: 142px; bottom: 18px; }
.tbtn.pickup { width: 42px; height: 42px; right: 140px; bottom: 74px; }

/* ───────────────────────── FIN ───────────────────────── */

.end-screen {
  z-index: 70; display: flex; align-items: center; justify-content: center;
  background: radial-gradient(ellipse at 50% 40%, rgba(60,20,20,0.55), rgba(5,3,8,0.94) 70%);
  backdrop-filter: blur(10px); padding: 20px;
}
.end-card {
  width: min(480px, 100%); text-align: center; padding: clamp(20px, 4vw, 36px);
  background: linear-gradient(160deg, #1e1428, #0d0912);
  border: 1px solid rgba(255,255,255,0.14); border-radius: 20px;
  box-shadow: 0 30px 120px rgba(0,0,0,0.8); position: relative; overflow: hidden;
}
.end-card::before {
  content: ""; position: absolute; top: -100px; left: 50%; transform: translateX(-50%);
  width: 300px; height: 200px; background: radial-gradient(ellipse, rgba(255,122,47,0.35), transparent 70%);
  pointer-events: none;
}
.end-kicker { font-size: 9px; letter-spacing: 0.24em; color: var(--muted); font-weight: 900; }
.end-card h2 { font-family: var(--display); font-size: clamp(38px, 8vw, 64px); letter-spacing: 0.04em; margin: 4px 0; color: var(--orange); text-shadow: 0 0 40px rgba(255,122,47,0.5); position: relative; }
.end-card h2.win { color: var(--yellow); text-shadow: 0 0 50px rgba(255,209,102,0.7); }
.end-card > p { font-size: 12px; color: var(--muted); }
.end-place { margin: 14px 0; display: flex; flex-direction: column; align-items: center; }
.end-place b { font-family: var(--display); font-size: 44px; line-height: 1; color: #fff; }
.end-place span { font-size: 8px; letter-spacing: 0.22em; color: var(--muted); }
.end-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin: 14px 0; }
.end-stats div { background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.08); border-radius: 9px; padding: 8px 3px; }
.end-stats b { display: block; font-family: var(--display); font-size: 22px; color: var(--yellow); line-height: 1; }
.end-stats span { font-size: 7px; letter-spacing: 0.12em; color: var(--muted); }
.end-reason { font-size: 10.5px; color: rgba(255,255,255,0.6); background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.07); border-radius: 7px; padding: 7px 10px; margin-bottom: 14px; }
.end-actions { display: flex; flex-direction: column; gap: 6px; }

/* ───────────────────────── RESPONSIVE ───────────────────────── */

@media (max-width: 900px) {
  .menu-grid { grid-template-columns: 1fr; }
  .skin-panel { display: none; }
  .menu-screen { justify-content: flex-start; gap: 14px; padding-bottom: 18px; }
  .map-info small { display: none; }
  .map-card { grid-template-columns: 54px 1fr auto; padding: 8px 10px; }
  .map-thumb { width: 54px; height: 44px; font-size: 22px; }
  .brand-kicker { font-size: 7px; }
  .menu-bottom { margin-top: auto; }
  .feature-strip { display: none; }
  .logo-sub { font-size: 8px; letter-spacing: 0.15em; }
}

@media (max-width: 640px) {
  #minimap { width: 92px; height: 92px; }
  .health-panel { width: 47vw; padding: 7px 8px; }
  .weapon-panel { width: 47vw; padding: 6px; }
  .hud-bottom { gap: 6px; }
  .health-head b { font-size: 9px; }
  .hp-num b { font-size: 21px; }
  .weapon-meta b { font-size: 9px; }
  .weapon-icon { width: 28px; height: 28px; font-size: 17px; }
  .ammo b { font-size: 16px; }
  .feed { width: 52vw; top: 56px; }
  .killfeed { top: 140px; width: 46vw; }
  .special-txt small { display: none; }
  .status-chip { font-size: 6.5px; }
  .hud-top { align-items: flex-start; }
  .match-info span { display: none; }
  .match-info b { font-size: 16px; }
  .alive-pill, .zone-pill { padding: 4px 7px; }
  .alive-pill b { font-size: 14px; }
  .zone-pill b { font-size: 9px; }
  .drop-info { top: 18%; }
}

@media (max-height: 620px) and (orientation: landscape) {
  .menu-screen { padding-top: 8px; gap: 6px; }
  .logo { font-size: 46px; }
  .brand-kicker { display: none; }
  .map-card { padding: 5px 8px; }
  .map-thumb { height: 36px; }
  .skin-stage { min-height: 110px; }
  .menu-bottom { gap: 4px; }
  .feature-strip { display: none; }
  .joystick { bottom: 92px; width: 88px; height: 88px; }
  .stick { width: 38px; height: 38px; margin: -19px 0 0 -19px; }
}

@media (pointer: coarse) {
  .reload-btn small { display: none; }
}

// Entrada unificada: teclado + ratón (pointer lock) + táctil (joystick, look, botones)

export class Input {
  constructor(canvas, opts = {}) {
    this.canvas = canvas;
    this.onPause = opts.onPause || (() => {});
    this.onFirstLock = opts.onFirstLock || (() => {});
    this.touch = matchMedia('(pointer: coarse)').matches || (navigator.maxTouchPoints > 0 && innerWidth < 1024);
    this.keys = new Set();
    this.lookX = 0; this.lookY = 0;
    this.firing = false;
    this.aiming = false;
    this.locked = false;
    this.enabled = false;
    this.pressed = { jump: false, reload: false, swap: false, special: false, interact: false, pause: false };
    this.moveX = 0; this.moveY = 0;
    this.joystickActive = false;
    this.lookPointer = null;
    this.stickPointer = null;
    this.bindKeyboard();
    this.bindMouse();
    this.bindTouch();
    this.applyTouchVisibility();
  }

  applyTouchVisibility() {
    const ui = document.getElementById('touch-ui');
    if (ui) ui.classList.toggle('hidden', !this.touch);
    document.body.classList.toggle('is-touch', this.touch);
  }

  setEnabled(on) {
    this.enabled = on;
    if (!on) {
      this.firing = false;
      this.aiming = false;
      this.moveX = this.moveY = 0;
      this.keys.clear();
      this.releaseStick();
    }
  }

  requestLock() {
    if (this.touch) return;
    if (document.pointerLockElement !== this.canvas) {
      this.canvas.requestPointerLock?.();
    }
  }

  bindKeyboard() {
    addEventListener('keydown', (e) => {
      if (!this.enabled) return;
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault();
      if (e.repeat) return;
      this.keys.add(e.code);
      switch (e.code) {
        case 'Space': this.pressed.jump = true; break;
        case 'KeyR': this.pressed.reload = true; break;
        case 'KeyE': this.pressed.interact = true; break;
        case 'KeyQ': this.pressed.special = true; break;
        case 'Digit1': this.swapTo = 0; break;
        case 'Digit2': this.swapTo = 1; break;
        case 'Digit3': this.swapTo = 2; break;
        case 'KeyX': this.pressed.swap = true; break;
        case 'Escape': this.pressed.pause = true; break;
        case 'KeyP': this.pressed.pause = true; break;
        case 'KeyM': this.aiming = !this.aiming; break;
        case 'KeyH': this.pressed.interact = true; break;
      }
    });
    addEventListener('keyup', (e) => this.keys.delete(e.code));
    addEventListener('blur', () => { this.keys.clear(); this.firing = false; });
    addEventListener('wheel', (e) => {
      if (!this.enabled) return;
      this.pressed.swap = true;
      this.swapDir = e.deltaY > 0 ? 1 : -1;
    }, { passive: true });
  }

  bindMouse() {
    this.canvas.addEventListener('mousedown', (e) => {
      if (!this.enabled || this.touch) return;
      if (!this.locked) { this.requestLock(); return; }
      if (e.button === 0) this.firing = true;
      if (e.button === 2) this.aiming = true;
    });
    addEventListener('mouseup', (e) => {
      if (e.button === 0) this.firing = false;
      if (e.button === 2) this.aiming = false;
    });
    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
    addEventListener('mousemove', (e) => {
      if (!this.enabled || this.touch || !this.locked) return;
      this.lookX += e.movementX || 0;
      this.lookY += e.movementY || 0;
    });
    document.addEventListener('pointerlockchange', () => {
      this.locked = document.pointerLockElement === this.canvas;
      if (this.locked) {
        this.onFirstLock();
      } else if (this.enabled && !this.touch) {
        this.onPause();
      }
    });
  }

  bindTouch() {
    const joy = document.getElementById('joystick');
    const stick = document.getElementById('stick');
    const look = document.getElementById('look-zone');
    if (!joy || !stick || !look) return;
    const R = 52;

    const moveStick = (e) => {
      const r = joy.getBoundingClientRect();
      const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
      let dx = e.clientX - cx, dy = e.clientY - cy;
      const d = Math.hypot(dx, dy) || 1;
      const max = r.width * 0.38;
      if (d > max) { dx = (dx / d) * max; dy = (dy / d) * max; }
      stick.style.transform = `translate(${dx}px, ${dy}px)`;
      this.moveX = dx / max;
      this.moveY = dy / max;
    };
    joy.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return;
      e.preventDefault();
      this.stickPointer = e.pointerId;
      joy.setPointerCapture?.(e.pointerId);
      moveStick(e);
    });
    joy.addEventListener('pointermove', (e) => {
      if (e.pointerId !== this.stickPointer) return;
      e.preventDefault();
      moveStick(e);
    });
    const endStick = (e) => {
      if (e.pointerId !== this.stickPointer) return;
      this.releaseStick();
    };
    joy.addEventListener('pointerup', endStick);
    joy.addEventListener('pointercancel', endStick);

    look.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return;
      e.preventDefault();
      this.lookPointer = e.pointerId;
      look.setPointerCapture?.(e.pointerId);
      this.lastLook = { x: e.clientX, y: e.clientY };
    });
    look.addEventListener('pointermove', (e) => {
      if (e.pointerId !== this.lookPointer) return;
      e.preventDefault();
      const dx = e.clientX - this.lastLook.x;
      const dy = e.clientY - this.lastLook.y;
      this.lastLook = { x: e.clientX, y: e.clientY };
      const sens = 0.42;
      this.lookX += dx * sens;
      this.lookY += dy * sens;
    });
    const endLook = (e) => {
      if (e.pointerId === this.lookPointer) this.lookPointer = null;
    };
    look.addEventListener('pointerup', endLook);
    look.addEventListener('pointercancel', endLook);

    const hold = (id, on, off) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.addEventListener('pointerdown', (e) => {
        if (!this.enabled) return;
        e.preventDefault();
        e.stopPropagation();
        on(e);
      });
      const up = (e) => { e.preventDefault(); off?.(e); };
      el.addEventListener('pointerup', up);
      el.addEventListener('pointercancel', up);
      el.addEventListener('pointerleave', up);
    };
    hold('btn-fire', () => { this.firing = true; }, () => { this.firing = false; });
    hold('btn-jump', () => { this.pressed.jump = true; });
    hold('btn-reload', () => { this.pressed.reload = true; });
    hold('btn-swap', () => { this.pressed.swap = true; this.swapDir = 1; });
    hold('btn-special', () => { this.pressed.special = true; });
    hold('btn-pickup', () => { this.pressed.interact = true; });
    hold('btn-aim', () => { this.aiming = !this.aiming; });

    // Bloquear gestos del navegador
    document.addEventListener('gesturestart', (e) => e.preventDefault());
    document.addEventListener('dblclick', (e) => e.preventDefault(), { passive: false });
  }

  releaseStick() {
    this.stickPointer = null;
    this.joystickActive = false;
    this.moveX = 0; this.moveY = 0;
    const stick = document.getElementById('stick');
    if (stick) stick.style.transform = 'translate(0px, 0px)';
  }

  sample() {
    // Movimiento: teclado + joystick
    let mx = 0, my = 0;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) my -= 1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) my += 1;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) mx -= 1;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) mx += 1;
    if (this.touch) { mx += this.moveX; my += this.moveY; }
    const len = Math.hypot(mx, my);
    if (len > 1) { mx /= len; my /= len; }

    const s = {
      moveX: mx, moveY: my,
      lookX: this.lookX, lookY: this.lookY,
      firing: this.firing,
      aiming: this.aiming,
      sprint: this.keys.has('ShiftLeft') || this.keys.has('ShiftRight'),
      jump: this.pressed.jump,
      reload: this.pressed.reload,
      swap: this.pressed.swap,
      swapDir: this.swapDir || 1,
      special: this.pressed.special,
      interact: this.pressed.interact,
      pause: this.pressed.pause,
      swapTo: this.swapTo,
    };
    this.lookX = 0; this.lookY = 0;
    this.pressed = { jump: false, reload: false, swap: false, special: false, interact: false, pause: false };
    this.swapTo = undefined; this.swapDir = undefined;
    return s;
  }
}

import * as THREE from 'three';
import { RARITY } from '../data/weapons.js';

const $ = (id) => document.getElementById(id);
const fmtTime = (s) => {
  s = Math.max(0, Math.floor(s));
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
};

export class HUD {
  constructor({ map, skin, world }) {
    this.map = map;
    this.skin = skin;
    this.world = world;
    this.el = {
      hud: $('hud'), feed: $('feed'), killfeed: $('killfeed'),
      alive: $('alive-count'), timer: $('match-timer'), mapName: $('map-name'),
      zonePill: $('zone-pill'), zoneLabel: $('zone-label'), zoneTimer: $('zone-timer'), zoneIcon: $('zone-icon'),
      hpValue: $('hp-value'), hpFill: $('hp-fill'), hpLag: $('hp-lag'), hpTrack: document.querySelector('.hp-track'),
      weaponIcon: $('weapon-icon'), weaponName: $('weapon-name'), weaponCat: $('weapon-cat'),
      ammoMag: $('ammo-mag'), ammoReserve: $('ammo-reserve'), weaponSlots: $('weapon-slots'),
      specialBtn: $('special-btn'), specialIcon: $('special-icon'), specialName: $('special-name'),
      specialDesc: $('special-desc'), specialCd: $('special-cd'),
      prompt: $('interact-prompt'), promptText: $('interact-text'),
      toast: $('toast'), vignette: $('vignette'), floatLayer: $('float-layer'),
      banner: $('event-banner'), bannerTitle: $('event-title'), bannerSub: $('event-sub'),
      drop: $('drop-info'), altitude: $('altitude'),
      crosshair: $('crosshair'), hitmarker: $('hitmarker'),
      statusGloves: $('status-gloves'), statusZone: $('status-zone'),
      statusMask: $('status-mask'), statusChickens: $('status-chickens'),
      playerName: $('player-name'), skinTag: $('skin-tag'),
      minimap: $('minimap'),
    };
    this.mctx = this.el.minimap.getContext('2d');
    this.floats = [];
    this.feedLines = [];
    this.bannerTimer = 0;
    this.toastTimer = 0;
    this.hitTimer = 0;
    this.minimapT = 0;
    this.el.mapName.textContent = map.name.toUpperCase();
    this.el.zoneIcon.textContent = map.emoji;
    this.el.zoneLabel.textContent = map.zoneName;
    this.el.playerName.textContent = skin.gloves ? 'MIGUEL FURIOSO' : 'MIGUEL';
    this.el.skinTag.textContent = skin.gloves ? 'FURIA GATUNA · GUANTES' : 'EL PANA DE SIEMPRE';
    this.el.statusGloves.textContent = skin.gloves ? '🥊 FURIA +15%' : '🐾 SIN GUANTES';
    this.el.statusGloves.style.display = '';
    this.lastHp = 1000;
  }

  show() { this.el.hud.classList.remove('hidden'); }
  hide() { this.el.hud.classList.add('hidden'); }

  setDrop(alt) {
    if (alt == null) { this.el.drop.classList.add('hidden'); return; }
    this.el.drop.classList.remove('hidden');
    this.el.altitude.textContent = `${Math.max(0, Math.round(alt))} m`;
  }

  chat(text, type = '') {
    const line = document.createElement('div');
    line.className = `feed-line ${type}`;
    line.innerHTML = text;
    this.el.feed.appendChild(line);
    this.feedLines.push(line);
    while (this.feedLines.length > 6) this.feedLines.shift().remove();
    setTimeout(() => {
      line.style.opacity = '0';
      line.style.transition = 'opacity 0.5s';
      setTimeout(() => line.remove(), 520);
      this.feedLines = this.feedLines.filter((l) => l !== line);
    }, 11000);
  }

  kill(killer, victim, weaponName, playerInvolved = false) {
    const line = document.createElement('div');
    line.className = 'kill-line';
    line.innerHTML = `<b>${killer}</b> <span class="wep">${weaponName}</span> <b>${victim}</b>`;
    this.el.killfeed.appendChild(line);
    const kids = [...this.el.killfeed.children];
    while (kids.length > 5) kids.shift().remove();
    setTimeout(() => { line.remove(); }, 8000);
    if (playerInvolved) line.style.borderColor = 'rgba(255,122,47,0.6)';
  }

  banner(title, sub = '', duration = 3.2, color = '#ffd166') {
    this.el.bannerTitle.textContent = title;
    this.el.bannerSub.textContent = sub;
    this.el.bannerTitle.style.color = color;
    this.el.banner.classList.remove('hidden');
    this.bannerTimer = duration;
  }

  toast(text) {
    this.el.toast.textContent = text;
    this.el.toast.classList.add('show');
    this.toastTimer = 2.2;
  }

  setPrompt(text) {
    if (!text) { this.el.prompt.classList.add('hidden'); return; }
    this.el.prompt.classList.remove('hidden');
    this.el.promptText.textContent = text;
  }

  hitmarker(crit = false) {
    this.el.crosshair.classList.add('hit');
    this.el.hitmarker.style.color = crit ? '#ffd166' : '#ff3b4e';
    this.hitTimer = 0.12;
  }

  hurt(amount) {
    this.el.vignette.classList.add('hurt');
    clearTimeout(this._hurtT);
    this._hurtT = setTimeout(() => this.el.vignette.classList.remove('hurt'), 140);
  }

  damage(worldPos, amount, kind = '') {
    const div = document.createElement('div');
    div.className = `dmg-float ${kind}`;
    div.textContent = kind === 'heal' ? `+${Math.round(amount)}` : `${Math.round(amount)}`;
    this.el.floatLayer.appendChild(div);
    this.floats.push({ el: div, pos: worldPos.clone(), life: 0.85, vy: 0 });
    while (this.floats.length > 18) this.floats.shift().el.remove();
  }

  updateFloats(dt, camera) {
    const v = new THREE.Vector3();
    for (let i = this.floats.length - 1; i >= 0; i--) {
      const f = this.floats[i];
      f.life -= dt;
      f.pos.y += dt * 1.1;
      if (f.life <= 0) { f.el.remove(); this.floats.splice(i, 1); continue; }
      v.copy(f.pos).project(camera);
      if (v.z > 1 || v.z < -1) { f.el.style.opacity = '0'; continue; }
      const x = (v.x * 0.5 + 0.5) * innerWidth;
      const y = (-v.y * 0.5 + 0.5) * innerHeight;
      f.el.style.left = `${x}px`;
      f.el.style.top = `${y}px`;
      f.el.style.opacity = String(Math.min(1, f.life * 2.2));
      f.el.style.fontSize = f.life > 0.6 ? '' : '';
    }
  }

  update(dt, state) {
    const {
      hp, maxHp = 1000, ammo, reserve, weapon, slots = [], slotIndex = 0,
      alive, timer, specialRemaining = 0, specialTotal = 1, reloading = false,
      zoneDanger = false, maskTime = 0, funado = false, zoneTime = '',
    } = state;

    // HP
    const pct = Math.max(0, hp / maxHp) * 100;
    this.el.hpValue.textContent = Math.max(0, Math.ceil(hp));
    this.el.hpFill.style.width = `${pct}%`;
    this.el.hpLag.style.width = `${pct}%`;
    this.el.hpTrack.classList.toggle('low', hp < 300);
    this.el.hpValue.style.color = hp < 300 ? '#ff6b6b' : hp < 600 ? '#ffd166' : '#7dffb0';
    this.lastHp = hp;

    this.el.alive.textContent = alive;
    this.el.timer.textContent = fmtTime(timer);
    this.el.zoneTimer.textContent = zoneTime;
    this.el.zonePill.classList.toggle('danger', zoneDanger);

    // Arma
    if (weapon) {
      this.el.weaponIcon.textContent = weapon.emoji;
      this.el.weaponName.textContent = weapon.name;
      const rar = RARITY[weapon.rarity] || RARITY.common;
      this.el.weaponCat.textContent = `${weapon.category.toUpperCase()} · ${rar.label.toUpperCase()}`;
      this.el.weaponCat.style.color = rar.color;
      this.el.weaponIcon.style.borderColor = rar.color + '66';
      this.el.ammoMag.textContent = weapon.melee ? '∞' : (reloading ? '···' : ammo);
      this.el.ammoReserve.textContent = weapon.melee ? '∞' : reserve;
      this.el.ammoMag.style.color = !weapon.melee && ammo === 0 ? '#ff3b4e' : '';
      // Especial
      if (weapon.special) {
        this.el.specialBtn.disabled = false;
        this.el.specialIcon.textContent = weapon.emoji;
        this.el.specialName.textContent = weapon.special.name;
        this.el.specialDesc.textContent = weapon.special.desc;
        const ratio = specialRemaining > 0 ? specialRemaining / specialTotal : 0;
        this.el.specialCd.style.width = `${ratio * 100}%`;
        this.el.specialBtn.classList.toggle('ready', specialRemaining <= 0);
      } else {
        this.el.specialBtn.disabled = true;
        this.el.specialIcon.textContent = '✨';
        this.el.specialName.textContent = 'SIN ESPECIAL';
        this.el.specialDesc.textContent = 'Busca un arma mítica';
        this.el.specialCd.style.width = '0%';
        this.el.specialBtn.classList.remove('ready');
      }
    }
    // Slots
    this.el.weaponSlots.innerHTML = '';
    for (let i = 0; i < 3; i++) {
      const w = slots[i];
      const d = document.createElement('div');
      d.className = `wslot ${i === slotIndex ? 'active' : ''}`;
      d.innerHTML = w ? `<b>${w.emoji}</b><i>${w.name}</i>` : `<b>·</b><i>vacío</i>`;
      this.el.weaponSlots.appendChild(d);
    }

    // Estados
    this.el.statusZone.classList.toggle('hidden', !zoneDanger);
    this.el.statusMask.classList.toggle('hidden', !(maskTime > 0));
    if (maskTime > 0) this.el.statusMask.textContent = `😷 MÁSCARA ${Math.ceil(maskTime)}s`;
    this.el.statusChickens.classList.toggle('hidden', !funado);

    // Timers
    if (this.bannerTimer > 0) {
      this.bannerTimer -= dt;
      if (this.bannerTimer <= 0) this.el.banner.classList.add('hidden');
    }
    if (this.toastTimer > 0) {
      this.toastTimer -= dt;
      if (this.toastTimer <= 0) this.el.toast.classList.remove('show');
    }
    if (this.hitTimer > 0) {
      this.hitTimer -= dt;
      if (this.hitTimer <= 0) this.el.crosshair.classList.remove('hit');
    }

    this.minimapT -= dt;
    if (this.minimapT <= 0) {
      this.minimapT = 0.1;
      this.drawMinimap(state.minimap || {});
    }
  }

  drawMinimap(m) {
    const ctx = this.mctx;
    const W = this.el.minimap.width, H = this.el.minimap.height;
    const scale = W / 420;
    const ox = W / 2, oz = H / 2;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#0b0810';
    ctx.fillRect(0, 0, W, H);

    // terreno
    ctx.fillStyle = this.map.toxic ? '#1c1230' : this.map.ruined ? '#33312c' : '#2b2a22';
    ctx.beginPath(); ctx.arc(ox, oz, 196 * scale, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.14)'; ctx.lineWidth = 1; ctx.stroke();

    // ciudad / pueblo / volcán
    ctx.fillStyle = this.map.toxic ? 'rgba(255,62,165,0.18)' : 'rgba(255,255,255,0.09)';
    ctx.fillRect(ox + (95 - 68) * scale, oz + (-40 - 68) * scale, 136 * scale, 136 * scale);
    ctx.fillStyle = 'rgba(120,255,140,0.12)';
    ctx.beginPath(); ctx.arc(ox - 95 * scale, oz + 35 * scale, 52 * scale, 0, Math.PI * 2); ctx.fill();
    // volcán
    ctx.fillStyle = 'rgba(255,90,31,0.35)';
    ctx.beginPath(); ctx.arc(ox + 10 * scale, oz + 105 * scale, 30 * scale, 0, Math.PI * 2); ctx.fill();

    // zona segura
    if (m.safe) {
      const sx = ox + m.safe.x * scale, sz = oz + m.safe.z * scale;
      // sombra fuera
      ctx.save();
      ctx.beginPath(); ctx.rect(0, 0, W, H); ctx.arc(sx, sz, m.safe.r * scale, 0, Math.PI * 2, true);
      ctx.fillStyle = 'rgba(255,40,60,0.16)'; ctx.fill();
      ctx.restore();
      ctx.strokeStyle = this.map.accent; ctx.lineWidth = 1.6;
      ctx.beginPath(); ctx.arc(sx, sz, m.safe.r * scale, 0, Math.PI * 2); ctx.stroke();
    }
    // lava / tormenta / tóxico
    if (m.hazardRadius > 0) {
      ctx.strokeStyle = this.map.accent; ctx.lineWidth = 1.4;
      ctx.setLineDash([3, 3]);
      ctx.beginPath(); ctx.arc(ox + 10 * scale, oz + 105 * scale, m.hazardRadius * scale, 0, Math.PI * 2); ctx.stroke();
      ctx.setLineDash([]);
    }
    // loot
    if (m.loot) {
      ctx.fillStyle = 'rgba(255,209,102,0.65)';
      for (const p of m.loot) ctx.fillRect(ox + p.x * scale - 1, oz + p.z * scale - 1, 2, 2);
    }
    // enemigos
    if (m.enemies) {
      ctx.fillStyle = '#ff4d5e';
      for (const p of m.enemies) {
        ctx.beginPath(); ctx.arc(ox + p.x * scale, oz + p.z * scale, 1.9, 0, Math.PI * 2); ctx.fill();
      }
    }
    // jugador
    if (m.player) {
      const px = ox + m.player.x * scale, pz = oz + m.player.z * scale;
      ctx.save();
      ctx.translate(px, pz);
      ctx.rotate(m.player.yaw);
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(3.6, 4); ctx.lineTo(0, 2.2); ctx.lineTo(-3.6, 4); ctx.closePath(); ctx.fill();
      ctx.restore();
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.beginPath(); ctx.arc(px, pz, 6, 0, Math.PI * 2); ctx.stroke();
    }
    // marco
    ctx.strokeStyle = 'rgba(255,255,255,0.15)';
    ctx.strokeRect(0.5, 0.5, W - 1, H - 1);
  }

  destroy() {
    this.el.feed.innerHTML = '';
    this.el.killfeed.innerHTML = '';
    this.el.floatLayer.innerHTML = '';
  }
}

import * as THREE from 'three';
import { MAPS, SKINS } from '../data/maps.js';
import { createPlayerCharacter } from '../entities/Character.js';

const QUALITIES = ['auto', 'alta', 'baja'];
const QLABEL = { auto: 'AUTO', alta: 'ALTA', baja: 'BAJA' };

export class Menu {
  constructor({ onPlay }) {
    this.onPlay = onPlay;
    this.selectedMap = MAPS[0];
    this.selectedSkin = SKINS[0];
    this.quality = localStorage.getItem('ms-quality') || 'auto';
    this.raf = 0;
    this.visible = true;
    this.buildMaps();
    this.bindSkin();
    this.bindButtons();
    this.initPreview();
    this.applyQualityLabel();
  }

  buildMaps() {
    const list = document.getElementById('map-list');
    list.innerHTML = '';
    const thumbs = {
      erupcion: 'linear-gradient(160deg, #ff7a3d 0%, #6b2318 45%, #1b1216 100%)',
      posapocalipsis: 'linear-gradient(160deg, #b9ad94 0%, #55534a 45%, #1a1c1d 100%)',
      neon: 'linear-gradient(160deg, #ff3ea5 0%, #4b1a7a 45%, #090616 100%)',
    };
    MAPS.forEach((m) => {
      const card = document.createElement('button');
      card.className = `map-card ${m.id === this.selectedMap.id ? 'active' : ''}`;
      card.style.setProperty('--accent', m.accent);
      card.style.setProperty('--thumb', thumbs[m.id]);
      card.innerHTML = `
        <div class="map-thumb">${m.emoji}</div>
        <div class="map-info">
          <b>${m.name}</b>
          <small>${m.subtitle}</small>
        </div>
        <div class="map-hazard">${m.hazardShort}<span>${m.tag}</span></div>`;
      card.addEventListener('click', () => {
        this.selectedMap = m;
        document.querySelectorAll('.map-card').forEach((c) => c.classList.remove('active'));
        card.classList.add('active');
        document.documentElement.style.setProperty('--accent', m.accent);
      });
      list.appendChild(card);
    });
    document.documentElement.style.setProperty('--accent', this.selectedMap.accent);
  }

  bindSkin() {
    const buttons = [...document.querySelectorAll('#skin-toggle button')];
    const desc = document.getElementById('skin-desc');
    const badge = document.getElementById('skin-badge');
    const bonus = document.getElementById('skin-bonus');
    const apply = (id) => {
      this.selectedSkin = SKINS.find((s) => s.id === id) || SKINS[0];
      buttons.forEach((b) => b.classList.toggle('active', b.dataset.skin === id));
      desc.textContent = this.selectedSkin.desc;
      badge.textContent = this.selectedSkin.gloves ? 'GUANTES EQUIPADOS' : 'SIN GUANTES';
      badge.style.color = this.selectedSkin.gloves ? '#ff9a6b' : '#7dffb0';
      badge.style.borderColor = this.selectedSkin.gloves ? 'rgba(255,154,107,0.4)' : 'rgba(125,255,176,0.3)';
      bonus.textContent = `+${Math.round(this.selectedSkin.meleeBonus * 100)}%`;
      if (this.previewChar) {
        this.previewChar.setGloves(this.selectedSkin.gloves);
        this.previewChar.setWeapon(this.selectedSkin.gloves ? 'garras' : 'pio');
        this.previewChar.rig.rotation.y = 0;
      }
    };
    buttons.forEach((b) => b.addEventListener('click', () => apply(b.dataset.skin)));
    apply('miguel');
    this.applySkin = apply;
  }

  bindButtons() {
    document.getElementById('play-btn').addEventListener('click', () => {
      if (!this.visible) return;
      this.onPlay(this.selectedMap, this.selectedSkin, this.quality);
    });
    document.getElementById('quality-btn').addEventListener('click', () => {
      const i = QUALITIES.indexOf(this.quality);
      this.quality = QUALITIES[(i + 1) % QUALITIES.length];
      localStorage.setItem('ms-quality', this.quality);
      this.applyQualityLabel();
    });
    const how = document.getElementById('how-modal');
    document.getElementById('how-btn').addEventListener('click', () => how.classList.remove('hidden'));
    document.getElementById('how-close').addEventListener('click', () => how.classList.add('hidden'));
    how.addEventListener('click', (e) => { if (e.target === how) how.classList.add('hidden'); });
  }

  applyQualityLabel() {
    const el = document.getElementById('quality-label');
    if (el) el.textContent = QLABEL[this.quality];
  }

  initPreview() {
    const canvas = document.getElementById('skin-preview');
    if (!canvas) return;
    const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true, powerPreference: 'low-power' });
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.setClearColor(0x000000, 0);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.previewRenderer = renderer;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(38, 1, 0.1, 30);
    camera.position.set(0, 1.15, 2.6);
    camera.lookAt(0, 0.62, 0);

    scene.add(new THREE.HemisphereLight(0xffd9b0, 0x2a1a30, 2.0));
    const key = new THREE.DirectionalLight(0xffa060, 3);
    key.position.set(2, 3, 3);
    scene.add(key);
    const rim = new THREE.DirectionalLight(0x35f0ff, 2);
    rim.position.set(-2, 1.5, -2);
    scene.add(rim);

    const pedestal = new THREE.Mesh(
      new THREE.CylinderGeometry(0.72, 0.86, 0.12, 24),
      new THREE.MeshLambertMaterial({ color: 0x2a1a30 })
    );
    pedestal.position.y = -0.06;
    scene.add(pedestal);
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(0.78, 0.86, 32),
      new THREE.MeshBasicMaterial({ color: 0xff7a2f, transparent: true, opacity: 0.7, side: THREE.DoubleSide })
    );
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.01;
    scene.add(ring);

    // Piso de rejilla
    const grid = new THREE.GridHelper(6, 24, 0x6a3a8a, 0x2a1a30);
    grid.position.y = -0.07;
    scene.add(grid);

    this.previewChar = createPlayerCharacter(scene, this.selectedSkin);
    this.previewChar.setWeapon('pio');
    this.previewChar.root.scale.setScalar(1.25);
    this.previewScene = scene;
    this.previewCamera = camera;

    const resize = () => {
      const r = canvas.getBoundingClientRect();
      if (r.width < 2) return;
      renderer.setSize(r.width, r.height, false);
      camera.aspect = r.width / Math.max(1, r.height);
      camera.updateProjectionMatrix();
    };
    this.previewResize = resize;
    resize();
    addEventListener('resize', resize);

    let t = 0;
    const loop = () => {
      if (!this.visible) { this.raf = 0; return; }
      this.raf = requestAnimationFrame(loop);
      t += 0.016;
      resize();
      if (this.previewChar) {
        this.previewChar.root.rotation.y = Math.sin(t * 0.5) * 0.6 + t * 0.12;
        this.previewChar.update(0.016, 0, true, false, false);
      }
      ring.rotation.z += 0.004;
      ring.material.opacity = 0.5 + Math.sin(t * 2) * 0.2;
      renderer.render(scene, camera);
    };
    loop();
  }

  hide() {
    this.visible = false;
    cancelAnimationFrame(this.raf);
    this.raf = 0;
    document.getElementById('menu').classList.add('hidden');
    if (this.previewRenderer) {
      this.previewRenderer.dispose();
      this.previewRenderer = null;
    }
    removeEventListener('resize', this.previewResize);
  }

  show() {
    this.visible = true;
    document.getElementById('menu').classList.remove('hidden');
    if (!this.previewRenderer) {
      // recrear preview al volver al menú
      this.initPreview();
    }
    if (!this.raf) {
      const tick = () => {
        if (!this.visible) return;
        this.raf = requestAnimationFrame(tick);
        const t = performance.now() * 0.001;
        if (this.previewChar) {
          this.previewChar.root.rotation.y = Math.sin(t * 0.5) * 0.6 + t * 0.12;
          this.previewChar.update(0.016, 0, true, false, false);
        }
        this.previewRenderer?.render(this.previewScene, this.previewCamera);
      };
      tick();
    }
  }
}

import * as THREE from 'three';

/* Pool de trazadoras, partículas, explosiones, anillos y destellos. */

const MAX_TRACERS = 56;
const MAX_SPARKS = 420;
const MAX_SMOKE = 120;
const MAX_FLASH = 10;

function radialTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.35, 'rgba(255,220,150,0.9)');
  g.addColorStop(1, 'rgba(255,120,40,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 64, 64);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.tmp = new THREE.Vector3();
    this.tmp2 = new THREE.Vector3();

    // Trazadoras
    this.tracerPos = new Float32Array(MAX_TRACERS * 6);
    this.tracerCol = new Float32Array(MAX_TRACERS * 6);
    const tg = new THREE.BufferGeometry();
    tg.setAttribute('position', new THREE.BufferAttribute(this.tracerPos, 3));
    tg.setAttribute('color', new THREE.BufferAttribute(this.tracerCol, 3));
    this.tracerMesh = new THREE.LineSegments(tg, new THREE.LineBasicMaterial({
      vertexColors: true, transparent: true, opacity: 0.95,
      blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    this.tracerMesh.frustumCulled = false;
    scene.add(this.tracerMesh);
    this.tracers = [];

    // Chispas
    this.sparkPos = new Float32Array(MAX_SPARKS * 3).fill(-999);
    this.sparkCol = new Float32Array(MAX_SPARKS * 3);
    this.sparkVel = new Float32Array(MAX_SPARKS * 3);
    this.sparkLife = new Float32Array(MAX_SPARKS);
    const sg = new THREE.BufferGeometry();
    sg.setAttribute('position', new THREE.BufferAttribute(this.sparkPos, 3));
    sg.setAttribute('color', new THREE.BufferAttribute(this.sparkCol, 3));
    this.sparks = new THREE.Points(sg, new THREE.PointsMaterial({
      size: 0.19, vertexColors: true, transparent: true, opacity: 0.95,
      blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true,
    }));
    this.sparks.frustumCulled = false;
    scene.add(this.sparks);
    this.sparkIdx = 0;

    // Humo
    this.smokePos = new Float32Array(MAX_SMOKE * 3).fill(-999);
    this.smokeCol = new Float32Array(MAX_SMOKE * 3);
    this.smokeVel = new Float32Array(MAX_SMOKE * 3);
    this.smokeLife = new Float32Array(MAX_SMOKE);
    const mg = new THREE.BufferGeometry();
    mg.setAttribute('position', new THREE.BufferAttribute(this.smokePos, 3));
    mg.setAttribute('color', new THREE.BufferAttribute(this.smokeCol, 3));
    this.smoke = new THREE.Points(mg, new THREE.PointsMaterial({
      size: 1.4, vertexColors: true, transparent: true, opacity: 0.32,
      depthWrite: false, sizeAttenuation: true,
    }));
    this.smoke.frustumCulled = false;
    scene.add(this.smoke);
    this.smokeIdx = 0;

    // Destellos de boca de cañón
    const tex = radialTexture();
    this.flashPos = new Float32Array(MAX_FLASH * 3).fill(-999);
    const fg = new THREE.BufferGeometry();
    fg.setAttribute('position', new THREE.BufferAttribute(this.flashPos, 3));
    this.flash = new THREE.Points(fg, new THREE.PointsMaterial({
      map: tex, size: 1.3, transparent: true, opacity: 0.9,
      blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true,
    }));
    this.flash.frustumCulled = false;
    scene.add(this.flash);
    this.flashLife = new Float32Array(MAX_FLASH);
    this.flashIdx = 0;

    // Explosiones
    this.booms = [];
    for (let i = 0; i < 4; i++) {
      const m = new THREE.Mesh(
        new THREE.IcosahedronGeometry(1, 1),
        new THREE.MeshBasicMaterial({ color: 0xff7a2f, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false })
      );
      m.visible = false;
      scene.add(m);
      this.booms.push({ mesh: m, life: 0, max: 0.5, radius: 4 });
    }

    // Anillos
    this.rings = [];
    for (let i = 0; i < 6; i++) {
      const m = new THREE.Mesh(
        new THREE.RingGeometry(0.86, 1, 28),
        new THREE.MeshBasicMaterial({ color: 0xffd166, transparent: true, opacity: 0, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false })
      );
      m.rotation.x = -Math.PI / 2;
      m.visible = false;
      scene.add(m);
      this.rings.push({ mesh: m, life: 0, max: 0.5, radius: 4 });
    }

    // Haces
    this.beams = [];
    for (let i = 0; i < 5; i++) {
      const m = new THREE.Mesh(
        new THREE.CylinderGeometry(0.05, 0.05, 1, 6, 1, true),
        new THREE.MeshBasicMaterial({ color: 0x35f0ff, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false })
      );
      m.visible = false;
      scene.add(m);
      this.beams.push({ mesh: m, life: 0, max: 0.2 });
    }
  }

  tracer(from, to, color = 0xffd166) {
    const i = this.tracers.length % MAX_TRACERS;
    const p = this.tracerPos, c = this.tracerCol;
    p[i * 6] = from.x; p[i * 6 + 1] = from.y; p[i * 6 + 2] = from.z;
    p[i * 6 + 3] = to.x; p[i * 6 + 4] = to.y; p[i * 6 + 5] = to.z;
    const col = new THREE.Color(color);
    c[i * 6] = col.r; c[i * 6 + 1] = col.g; c[i * 6 + 2] = col.b;
    c[i * 6 + 3] = col.r * 0.15; c[i * 6 + 4] = col.g * 0.15; c[i * 6 + 5] = col.b * 0.15;
    const entry = this.tracers.find((t) => t.slot === i);
    if (entry) { entry.life = 0.12; entry.max = 0.12; }
    else this.tracers.push({ slot: i, life: 0.12, max: 0.12 });
    this.tracerMesh.geometry.attributes.position.needsUpdate = true;
    this.tracerMesh.geometry.attributes.color.needsUpdate = true;
  }

  muzzle(pos) {
    const i = this.flashIdx++ % MAX_FLASH;
    this.flashPos[i * 3] = pos.x; this.flashPos[i * 3 + 1] = pos.y; this.flashPos[i * 3 + 2] = pos.z;
    this.flashLife[i] = 0.06;
    this.flash.geometry.attributes.position.needsUpdate = true;
  }

  sparksAt(pos, color = 0xffd166, count = 6, speed = 4, spread = 1) {
    const col = new THREE.Color(color);
    for (let k = 0; k < count; k++) {
      const i = this.sparkIdx++ % MAX_SPARKS;
      this.sparkPos[i * 3] = pos.x; this.sparkPos[i * 3 + 1] = pos.y; this.sparkPos[i * 3 + 2] = pos.z;
      this.sparkVel[i * 3] = (Math.random() - 0.5) * speed * spread;
      this.sparkVel[i * 3 + 1] = Math.random() * speed;
      this.sparkVel[i * 3 + 2] = (Math.random() - 0.5) * speed * spread;
      this.sparkCol[i * 3] = col.r; this.sparkCol[i * 3 + 1] = col.g; this.sparkCol[i * 3 + 2] = col.b;
      this.sparkLife[i] = 0.35 + Math.random() * 0.4;
    }
    this.sparks.geometry.attributes.position.needsUpdate = true;
    this.sparks.geometry.attributes.color.needsUpdate = true;
  }

  smokeAt(pos, color = 0x555555, count = 5, up = 2) {
    const col = new THREE.Color(color);
    for (let k = 0; k < count; k++) {
      const i = this.smokeIdx++ % MAX_SMOKE;
      this.smokePos[i * 3] = pos.x + (Math.random() - 0.5) * 1.2;
      this.smokePos[i * 3 + 1] = pos.y + Math.random() * 0.6;
      this.smokePos[i * 3 + 2] = pos.z + (Math.random() - 0.5) * 1.2;
      this.smokeVel[i * 3] = (Math.random() - 0.5) * 1.5;
      this.smokeVel[i * 3 + 1] = up * (0.4 + Math.random());
      this.smokeVel[i * 3 + 2] = (Math.random() - 0.5) * 1.5;
      this.smokeCol[i * 3] = col.r; this.smokeCol[i * 3 + 1] = col.g; this.smokeCol[i * 3 + 2] = col.b;
      this.smokeLife[i] = 0.8 + Math.random() * 0.7;
    }
    this.smoke.geometry.attributes.position.needsUpdate = true;
    this.smoke.geometry.attributes.color.needsUpdate = true;
  }

  explosion(pos, radius = 5, color = 0xff7a2f) {
    const b = this.booms.find((x) => x.life <= 0) || this.booms[0];
    b.mesh.position.copy(pos);
    b.mesh.material.color.set(color);
    b.mesh.material.opacity = 0.9;
    b.mesh.scale.setScalar(0.6);
    b.mesh.visible = true;
    b.life = b.max = 0.5;
    b.radius = radius;
    const ring = this.rings.find((x) => x.life <= 0) || this.rings[0];
    ring.mesh.position.set(pos.x, Math.max(0.3, pos.y - 0.4), pos.z);
    ring.mesh.material.color.set(color);
    ring.mesh.material.opacity = 0.9;
    ring.mesh.scale.setScalar(1);
    ring.mesh.visible = true;
    ring.life = ring.max = 0.6;
    ring.radius = radius * 1.3;
    this.sparksAt(pos, color, 26, 12, 1.4);
    this.smokeAt(pos, 0x3a3a3a, 12, 3.5);
  }

  ring(pos, radius = 3, color = 0xffd166) {
    const r = this.rings.find((x) => x.life <= 0) || this.rings[0];
    r.mesh.position.set(pos.x, Math.max(0.25, pos.y - 0.35), pos.z);
    r.mesh.material.color.set(color);
    r.mesh.material.opacity = 0.85;
    r.mesh.scale.setScalar(1);
    r.mesh.visible = true;
    r.life = r.max = 0.45;
    r.radius = radius;
  }

  beam(from, to, color = 0x35f0ff, width = 1) {
    const b = this.beams.find((x) => x.life <= 0) || this.beams[0];
    const mid = this.tmp.copy(from).add(to).multiplyScalar(0.5);
    const len = from.distanceTo(to);
    b.mesh.position.copy(mid);
    b.mesh.scale.set(width, len, width);
    b.mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), this.tmp2.copy(to).sub(from).normalize());
    b.mesh.material.color.set(color);
    b.mesh.material.opacity = 0.9;
    b.mesh.visible = true;
    b.life = b.max = 0.16;
  }

  update(dt) {
    // Trazadoras
    for (const t of this.tracers) {
      t.life -= dt;
      if (t.life <= 0) {
        for (let k = 0; k < 6; k++) this.tracerCol[t.slot * 6 + k] = 0;
      }
    }
    this.tracers = this.tracers.filter((t) => t.life > 0);
    this.tracerMesh.geometry.attributes.color.needsUpdate = true;

    // Chispas
    for (let i = 0; i < MAX_SPARKS; i++) {
      if (this.sparkLife[i] <= 0) continue;
      this.sparkLife[i] -= dt;
      this.sparkVel[i * 3 + 1] -= dt * 9;
      this.sparkPos[i * 3] += this.sparkVel[i * 3] * dt;
      this.sparkPos[i * 3 + 1] += this.sparkVel[i * 3 + 1] * dt;
      this.sparkPos[i * 3 + 2] += this.sparkVel[i * 3 + 2] * dt;
      const f = Math.max(0, this.sparkLife[i]);
      this.sparkCol[i * 3] *= 0.94; this.sparkCol[i * 3 + 1] *= 0.94; this.sparkCol[i * 3 + 2] *= 0.94;
      if (this.sparkLife[i] <= 0) this.sparkPos[i * 3 + 1] = -999;
    }
    this.sparks.geometry.attributes.position.needsUpdate = true;
    this.sparks.geometry.attributes.color.needsUpdate = true;

    // Humo
    for (let i = 0; i < MAX_SMOKE; i++) {
      if (this.smokeLife[i] <= 0) continue;
      this.smokeLife[i] -= dt;
      this.smokePos[i * 3] += this.smokeVel[i * 3] * dt;
      this.smokePos[i * 3 + 1] += this.smokeVel[i * 3 + 1] * dt;
      this.smokePos[i * 3 + 2] += this.smokeVel[i * 3 + 2] * dt;
      this.smokeCol[i * 3] *= 0.985; this.smokeCol[i * 3 + 1] *= 0.985; this.smokeCol[i * 3 + 2] *= 0.985;
      if (this.smokeLife[i] <= 0) this.smokePos[i * 3 + 1] = -999;
    }
    this.smoke.geometry.attributes.position.needsUpdate = true;
    this.smoke.geometry.attributes.color.needsUpdate = true;

    // Destellos
    for (let i = 0; i < MAX_FLASH; i++) {
      if (this.flashLife[i] <= 0) continue;
      this.flashLife[i] -= dt;
      if (this.flashLife[i] <= 0) { this.flashPos[i * 3 + 1] = -999; this.flash.geometry.attributes.position.needsUpdate = true; }
    }

    // Explosiones / anillos / haces
    for (const b of this.booms) {
      if (b.life <= 0) continue;
      b.life -= dt;
      const t = 1 - b.life / b.max;
      b.mesh.scale.setScalar(0.6 + t * b.radius);
      b.mesh.material.opacity = Math.max(0, 0.9 * (1 - t));
      if (b.life <= 0) b.mesh.visible = false;
    }
    for (const r of this.rings) {
      if (r.life <= 0) continue;
      r.life -= dt;
      const t = 1 - r.life / r.max;
      r.mesh.scale.setScalar(1 + t * r.radius);
      r.mesh.material.opacity = Math.max(0, 0.85 * (1 - t));
      if (r.life <= 0) r.mesh.visible = false;
    }
    for (const b of this.beams) {
      if (b.life <= 0) continue;
      b.life -= dt;
      b.mesh.material.opacity = Math.max(0, 0.9 * (b.life / b.max));
      if (b.life <= 0) b.mesh.visible = false;
    }
  }

  dispose() {
    this.scene.remove(this.tracerMesh, this.sparks, this.smoke, this.flash);
    for (const b of this.booms) this.scene.remove(b.mesh);
    for (const r of this.rings) this.scene.remove(r.mesh);
    for (const b of this.beams) this.scene.remove(b.mesh);
  }
}

import * as THREE from 'three';
import { createBotMesh } from './Character.js';
import { WEAPONS } from '../data/weapons.js';

const BOT_WEAPONS = [
  'pio', 'm1911', 'uzi', 'mp5', 'ak47', 'm4a1', 'remington', 'deagle',
  'mp7', 'scar', 'g36', 'mosin', 'm249', 'bate_beisbol', 'katana', 'p90',
];

export class Bot {
  constructor(game, name, seed, spawn) {
    this.game = game;
    this.name = name;
    this.seed = seed;
    this.alive = true;
    this.hp = 1000;
    this.maxHp = 1000;
    this.pos = new THREE.Vector3(spawn.x, spawn.y ?? 0, spawn.z);
    this.vel = new THREE.Vector3();
    this.knock = new THREE.Vector3();
    this.yaw = Math.random() * Math.PI * 2;
    this.dropping = spawn.drop !== false;
    this.landed = !this.dropping;
    this.dropSpeed = 10 + Math.random() * 6;
    this.stun = 0;
    this.dead = false;
    this.target = null;
    this.targetTimer = Math.random() * 0.6;
    this.fireTimer = 0.8 + Math.random() * 1.5;
    this.thinkTimer = Math.random();
    this.wander = new THREE.Vector3(spawn.x, 0, spawn.z);
    this.accuracy = 0.28 + Math.random() * 0.3;
    this.aggression = 0.4 + Math.random() * 0.6;
    this.speed = 3.8 + Math.random() * 1.5;
    this.weapon = WEAPONS[BOT_WEAPONS[Math.floor(Math.random() * BOT_WEAPONS.length)]];
    this.meshData = createBotMesh(game.scene, seed, game.map);
    this.mesh = this.meshData.group;
    this.mesh.position.copy(this.pos);
    this.bobPhase = Math.random() * 10;
    this.lastHitBy = null;
    this.meleeTimer = 0;
    if (this.dropping) {
      this.pos.y = 60 + Math.random() * 25;
      this.mesh.position.y = this.pos.y;
    } else {
      this.pos.y = game.world.heightAt(this.pos.x, this.pos.z);
      this.mesh.position.y = this.pos.y;
    }
  }

  get chest() { return new THREE.Vector3(this.pos.x, this.pos.y + 0.62, this.pos.z); }
  get head() { return new THREE.Vector3(this.pos.x, this.pos.y + 0.9, this.pos.z); }

  takeDamage(amount, source, weaponName = '') {
    if (!this.alive) return;
    this.hp -= amount;
    this.lastHitBy = source;
    this.stun = Math.max(this.stun, 0.08);
    this.game.hud.damage(this.head.clone().add(new THREE.Vector3(0, 0.25, 0)), amount, amount >= 100 ? 'crit' : '');
    if (this.hp <= 0) {
      this.game.killBot(this, source, weaponName);
    }
  }

  applyKnockback(dir, force) {
    this.knock.addScaledVector(dir, force);
    this.stun = Math.max(this.stun, 0.35);
  }

  update(dt) {
    if (!this.alive) return;
    const world = this.game.world;

    if (this.dropping) {
      this.pos.y -= this.dropSpeed * dt;
      const g = world.heightAt(this.pos.x, this.pos.z);
      this.mesh.rotation.z = Math.sin(performance.now() * 0.004 + this.seed) * 0.18;
      if (this.pos.y <= g + 0.05) {
        this.pos.y = g;
        this.dropping = false;
        this.landed = true;
        this.mesh.rotation.z = 0;
        this.game.effects.ring(this.pos, 1.2, 0xffffff);
      }
      this.mesh.position.copy(this.pos);
      return;
    }

    this.stun = Math.max(0, this.stun - dt);
    this.fireTimer = Math.max(0, this.fireTimer - dt);
    this.targetTimer -= dt;
    this.thinkTimer -= dt;

    // Elegir objetivo
    if (this.targetTimer <= 0 || !this.target || !this.target.alive) {
      this.targetTimer = 0.7 + Math.random() * 0.7;
      this.target = this.pickTarget();
    }

    const zone = this.game.hazards.safe;
    const outside = Math.hypot(this.pos.x - zone.x, this.pos.z - zone.z) > zone.r - 3;
    const inLava = this.game.hazards.lavaAt(this.pos.x, this.pos.z);

    let moveTarget = null;
    let speed = this.speed;
    let strafe = false;

    if (outside || inLava) {
      moveTarget = new THREE.Vector3(zone.x, 0, zone.z);
      speed *= 1.25;
    } else if (this.target) {
      const d = this.pos.distanceTo(this.target.pos);
      const range = this.weapon.melee ? 2.2 : Math.min(28, this.weapon.range * 0.55);
      if (d > range * 1.15) {
        moveTarget = this.target.pos;
      } else if (d < range * 0.55) {
        moveTarget = this.pos.clone().add(this.pos.clone().sub(this.target.pos).setY(0).normalize().multiplyScalar(4));
        strafe = true;
      } else {
        // strafe lateral
        const dir = new THREE.Vector3(this.target.pos.x - this.pos.x, 0, this.target.pos.z - this.pos.z).normalize();
        const side = new THREE.Vector3(-dir.z, 0, dir.x).multiplyScalar(this.seed % 2 ? 1 : -1);
        moveTarget = this.pos.clone().add(side.multiplyScalar(5));
        strafe = true;
        speed *= 0.7;
      }
    } else {
      if (this.thinkTimer <= 0) {
        this.thinkTimer = 2 + Math.random() * 3;
        const a = Math.random() * Math.PI * 2;
        const r = 20 + Math.random() * 120;
        this.wander.set(zone.x + Math.cos(a) * r * 0.5, 0, zone.z + Math.sin(a) * r * 0.5);
      }
      moveTarget = this.wander;
      speed *= 0.55;
    }

    if (this.stun > 0) { moveTarget = null; speed = 0; }

    // Movimiento
    if (moveTarget) {
      const dir = new THREE.Vector3(moveTarget.x - this.pos.x, 0, moveTarget.z - this.pos.z);
      const dist = dir.length();
      if (dist > 0.5) {
        dir.normalize();
        this.pos.x += dir.x * speed * dt;
        this.pos.z += dir.z * speed * dt;
        if (!strafe) this.yaw = Math.atan2(dir.x, dir.z);
      }
    }
    if (this.target && this.fireTimer > 0) {
      // Mirar al objetivo mientras dispara
      const dx = this.target.pos.x - this.pos.x, dz = this.target.pos.z - this.pos.z;
      const want = Math.atan2(dx, dz);
      let diff = want - this.yaw;
      while (diff > Math.PI) diff -= Math.PI * 2;
      while (diff < -Math.PI) diff += Math.PI * 2;
      this.yaw += diff * Math.min(1, dt * 5);
    }

    // Knockback
    this.pos.x += this.knock.x * dt;
    this.pos.z += this.knock.z * dt;
    this.knock.multiplyScalar(Math.max(0, 1 - dt * 7));

    // Colisiones y suelo
    const boxTop = world.resolveCollisions(this.pos, 0.32, 1.0);
    let ground = world.heightAt(this.pos.x, this.pos.z);
    if (boxTop != null) ground = Math.max(ground, boxTop);
    this.pos.y = ground;

    // Evitar el agua
    if (this.pos.y < 0.4) {
      const dx = -this.pos.x, dz = -this.pos.z;
      const l = Math.hypot(dx, dz) || 1;
      this.pos.x += (dx / l) * dt * 4;
      this.pos.z += (dz / l) * dt * 4;
      this.pos.y = world.heightAt(this.pos.x, this.pos.z);
    }

    // Disparar
    if (this.target && this.fireTimer <= 0 && !this.dropping && this.stun <= 0) {
      const d = this.pos.distanceTo(this.target.pos);
      const maxRange = this.weapon.melee ? 2.6 : this.weapon.range;
      if (d < maxRange) {
        this.game.botShoot(this, this.target, this.weapon);
        this.fireTimer = this.weapon.melee
          ? this.weapon.fireRate * (1.2 + Math.random())
          : this.weapon.fireRate * (1.4 + Math.random() * 1.4);
      }
    }

    // Animación
    this.bobPhase += dt * (moveTarget && this.stun <= 0 ? 9 : 2);
    this.mesh.position.set(this.pos.x, this.pos.y + Math.abs(Math.sin(this.bobPhase)) * 0.02, this.pos.z);
    this.mesh.rotation.y = this.yaw;
    this.mesh.rotation.z = this.stun > 0 ? Math.sin(performance.now() * 0.03) * 0.12 : 0;
    this.meshData.weaponMesh.rotation.x = this.target ? -0.15 : 0;
  }

  pickTarget() {
    const game = this.game;
    let best = null, bestD = 70;
    const candidates = game.aliveEntities();
    for (const e of candidates) {
      if (e === this || !e.alive) continue;
      const d = this.pos.distanceTo(e.pos);
      if (d < bestD) {
        // No perseguir a través del mapa entero si está fuera de zona
        bestD = d;
        best = e;
      }
    }
    // 25% de las veces prioriza al jugador si está cerca
    if (game.player.alive && this.pos.distanceTo(game.player.pos) < 30 && Math.random() < 0.3) {
      return game.player;
    }
    return best;
  }

  dispose() {
    this.mesh.parent?.remove(this.mesh);
    this.mesh.traverse((o) => { o.geometry?.dispose?.(); });
  }
}

import * as THREE from 'three';
import { createPlayerCharacter } from './Character.js';
import { WEAPONS, STARTER_WEAPON } from '../data/weapons.js';

export class Player {
  constructor(game, skin) {
    this.game = game;
    this.skin = skin;
    this.pos = new THREE.Vector3(0, 80, 0);
    this.vel = new THREE.Vector3();
    this.yaw = Math.random() * Math.PI * 2;
    this.pitch = 0.08;
    this.hp = 1000;
    this.maxHp = 1000;
    this.alive = true;
    this.grounded = false;
    this.dropping = true;
    this.dropSpeed = 11;
    this.stun = 0;
    this.fireCooldown = 0;
    this.reloadTimer = 0;
    this.reloading = false;
    this.specialCooldown = 0;
    this.aiming = false;
    this.attacking = 0;
    this.maskTime = 0;
    this.funado = false;
    this.slots = [];
    this.slotIndex = 0;
    this.lastDamage = '';
    this.character = createPlayerCharacter(game.scene, skin);
    this.character.root.position.copy(this.pos);
    this.addWeapon(STARTER_WEAPON, true);
  }

  get weapon() { return WEAPONS[this.slots[this.slotIndex]?.id] || WEAPONS[STARTER_WEAPON]; }
  get item() { return this.slots[this.slotIndex]; }
  get chest() { return new THREE.Vector3(this.pos.x, this.pos.y + 0.62, this.pos.z); }
  get head() { return new THREE.Vector3(this.pos.x, this.pos.y + 0.9, this.pos.z); }

  addWeapon(id, silent = false) {
    const w = WEAPONS[id];
    if (!w) return false;
    const existing = this.slots.find((s) => s.id === id);
    if (existing) {
      existing.mag = w.mag === Infinity ? Infinity : w.mag;
      existing.reserve = w.reserve;
      this.slotIndex = this.slots.indexOf(existing);
      this.character.setWeapon(id);
      if (!silent) this.game.hud.toast(`${w.name} recargada`);
      return true;
    }
    const item = {
      id,
      mag: w.mag === Infinity ? Infinity : w.mag,
      reserve: w.reserve,
    };
    if (this.slots.length < 3) {
      this.slots.push(item);
      this.slotIndex = this.slots.length - 1;
    } else {
      this.slots[this.slotIndex] = item;
    }
    this.character.setWeapon(id);
    this.fireCooldown = 0.15;
    this.reloading = false;
    this.reloadTimer = 0;
    if (!silent) this.game.hud.toast(`Equipado: ${w.name}`);
    return true;
  }

  switchSlot(i) {
    if (i < 0 || i >= this.slots.length || i === this.slotIndex) return;
    this.slotIndex = i;
    this.character.setWeapon(this.item.id);
    this.reloading = false;
    this.reloadTimer = 0;
    this.fireCooldown = Math.max(this.fireCooldown, 0.18);
  }

  cycleSlot(dir = 1) {
    if (this.slots.length < 2) return;
    const n = this.slots.length;
    this.switchSlot((this.slotIndex + dir + n) % n);
  }

  startReload() {
    const w = this.weapon;
    if (w.melee || this.reloading || this.item.mag >= w.mag || this.item.reserve <= 0) return;
    this.reloading = true;
    this.reloadTimer = w.reload;
    this.game.hud.toast('Recargando...');
  }

  finishReload() {
    const w = this.weapon, it = this.item;
    const need = w.mag - it.mag;
    const take = Math.min(need, it.reserve);
    it.mag += take;
    if (it.reserve !== Infinity) it.reserve -= take;
    this.reloading = false;
  }

  heal(amount) {
    const before = this.hp;
    this.hp = Math.min(this.maxHp, this.hp + amount);
    if (this.hp > before) this.game.hud.damage(this.pos.clone().add(new THREE.Vector3(0, 1.3, 0)), this.hp - before, 'heal');
  }

  takeDamage(amount, source = 'El caos', weaponName = '') {
    if (!this.alive || this.dropping) return;
    this.hp -= amount;
    this.lastDamage = weaponName ? `${source} con ${weaponName}` : source;
    this.game.hud.hurt(amount);
    this.game.shake = Math.min(1.2, this.game.shake + amount / 180);
    this.game.hud.damage(this.pos.clone().add(new THREE.Vector3(0, 1.4, 0)), amount, '');
    if (this.hp <= 0) {
      this.hp = 0;
      this.game.killPlayer(source, weaponName);
    }
  }

  respawnAtSpawn(spawn) {
    this.pos.set(spawn.x, spawn.y, spawn.z);
    this.vel.set(0, 0, 0);
    this.character.root.position.copy(this.pos);
  }

  update(dt, input) {
    if (!this.alive) return;
    const w = this.weapon;
    const world = this.game.world;

    // Cámara / mirada
    const sens = (this.aiming ? 0.0016 : 0.0026) * (this.game.quality === 'baja' ? 1.1 : 1);
    this.yaw += input.lookX * sens;
    this.pitch -= input.lookY * sens;
    this.pitch = Math.max(-0.52, Math.min(0.95, this.pitch));
    if (this.yaw > Math.PI) this.yaw -= Math.PI * 2;
    if (this.yaw < -Math.PI) this.yaw += Math.PI * 2;
    this.aiming = !!input.aiming;

    if (this.stun > 0) this.stun -= dt;
    this.fireCooldown = Math.max(0, this.fireCooldown - dt);
    this.specialCooldown = Math.max(0, this.specialCooldown - dt);
    this.attacking = Math.max(0, this.attacking - dt);
    this.maskTime = Math.max(0, this.maskTime - dt);
    if (this.reloading) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) this.finishReload();
    }

    // Caída en paracaídas
    if (this.dropping) {
      const fwd = new THREE.Vector3(Math.sin(this.yaw), 0, Math.cos(this.yaw));
      const right = new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
      this.pos.addScaledVector(fwd, -input.moveY * 9 * dt);
      this.pos.addScaledVector(right, input.moveX * 9 * dt);
      this.pos.y -= this.dropSpeed * dt;
      const g = world.heightAt(this.pos.x, this.pos.z);
      if (this.pos.y <= g + 0.02) {
        this.pos.y = g;
        this.dropping = false;
        this.grounded = true;
        this.vel.set(0, 0, 0);
        this.game.effects.ring(this.pos, 2.2, 0xffd166);
        this.game.effects.smokeAt(this.pos, 0x8a7a5a, 8, 2);
        this.game.hud.setDrop(null);
        this.game.hud.toast('¡Aterrizaste! Busca armas y sobrevive.');
        this.game.shake = Math.max(this.game.shake, 0.25);
      }
      this.character.root.position.copy(this.pos);
      this.character.root.rotation.y = this.yaw;
      this.character.rig.rotation.x = -0.35;
      this.character.rig.rotation.z = Math.sin(performance.now() * 0.003) * 0.1;
      this.character.update(dt, 0, false, false, false);
      return;
    }
    this.character.rig.rotation.x = 0;

    // Movimiento
    const fwd = new THREE.Vector3(Math.sin(this.yaw), 0, Math.cos(this.yaw));
    const right = new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
    const wish = new THREE.Vector3();
    wish.addScaledVector(fwd, -input.moveY);
    wish.addScaledVector(right, input.moveX);
    if (wish.lengthSq() > 1) wish.normalize();

    let speed = 5.4;
    if (input.sprint && input.moveY < -0.2 && !this.aiming) speed = 8.4;
    if (this.aiming) speed = 3.0;
    speed *= w.moveSpeed || 1;
    if (this.stun > 0) speed *= 0.25;

    const targetVX = wish.x * speed;
    const targetVZ = wish.z * speed;
    const accel = this.grounded ? 14 : 4;
    this.vel.x += (targetVX - this.vel.x) * Math.min(1, accel * dt);
    this.vel.z += (targetVZ - this.vel.z) * Math.min(1, accel * dt);

    // Salto / gravedad
    if (input.jump && this.grounded && this.stun <= 0) {
      this.vel.y = 7.4;
      this.grounded = false;
      this.game.effects.ring(this.pos, 0.9, 0xffffff);
    }
    this.vel.y -= 20 * dt;

    this.pos.x += this.vel.x * dt;
    this.pos.z += this.vel.z * dt;
    this.pos.y += this.vel.y * dt;

    // Colisiones
    const boxTop = world.resolveCollisions(this.pos, 0.34, 1.02);
    let ground = world.heightAt(this.pos.x, this.pos.z);
    if (boxTop != null) ground = Math.max(ground, boxTop);
    if (this.pos.y <= ground) {
      this.pos.y = ground;
      if (this.vel.y < -6) {
        this.game.effects.ring(this.pos, 1.2, 0xffffff);
        this.game.shake = Math.max(this.game.shake, Math.min(0.35, -this.vel.y / 40));
      }
      this.vel.y = 0;
      this.grounded = true;
    } else {
      this.grounded = false;
    }

    // Agua = daño
    if (this.pos.y < 0.35) {
      this.pos.y = Math.max(this.pos.y, 0.1);
      if (!this._waterT) this._waterT = 0;
      this._waterT += dt;
      if (this._waterT > 0.6) { this._waterT = 0; this.takeDamage(18, 'El agua', ''); }
      const dx = -this.pos.x, dz = -this.pos.z;
      const l = Math.hypot(dx, dz) || 1;
      this.pos.x += (dx / l) * dt * 3;
      this.pos.z += (dz / l) * dt * 3;
    }

    // Límites del mapa: las palomas se encargan, pero no dejar salir del todo
    if (Math.hypot(this.pos.x, this.pos.z) > 230) {
      this.pos.x *= 0.98; this.pos.z *= 0.98;
    }

    // Acciones
    if (input.reload) this.startReload();
    if (input.swapTo != null) this.switchSlot(input.swapTo);
    else if (input.swap) this.cycleSlot(input.swapDir || 1);

    // Disparo
    if (input.firing && this.fireCooldown <= 0 && this.stun <= 0 && !this.reloading) {
      this.game.playerShoot();
    }

    // Animación
    const hSpeed = Math.hypot(this.vel.x, this.vel.z);
    this.character.root.position.copy(this.pos);
    this.character.root.rotation.y = this.yaw;
    this.character.rig.rotation.y = 0;
    this.character.update(dt, hSpeed, this.grounded, this.aiming, this.attacking > 0);
    this.character.muzzle.getWorldPosition(this.game.tmpMuzzle);
  }

  dispose() {
    this.character.root.parent?.remove(this.character.root);
  }
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';

/* ── helpers de geometría ── */
function paint(geo, color) {
  const c = new THREE.Color(color);
  const n = geo.attributes.position.count;
  const arr = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { arr[i * 3] = c.r; arr[i * 3 + 1] = c.g; arr[i * 3 + 2] = c.b; }
  geo.setAttribute('color', new THREE.BufferAttribute(arr, 3));
  return geo;
}
function bx(w, h, d, x, y, z, color) {
  const g = new THREE.BoxGeometry(w, h, d); paint(g, color); g.translate(x, y, z); return g;
}
function sp(r, x, y, z, color, sx = 1, sy = 1, sz = 1) {
  const g = new THREE.IcosahedronGeometry(r, 1); paint(g, color); g.scale(sx, sy, sz); g.translate(x, y, z); return g;
}
function co(r, h, x, y, z, color, rx = 0, ry = 0, rz = 0) {
  const g = new THREE.ConeGeometry(r, h, 6); paint(g, color);
  if (rx) g.rotateX(rx); if (ry) g.rotateY(ry); if (rz) g.rotateZ(rz);
  g.translate(x, y, z); return g;
}
function cy(r1, r2, h, x, y, z, color, rx = 0) {
  const g = new THREE.CylinderGeometry(r1, r2, h, 5); paint(g, color);
  if (rx) g.rotateX(rx);
  g.translate(x, y, z); return g;
}

function chickenGeo(immortal = false) {
  const body = immortal ? '#f4e8d0' : '#f7f1e3';
  const comb = immortal ? '#ff3b4e' : '#e04545';
  const g = [];
  g.push(sp(0.24, 0, 0.34, 0, body, 1, 0.9, 1.25));
  g.push(sp(0.15, 0, 0.55, 0.2, body, 1, 0.95, 1));
  g.push(co(0.045, 0.13, 0, 0.68, 0.19, comb, 0, 0, 0));
  g.push(co(0.035, 0.1, -0.04, 0.67, 0.18, comb, 0, 0, 0.3));
  g.push(co(0.035, 0.1, 0.04, 0.67, 0.18, comb, 0, 0, -0.3));
  g.push(co(0.055, 0.14, 0, 0.55, 0.37, '#f2a33a', Math.PI / 2, 0, 0));
  g.push(sp(0.035, -0.055, 0.59, 0.29, '#1a1a1a'));
  g.push(sp(0.035, 0.055, 0.59, 0.29, '#1a1a1a'));
  if (immortal) {
    g.push(sp(0.022, -0.055, 0.61, 0.32, '#ff2a3a'));
    g.push(sp(0.022, 0.055, 0.61, 0.32, '#ff2a3a'));
  }
  // alas
  g.push(bx(0.08, 0.18, 0.28, -0.22, 0.36, 0.02, immortal ? '#d8c8a8' : '#e8e0cc'));
  g.push(bx(0.08, 0.18, 0.28, 0.22, 0.36, 0.02, immortal ? '#d8c8a8' : '#e8e0cc'));
  // cola
  g.push(co(0.08, 0.24, 0, 0.42, -0.24, '#e8e0cc', -0.9, 0, 0));
  // patas
  g.push(cy(0.018, 0.018, 0.16, -0.08, 0.12, 0, '#d99a3a'));
  g.push(cy(0.018, 0.018, 0.16, 0.08, 0.12, 0, '#d99a3a'));
  if (immortal) {
    g.push(bx(0.34, 0.02, 0.34, 0, 0.05, 0, '#ff3b4e'));
  }
  return mergeGeometries(g, false);
}

function pigeonGeo() {
  const g = [];
  const body = '#b9c4d0', dark = '#7d8a99', white = '#e8eef4';
  g.push(sp(0.5, 0, 0.5, 0, body, 1, 0.9, 1.4));
  g.push(sp(0.26, 0, 0.86, 0.5, body, 1, 1, 1));
  g.push(co(0.12, 0.32, 0, 0.86, 0.82, '#f2a33a', Math.PI / 2, 0, 0));
  g.push(sp(0.06, -0.12, 0.94, 0.68, '#1a1a1a'));
  g.push(sp(0.06, 0.12, 0.94, 0.68, '#1a1a1a'));
  g.push(sp(0.09, 0, 0.9, 0.6, '#ff6b8a'));
  g.push(bx(0.9, 0.1, 0.55, -0.6, 0.62, -0.05, dark));
  g.push(bx(0.9, 0.1, 0.55, 0.6, 0.62, -0.05, dark));
  g.push(bx(0.5, 0.08, 0.3, -0.6, 0.55, -0.1, white));
  g.push(bx(0.5, 0.08, 0.3, 0.6, 0.55, -0.1, white));
  g.push(co(0.18, 0.6, 0, 0.42, -0.55, dark, -1.1, 0, 0));
  return mergeGeometries(g, false);
}

function wallTexture(color) {
  const c = document.createElement('canvas');
  c.width = 128; c.height = 256;
  const ctx = c.getContext('2d');
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, 128, 256);
  for (let i = 0; i < 90; i++) {
    ctx.fillStyle = `rgba(255,255,255,${Math.random() * 0.12})`;
    const x = Math.random() * 128;
    ctx.fillRect(x, Math.random() * 256, 1 + Math.random() * 2, 10 + Math.random() * 70);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(10, 1);
  return tex;
}

export class Hazards {
  constructor(scene, world, map, game) {
    this.scene = scene;
    this.world = world;
    this.map = map;
    this.game = game;
    this.safe = { x: (Math.random() - 0.5) * 40, z: (Math.random() - 0.5) * 40, r: 190 };
    this.zonePhase = 0;
    this.erupted = false;
    this.lavaRadius = 0;
    this.chickenKills = 0;
    this.funado = false;
    this.meteorTimer = 16 + Math.random() * 8;
    this.meteors = [];
    this.rockTimer = 0;
    this.rocks = [];
    this.pigeonTimer = 0;
    this.pigeons = [];
    this.chickens = [];
    this.immortalChickens = [];
    this.zoneTick = 0;
    this.peckTick = 0;
    this._pigeonWarned = false;
    this._lastZoneLabel = '';

    this.createChickens();
    this.createZoneWall();
  }

  /* ───────── pollos jueces ───────── */
  createChickens() {
    const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
    const geo = chickenGeo(false);
    this.world.chickenSpots.slice(0, 12).forEach((spot, i) => {
      const mesh = new THREE.Mesh(geo, mat);
      mesh.position.set(spot.x, spot.y, spot.z);
      mesh.rotation.y = Math.random() * Math.PI * 2;
      this.scene.add(mesh);
      this.chickens.push({
        mesh, pos: new THREE.Vector3(spot.x, spot.y, spot.z),
        alive: true, phase: Math.random() * 10, target: this.randomChickenTarget(spot),
        speed: 0.5 + Math.random() * 0.7, immortal: false, id: i,
      });
    });
  }

  randomChickenTarget(spot) {
    const a = Math.random() * Math.PI * 2;
    const r = 2 + Math.random() * 8;
    return new THREE.Vector3(spot.x + Math.cos(a) * r, 0, spot.z + Math.sin(a) * r);
  }

  hitChicken(origin, dir, maxDist) {
    let best = null, bestT = maxDist;
    const check = (list) => {
      for (const c of list) {
        if (!c.alive) continue;
        const center = c.pos.clone().add(new THREE.Vector3(0, 0.38, 0));
        const toC = center.clone().sub(origin);
        const t = toC.dot(dir);
        if (t < 0 || t > bestT) continue;
        const closest = origin.clone().addScaledVector(dir, t);
        if (closest.distanceTo(center) < 0.42) { best = c; bestT = t; }
      }
    };
    check(this.chickens);
    check(this.immortalChickens);
    return best ? { chicken: best, t: bestT } : null;
  }

  killChicken(chicken, byPlayer = false) {
    if (!chicken.alive) return;
    if (chicken.immortal) {
      // No se pueden matar: se teletransportan
      this.teleportImmortal(chicken);
      if (byPlayer) this.game.hud.toast('Los pollos inmortales no mueren. Solo se enfadan.');
      return;
    }
    chicken.alive = false;
    chicken.mesh.visible = false;
    this.game.effects.sparksAt(chicken.pos.clone().add(new THREE.Vector3(0, 0.4, 0)), 0xffffff, 12, 5, 1.2);
    this.game.effects.smokeAt(chicken.pos, 0xe8e0cc, 5, 1.5);
    this.game.effects.ring(chicken.pos, 1.1, 0xffd166);
    if (byPlayer) {
      this.chickenKills++;
      this.game.player.chickenKills = this.chickenKills;
      this.game.hud.chat(`🐔 <b>Pollo juez</b> eliminado · ${this.chickenKills}/10`, 'chicken');
      this.game.hud.toast(`Pollos jueces: ${this.chickenKills}/10`);
      if (this.chickenKills === 10 && !this.funado) this.triggerApocalypse();
    }
  }

  triggerApocalypse() {
    if (this.funado) return;
    this.funado = true;
    const name = this.game.playerName;
    this.game.hud.chat(`🐔 <b>A ${name} lo funaron los pollos por hate</b>`, 'chicken');
    this.game.hud.banner('APOCALIPSIS AVÍCOLA', 'La justicia de los pollos no descansa', 5, '#ffd166');
    this.game.hud.toast('🐔 ¡Los pollos inmortales te persiguen!');
    this.game.player.funado = true;

    const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
    const geo = chickenGeo(true);
    for (let i = 0; i < 6; i++) {
      const mesh = new THREE.Mesh(geo, mat);
      const pos = this.game.player.pos.clone().add(new THREE.Vector3((Math.random() - 0.5) * 8, 0, (Math.random() - 0.5) * 8));
      pos.y = this.world.heightAt(pos.x, pos.z);
      mesh.position.copy(pos);
      this.scene.add(mesh);
      this.immortalChickens.push({
        mesh, pos, alive: true, immortal: true, phase: Math.random() * 10,
        teleportTimer: 1 + Math.random() * 2, peckTimer: 0, id: i,
      });
    }
  }

  teleportImmortal(c) {
    const p = this.game.player;
    const fwd = new THREE.Vector3(Math.sin(p.yaw), 0, Math.cos(p.yaw));
    const right = new THREE.Vector3(Math.cos(p.yaw), 0, -Math.sin(p.yaw));
    const back = fwd.clone().multiplyScalar(-(3.5 + Math.random() * 3)).addScaledVector(right, (Math.random() - 0.5) * 5);
    const x = p.pos.x + back.x, z = p.pos.z + back.z;
    const y = this.world.heightAt(x, z);
    this.game.effects.smokeAt(c.pos.clone().add(new THREE.Vector3(0, 0.3, 0)), 0xffd166, 6, 1.5);
    c.pos.set(x, y, z);
    c.mesh.position.copy(c.pos);
    c.teleportTimer = 2.5 + Math.random() * 2;
    this.game.effects.sparksAt(c.pos.clone().add(new THREE.Vector3(0, 0.4, 0)), 0xffd166, 8, 4, 1);
  }

  updateChickens(dt) {
    // Pollos normales: deambulan
    for (const c of this.chickens) {
      if (!c.alive) continue;
      c.phase += dt * 2;
      const d = c.target.clone().sub(c.pos);
      d.y = 0;
      if (d.length() < 1.2) {
        c.target = this.randomChickenTarget(c.pos);
      } else {
        d.normalize();
        c.pos.x += d.x * c.speed * dt;
        c.pos.z += d.z * c.speed * dt;
        c.pos.y = this.world.heightAt(c.pos.x, c.pos.z);
        c.mesh.rotation.y = Math.atan2(d.x, d.z);
      }
      c.mesh.position.set(c.pos.x, c.pos.y + Math.abs(Math.sin(c.phase)) * 0.035, c.pos.z);
    }

    // Pollos inmortales: teletransporte + acoso
    if (!this.funado) return;
    const p = this.game.player;
    for (const c of this.immortalChickens) {
      if (!c.alive) continue;
      c.phase += dt * 5;
      c.teleportTimer -= dt;
      c.peckTimer -= dt;
      const d = new THREE.Vector3(p.pos.x - c.pos.x, 0, p.pos.z - c.pos.z);
      const dist = d.length();
      if (c.teleportTimer <= 0) {
        // Si está a la vista, se teletransporta fuera de ella
        const toChicken = new THREE.Vector3(c.pos.x - p.pos.x, 0, c.pos.z - p.pos.z).normalize();
        const fwd = new THREE.Vector3(Math.sin(p.yaw), 0, Math.cos(p.yaw));
        if (toChicken.dot(fwd) > 0.2 || dist > 18) this.teleportImmortal(c);
        else c.teleportTimer = 1.2;
      }
      if (dist > 1.2) {
        d.normalize();
        c.pos.x += d.x * 4.6 * dt;
        c.pos.z += d.z * 4.6 * dt;
        c.pos.y = this.world.heightAt(c.pos.x, c.pos.z);
        c.mesh.rotation.y = Math.atan2(d.x, d.z);
      } else if (c.peckTimer <= 0) {
        c.peckTimer = 0.65 + Math.random() * 0.35;
        if (p.alive && !p.dropping) {
          p.takeDamage(2, 'Los Pollos Justicieros', 'picotazo');
          this.game.aimWobble = Math.max(this.game.aimWobble, 0.9);
          this.game.shake = Math.max(this.game.shake, 0.18);
          this.game.hud.chat('🐔 <b>PICOTAZO</b> · -2 HP · los pollos te están funando', 'chicken');
        }
      }
      c.mesh.position.set(c.pos.x, c.pos.y + Math.abs(Math.sin(c.phase)) * 0.08, c.pos.z);
      c.mesh.rotation.z = Math.sin(c.phase * 2) * 0.12;
    }
  }

  /* ───────── zona / muro ───────── */
  createZoneWall() {
    const color = this.map.toxic ? '#5affb0' : this.map.storm ? '#d8d0be' : '#ff8a3d';
    const tex = wallTexture(color);
    const mat = new THREE.MeshBasicMaterial({
      map: tex, color: new THREE.Color(color), transparent: true, opacity: 0.16,
      side: THREE.DoubleSide, depthWrite: false,
    });
    const geo = new THREE.CylinderGeometry(1, 1, 1, 48, 1, true);
    this.wall = new THREE.Mesh(geo, mat);
    this.wall.position.y = 35;
    this.wall.renderOrder = 2;
    this.scene.add(this.wall);

    const ringMat = new THREE.MeshBasicMaterial({
      color: new THREE.Color(color), transparent: true, opacity: 0.55,
      side: THREE.DoubleSide, depthWrite: false,
    });
    this.zoneRing = new THREE.Mesh(new THREE.RingGeometry(0.985, 1, 64), ringMat);
    this.zoneRing.rotation.x = -Math.PI / 2;
    this.zoneRing.position.y = 0.5;
    this.scene.add(this.zoneRing);
  }

  zoneRadiusAt(t) {
    if (t < 80) return 190;
    if (t < 140) return 190 + (120 - 190) * ((t - 80) / 60);
    if (t < 160) return 120;
    if (t < 205) return 120 + (75 - 120) * ((t - 160) / 45);
    if (t < 220) return 75;
    if (t < 260) return 75 + (40 - 75) * ((t - 220) / 40);
    if (t < 270) return 40;
    if (t < 300) return 40 + (18 - 40) * ((t - 270) / 30);
    return 18;
  }

  zoneLabel(t) {
    if (t < 80) return `${Math.ceil(80 - t)}s`;
    if (t < 140) return 'CERRANDO';
    if (t < 160) return `${Math.ceil(160 - t)}s`;
    if (t < 205) return 'CERRANDO';
    if (t < 220) return `${Math.ceil(220 - t)}s`;
    if (t < 260) return 'CERRANDO';
    if (t < 270) return `${Math.ceil(270 - t)}s`;
    if (t < 300) return 'FINAL';
    return 'FINAL';
  }

  lavaAt(x, z) {
    if (!this.erupted) return false;
    return Math.hypot(x - 10, z - 105) < this.lavaRadius;
  }

  updateZone(dt, t) {
    this.safe.r = this.zoneRadiusAt(t);
    const s = this.safe;
    this.wall.position.set(s.x, 35, s.z);
    this.wall.scale.set(s.r, 80, s.r);
    this.zoneRing.position.set(s.x, 0.5, s.z);
    this.zoneRing.scale.setScalar(s.r);
    this.zoneRing.material.opacity = 0.35 + Math.sin(t * 3) * 0.12;

    // Erupción volcánica
    if (this.map.lava && t >= 120 && !this.erupted) {
      this.erupted = true;
      this.lavaRadius = 26;
      this.world.setEruption(true);
      this.game.hud.banner('🌋 ERUPCIÓN MASIVA', 'Rocas ardientes y lava se extienden por el mapa', 5.5, '#ff7a2f');
      this.game.hud.chat('🌋 <b>El volcán entró en erupción</b> · la lava avanza', 'meteor');
      this.game.scene.fog.color.setHex(0x4a1c12);
      this.game.scene.fog.density = 0.006;
      this.game.hud.toast('🌋 ¡Corre! La lava avanza desde el volcán');
    }
    if (this.erupted) {
      this.lavaRadius = Math.min(175, 26 + (t - 120) * 1.15);
      this.rockTimer -= dt;
      if (this.rockTimer <= 0) {
        this.rockTimer = 1.6 + Math.random() * 2;
        this.spawnBurningRock();
      }
    }

    // Daño de zona cada 0.5s
    this.zoneTick -= dt;
    if (this.zoneTick <= 0 && t > 80) {
      this.zoneTick = 0.5;
      for (const e of this.game.aliveEntities()) {
        if (!e.alive || e.dropping) continue;
        const isPlayer = e === this.game.player;
        const outside = Math.hypot(e.pos.x - s.x, e.pos.z - s.z) > s.r;
        const inLava = this.lavaAt(e.pos.x, e.pos.z);
        if (outside || inLava) {
          const masked = isPlayer && this.map.toxic && this.game.player.maskTime > 0;
          if (masked && outside && !inLava) continue;
          let dmg = inLava ? 12 : this.map.toxic ? 11 : this.map.storm ? 8 : 9;
          if (isPlayer) this.game.player.takeDamage(dmg, inLava ? 'La lava' : 'La zona', '');
          else this.game.damageEntity(e, dmg, 'La zona', '');
        }
      }
    }

    // Rocas ardientes / meteoritos / palomas
    this.updateRocks(dt);
    this.updateMeteors(dt);
    this.updatePigeons(dt);
  }

  spawnBurningRock() {
    const a = Math.random() * Math.PI * 2;
    const d = 20 + Math.random() * 120;
    const x = 10 + Math.cos(a) * d, z = 105 + Math.sin(a) * d;
    const mesh = new THREE.Mesh(
      new THREE.IcosahedronGeometry(0.7 + Math.random() * 0.9, 0),
      new THREE.MeshBasicMaterial({ color: 0xff5a1f, toneMapped: false })
    );
    mesh.position.set(x + (Math.random() - 0.5) * 12, 70, z + (Math.random() - 0.5) * 12);
    this.scene.add(mesh);
    this.rocks.push({ mesh, vy: 26 + Math.random() * 12, targetY: this.world.heightAt(x, z), life: 8, x, z });
  }

  updateRocks(dt) {
    for (let i = this.rocks.length - 1; i >= 0; i--) {
      const r = this.rocks[i];
      r.life -= dt;
      r.mesh.position.y -= r.vy * dt;
      r.mesh.rotation.x += dt * 4;
      r.mesh.rotation.z += dt * 3;
      if (Math.random() < 0.6) this.game.effects.sparksAt(r.mesh.position, 0xff7a2f, 1, 2, 0.4);
      if (r.mesh.position.y <= r.targetY) {
        const pos = r.mesh.position.clone();
        this.game.effects.explosion(pos, 3.5, 0xff5a1f);
        this.game.effects.ring(pos, 3.5, 0xff7a2f);
        for (const e of this.game.aliveEntities()) {
          if (!e.alive) continue;
          if (e.pos.distanceTo(pos) < 4) {
            if (e === this.game.player) {
              this.game.player.takeDamage(24, 'Una roca ardiente', '');
              this.game.shake = Math.max(this.game.shake, 0.5);
            } else this.game.damageEntity(e, 24, 'Una roca ardiente', '');
          }
        }
        this.scene.remove(r.mesh);
        r.mesh.geometry.dispose();
        this.rocks.splice(i, 1);
      } else if (r.life <= 0) {
        this.scene.remove(r.mesh); r.mesh.geometry.dispose(); this.rocks.splice(i, 1);
      }
    }
  }

  /* ───────── meteorito de la humillación ───────── */
  updateMeteors(dt) {
    this.meteorTimer -= dt;
    if (this.meteorTimer <= 0) {
      this.meteorTimer = 20 + Math.random() * 16;
      this.spawnMeteor();
    }
    for (let i = this.meteors.length - 1; i >= 0; i--) {
      const m = this.meteors[i];
      m.t -= dt;
      const k = 1 - m.t / m.dur;
      m.mesh.position.lerpVectors(m.from, m.to, k);
      m.mesh.rotation.x += dt * 8;
      if (Math.random() < 0.7) this.game.effects.sparksAt(m.mesh.position, 0xff7a2f, 1, 1.5, 0.3);
      if (m.t <= 0) {
        const pos = m.to.clone();
        this.game.effects.explosion(pos, 2.4, 0xff7a2f);
        this.game.effects.ring(pos, 2.2, 0xff7a2f);
        this.game.effects.smokeAt(pos, 0x3a2a24, 8, 2);
        if (m.target && m.target.alive) {
          if (m.target === this.game.player) {
            this.game.player.takeDamage(5, 'El Meteorito de la Humillación', '');
            this.game.shake = Math.max(this.game.shake, 0.35);
          } else {
            this.game.damageEntity(m.target, 5, 'El Meteorito de la Humillación', '');
          }
        }
        this.game.hud.chat(`☄️ <b>«A ${m.targetName} le cayó un meteorito, qué pena, terrible...»</b>`, 'meteor');
        this.scene.remove(m.mesh);
        m.mesh.geometry.dispose();
        m.mesh.material.dispose();
        this.meteors.splice(i, 1);
      }
    }
  }

  spawnMeteor() {
    const entities = this.game.aliveEntities().filter((e) => e.alive && !e.dropping);
    if (!entities.length) return;
    const target = entities[Math.floor(Math.random() * entities.length)];
    const targetName = target === this.game.player ? this.game.playerName : target.name;
    const to = target.pos.clone();
    to.y = this.world.heightAt(to.x, to.z) + 0.2;
    const from = to.clone().add(new THREE.Vector3(12 + Math.random() * 18, 90 + Math.random() * 30, 12 + Math.random() * 18));
    const mesh = new THREE.Mesh(
      new THREE.IcosahedronGeometry(0.75, 0),
      new THREE.MeshBasicMaterial({ color: 0xff7a2f, toneMapped: false })
    );
    mesh.position.copy(from);
    this.scene.add(mesh);
    this.meteors.push({ mesh, from, to, t: 1.8, dur: 1.8, target, targetName });
  }

  /* ───────── palomas cósmicas ───────── */
  updatePigeons(dt) {
    const p = this.game.player;
    this.pigeonTimer -= dt;
    if (this.pigeonTimer <= 0 && p.alive && !p.dropping) {
      this.pigeonTimer = 0.5;
      const outOfBounds = Math.hypot(p.pos.x, p.pos.z) > 205;
      const tooHigh = p.pos.y > 42;
      const below = p.pos.y < -2;
      if ((outOfBounds || tooHigh || below) && !this._pigeonWarned) {
        this._pigeonWarned = true;
        this.game.hud.banner('🚫 ZONA NO AUTORIZADA', 'Las Palomas Cósmicas han detectado un camper', 3.5, '#35f0ff');
        this.game.hud.chat('🐦 <b>Las Palomas Cósmicas descienden...</b>', 'pigeon');
        this.spawnPigeons(p.pos.clone(), () => {
          if (p.alive) {
            this.game.hud.chat(`🐦 <b>Las Palomas Cósmicas ajusticiaron a ${this.game.playerName} por camper</b>`, 'pigeon');
            this.game.killPlayer('Las Palomas Cósmicas', 'justicia divina');
          }
        });
      }
    }
    if (this._pigeonWarned && p.alive && !this.pigeons.length) {
      // ya ejecutado o el jugador volvió: reset
      this._pigeonWarned = false;
    }

    for (let i = this.pigeons.length - 1; i >= 0; i--) {
      const pg = this.pigeons[i];
      pg.t -= dt;
      const k = Math.min(1, 1 - pg.t / pg.dur);
      pg.mesh.position.lerpVectors(pg.from, pg.to, k * k);
      pg.mesh.rotation.z = Math.sin(performance.now() * 0.02 + i) * 0.3;
      pg.wingL.rotation.z = Math.sin(performance.now() * 0.03 + i) * 0.9;
      pg.wingR.rotation.z = -Math.sin(performance.now() * 0.03 + i) * 0.9;
      if (pg.t <= 0) {
        pg.onDone?.();
        this.scene.remove(pg.mesh);
        this.pigeons.splice(i, 1);
        setTimeout(() => { this._pigeonWarned = false; }, 1500);
      }
    }
  }

  spawnPigeons(pos, onDone) {
    const geo = pigeonGeo();
    const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
    for (let i = 0; i < 3; i++) {
      const mesh = new THREE.Mesh(geo, mat);
      mesh.scale.setScalar(3.2);
      const from = pos.clone().add(new THREE.Vector3((i - 1) * 14 + (Math.random() - 0.5) * 6, 34 + i * 5, 10 + Math.random() * 12));
      mesh.position.copy(from);
      const wingL = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.12, 0.9), mat.clone());
      const wingR = wingL.clone();
      wingL.position.set(-1.0, 0.6, 0);
      wingR.position.set(1.0, 0.6, 0);
      mesh.add(wingL, wingR);
      this.scene.add(mesh);
      this.pigeons.push({
        mesh, from, to: pos.clone().add(new THREE.Vector3(0, 1.2, 0)),
        t: 1.35 + i * 0.12, dur: 1.35, wingL, wingR,
        onDone: i === 0 ? onDone : null,
      });
    }
  }

  update(dt, t) {
    this.updateZone(dt, t);
    this.updateChickens(dt);
    // Anillo del muro
    this.wall.material.opacity = 0.12 + Math.sin(t * 2) * 0.03;
  }

  dispose() {
    this.scene.remove(this.wall, this.zoneRing);
    for (const c of this.chickens) this.scene.remove(c.mesh);
    for (const c of this.immortalChickens) this.scene.remove(c.mesh);
    for (const m of this.meteors) this.scene.remove(m.mesh);
    for (const r of this.rocks) this.scene.remove(r.mesh);
    for (const p of this.pigeons) this.scene.remove(p.mesh);
  }
}

import * as THREE from 'three';
import { createWorld } from './world/World.js';
import { Player } from './entities/Player.js';
import { Bot } from './entities/Bot.js';
import { Effects } from './systems/Effects.js';
import { Hazards } from './systems/Hazards.js';
import { HUD } from './ui/HUD.js';
import { Input } from './core/Input.js';
import { WEAPONS, randomWeapon, RARITY } from './data/weapons.js';
import { BOT_NAMES, CHAT_LINES } from './data/maps.js';

const $ = (id) => document.getElementById(id);
const rand = (a, b) => a + Math.random() * (b - a);
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

function raySphere(origin, dir, center, radius) {
  const oc = center.clone().sub(origin);
  const t = oc.dot(dir);
  if (t < 0) return -1;
  const d2 = oc.lengthSq() - t * t;
  const r2 = radius * radius;
  if (d2 > r2) return -1;
  return t - Math.sqrt(r2 - d2);
}

export class Game {
  constructor({ renderer, map, skin, quality, onRestart, onExit }) {
    this.renderer = renderer;
    this.map = map;
    this.skin = skin;
    this.quality = quality;
    this.opts = { onRestart, onExit };
    this.canvas = renderer.domElement;
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(70, innerWidth / innerHeight, 0.08, 460);
    this.time = 0;
    this.state = 'drop';
    this.aliveCount = 30;
    this.kills = 0;
    this.damageDealt = 0;
    this.shake = 0;
    this.aimWobble = 0;
    this.tmpMuzzle = new THREE.Vector3();
    this.projectiles = [];
    this.boomerangs = [];
    this.burnZones = [];
    this.ambientTimer = 14;
    this.lastFrame = 0;
    this.fpsAcc = 0; this.fpsFrames = 0; this.fpsCheck = 0; this.downgraded = false;
    this.pausedFrom = 'drop';
    this.disposed = false;
    this.ac = new AbortController();

    this.playerName = skin.gloves ? 'Miguel Furioso' : 'Miguel';

    // Calidad / render
    const dpr = Math.min(devicePixelRatio || 1, 2);
    let pr = dpr;
    if (quality === 'baja') pr = 1;
    else if (quality === 'auto') pr = Math.min(dpr, matchMedia('(pointer: coarse)').matches ? 1.4 : 2);
    renderer.setPixelRatio(pr);
    renderer.setSize(innerWidth, innerHeight, false);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.NoToneMapping;

    this.world = createWorld(this.scene, map, { quality });
    this.effects = new Effects(this.scene);
    this.hud = new HUD({ map, skin, world: this.world });

    // Spawn del jugador
    const pSpawn = this.findSpawn(55, 140);
    this.player = new Player(this, skin);
    this.player.pos.set(pSpawn.x, 92, pSpawn.z);
    this.player.yaw = Math.random() * Math.PI * 2;
    this.player.character.root.position.copy(this.player.pos);

    this.hazards = new Hazards(this.scene, this.world, map, this);

    // Bots
    this.bots = [];
    const names = [...BOT_NAMES].sort(() => Math.random() - 0.5);
    for (let i = 0; i < 29; i++) {
      const sp = this.findSpawn(20, 178, pSpawn, 22);
      const bot = new Bot(this, names[i % names.length], i + 1, { x: sp.x, y: 60, z: sp.z, drop: true });
      this.bots.push(bot);
    }

    this.createPickups();
    this.createBotShadows();

    this.input = new Input(this.canvas, {
      onPause: () => this.pause(),
      onFirstLock: () => this.hud.toast('Clic para bloquear el ratón · Esc para pausar'),
    });

    // Eventos UI
    $('pause-btn').onclick = () => this.pause();
    $('resume-btn').onclick = () => this.resume();
    $('quit-btn').onclick = () => this.quit();
    $('again-btn').onclick = () => this.opts.onRestart?.();
    $('menu-btn').onclick = () => this.quit();
    $('special-btn').onclick = () => this.useSpecial();
    $('reload-btn').onclick = () => this.player.startReload();

    addEventListener('resize', () => this.resize(), { signal: this.ac.signal });
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && (this.state === 'playing' || this.state === 'drop')) this.pause();
    }, { signal: this.ac.signal });

    this.updateCamera(0.016, true);
    this.hud.show();
    this.hud.setDrop(92);
    this.hud.banner('SALTO EN PARACAÍDAS', 'Elige dónde aterrizar · WASD / joystick para planear', 4, '#35f0ff');
    this.hud.chat('💬 <b>Cheems:</b> que empiece el caos', '');
    this.hud.chat('🐔 <b>Sistema:</b> 12 pollos jueces vigilan el mapa', 'chicken');

    this.input.setEnabled(true);
    this.input.requestLock();
    this.loop = this.loop.bind(this);
    this.raf = requestAnimationFrame(this.loop);
  }

  /* ───────── spawns ───────── */
  findSpawn(minR, maxR, avoid, avoidDist = 0) {
    const world = this.world;
    for (let i = 0; i < 120; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = rand(minR, maxR);
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      if (Math.hypot(x, z) > 190) continue;
      if (world.heightAt(x, z) < 1.2) continue;
      let inside = false;
      for (const c of world.colliders) {
        if (x > c.minX - 2 && x < c.maxX + 2 && z > c.minZ - 2 && z < c.maxZ + 2) { inside = true; break; }
      }
      if (inside) continue;
      if (avoid && Math.hypot(x - avoid.x, z - avoid.z) < avoidDist) continue;
      return { x, z };
    }
    return { x: rand(-50, 50), z: rand(-50, 50) };
  }

  /* ───────── pickups ───────── */
  createPickups() {
    const cap = 170;
    this.pickupCap = cap;
    this.pickups = [];
    const geo = new THREE.BoxGeometry(0.5, 0.5, 0.5);
    const mat = new THREE.MeshBasicMaterial({ toneMapped: false });
    this.pickupMesh = new THREE.InstancedMesh(geo, mat, cap);
    this.pickupMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.pickupMesh.frustumCulled = false;
    this.scene.add(this.pickupMesh);

    const bgeo = new THREE.BoxGeometry(0.07, 1.7, 0.07);
    const bmat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0.3, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
    this.beamMesh = new THREE.InstancedMesh(bgeo, bmat, cap);
    this.beamMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.beamMesh.frustumCulled = false;
    this.scene.add(this.beamMesh);

    // Armas
    for (const spot of this.world.lootSpots) {
      this.addPickup('weapon', spot.x, spot.z, spot.y, randomWeapon());
    }
    // Salud y munición
    for (let i = 0; i < 14; i++) {
      const s = this.world.lootSpots[(i * 7 + 3) % this.world.lootSpots.length];
      this.addPickup('health', s.x + rand(-7, 7), s.z + rand(-7, 7));
    }
    for (let i = 0; i < 14; i++) {
      const s = this.world.lootSpots[(i * 5 + 1) % this.world.lootSpots.length];
      this.addPickup('ammo', s.x + rand(-7, 7), s.z + rand(-7, 7));
    }
    // Máscaras de gas
    if (this.map.toxic) {
      for (const s of this.world.gasMaskSpots) this.addPickup('mask', s.x, s.z, s.y);
    } else {
      for (let i = 0; i < 3; i++) {
        const s = this.world.lootSpots[(i * 13 + 5) % this.world.lootSpots.length];
        this.addPickup('mask', s.x + rand(-5, 5), s.z + rand(-5, 5));
      }
    }
    // Inicializar colores
    for (let i = 0; i < this.pickups.length; i++) {
      const p = this.pickups[i];
      const col = this.pickupColor(p);
      this.pickupMesh.setColorAt(i, col);
      this.beamMesh.setColorAt(i, col);
    }
    if (this.pickupMesh.instanceColor) this.pickupMesh.instanceColor.needsUpdate = true;
    if (this.beamMesh.instanceColor) this.beamMesh.instanceColor.needsUpdate = true;
    this.updatePickupInstances(0);
  }

  pickupColor(p) {
    if (p.type === 'health') return new THREE.Color(0x7dffb0);
    if (p.type === 'ammo') return new THREE.Color(0xffd166);
    if (p.type === 'mask') return new THREE.Color(0x35f0ff);
    const w = WEAPONS[p.weaponId];
    return new THREE.Color(RARITY[w?.rarity || 'common'].glow);
  }

  addPickup(type, x, z, y, weaponId) {
    if (this.pickups.length >= this.pickupCap) return null;
    const yy = y != null ? y : this.world.heightAt(x, z);
    const p = {
      type, x, z, y: yy, weaponId, taken: false,
      phase: Math.random() * Math.PI * 2, idx: this.pickups.length,
    };
    this.pickups.push(p);
    return p;
  }

  updatePickupInstances(t) {
    const dummy = this._dummy || (this._dummy = new THREE.Object3D());
    const beamDummy = this._beamDummy || (this._beamDummy = new THREE.Object3D());
    for (let i = 0; i < this.pickupCap; i++) {
      const p = this.pickups[i];
      if (!p || p.taken) {
        dummy.position.set(0, -999, 0); dummy.scale.setScalar(0.0001); dummy.updateMatrix();
        this.pickupMesh.setMatrixAt(i, dummy.matrix);
        this.beamMesh.setMatrixAt(i, dummy.matrix);
        continue;
      }
      const bob = Math.sin(t * 2.2 + p.phase) * 0.12;
      dummy.position.set(p.x, p.y + 0.55 + bob, p.z);
      dummy.rotation.set(0.25, t * 1.2 + p.phase, 0.1);
      dummy.scale.setScalar(1);
      dummy.updateMatrix();
      this.pickupMesh.setMatrixAt(i, dummy.matrix);
      beamDummy.position.set(p.x, p.y + 1.45 + bob, p.z);
      beamDummy.rotation.set(0, 0, 0);
      beamDummy.scale.set(1, 1, 1);
      beamDummy.updateMatrix();
      this.beamMesh.setMatrixAt(i, beamDummy.matrix);
    }
    this.pickupMesh.instanceMatrix.needsUpdate = true;
    this.beamMesh.instanceMatrix.needsUpdate = true;
  }

  takePickup(p) {
    if (!p || p.taken) return;
    if (p.type === 'weapon') {
      const w = WEAPONS[p.weaponId];
      if (!w) return;
      this.player.addWeapon(p.weaponId);
      p.taken = true;
      this.effects.ring(new THREE.Vector3(p.x, p.y, p.z), 1.6, RARITY[w.rarity].glow);
      this.effects.sparksAt(new THREE.Vector3(p.x, p.y + 0.5, p.z), RARITY[w.rarity].glow, 10, 4, 1);
      this.hud.chat(`🎁 <b>${this.playerName}</b> recogió ${w.emoji} ${w.name}`, '');
    } else if (p.type === 'health') {
      this.player.heal(250);
      p.taken = true;
      this.hud.toast('❤️ +250 HP');
      this.effects.sparksAt(new THREE.Vector3(p.x, p.y + 0.5, p.z), 0x7dffb0, 10, 3, 1);
    } else if (p.type === 'ammo') {
      for (const it of this.player.slots) {
        const w = WEAPONS[it.id];
        if (w.reserve !== Infinity) it.reserve = Math.min(w.reserve * 2, it.reserve + Math.ceil(w.reserve * 0.6));
      }
      p.taken = true;
      this.hud.toast('📦 Munición recargada');
    } else if (p.type === 'mask') {
      this.player.maskTime = 60;
      p.taken = true;
      this.hud.toast('😷 Máscara de gas · 60s de inmunidad tóxica');
      this.hud.chat('😷 <b>Máscara de gas antigua</b> equipada · 60s', '');
      this.effects.ring(new THREE.Vector3(p.x, p.y, p.z), 1.4, 0x35f0ff);
    }
  }

  nearestPickup(maxDist = 3) {
    let best = null, bestD = maxDist;
    const pp = this.player.pos;
    for (const p of this.pickups) {
      if (p.taken || p.type !== 'weapon') continue;
      const d = Math.hypot(p.x - pp.x, p.z - pp.z);
      if (d < bestD && Math.abs(p.y - pp.y) < 3) { best = p; bestD = d; }
    }
    return best;
  }

  updatePickups(dt) {
    this.updatePickupInstances(this.time);
    if (!this.player.alive || this.player.dropping) { this.hud.setPrompt(null); return; }

    // Auto-recogida
    this._autoT = (this._autoT || 0) - dt;
    if (this._autoT <= 0) {
      this._autoT = 0.18;
      for (const p of this.pickups) {
        if (p.taken || p.type === 'weapon') continue;
        if (Math.hypot(p.x - this.player.pos.x, p.z - this.player.pos.z) < 1.9 && Math.abs(p.y - this.player.pos.y) < 2.2) {
          this.takePickup(p);
        }
      }
    }
    const near = this.nearestPickup(3.2);
    this.nearPickup = near;
    if (near) {
      const w = WEAPONS[near.weaponId];
      this.hud.setPrompt(`Recoger ${w.emoji} ${w.name} · ${RARITY[w.rarity].label}`);
    } else {
      this.hud.setPrompt(null);
    }
  }

  /* ───────── sombras de bots ───────── */
  createBotShadows() {
    const geo = new THREE.CircleGeometry(0.4, 10);
    const mat = new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.28, depthWrite: false });
    this.botShadows = new THREE.InstancedMesh(geo, mat, this.bots.length);
    this.botShadows.frustumCulled = false;
    this.scene.add(this.botShadows);
  }

  updateBotShadows() {
    const d = this._shadowDummy || (this._shadowDummy = new THREE.Object3D());
    for (let i = 0; i < this.bots.length; i++) {
      const b = this.bots[i];
      d.position.set(b.pos.x, b.pos.y + 0.03, b.pos.z);
      d.rotation.x = -Math.PI / 2;
      d.scale.setScalar(b.alive ? 1 : 0.0001);
      d.updateMatrix();
      this.botShadows.setMatrixAt(i, d.matrix);
    }
    this.botShadows.instanceMatrix.needsUpdate = true;
  }

  /* ───────── combate ───────── */
  getAimDir(spread = 0) {
    const dir = new THREE.Vector3();
    this.camera.getWorldDirection(dir);
    if (spread > 0) {
      dir.x += (Math.random() - 0.5) * spread * 2;
      dir.y += (Math.random() - 0.5) * spread * 2;
      dir.z += (Math.random() - 0.5) * spread * 2;
      dir.normalize();
    }
    return dir;
  }

  playerShoot() {
    const p = this.player;
    if (!p.alive || p.dropping) return;
    const w = p.weapon;
    const item = p.item;
    if (!item) return;
    if (!w.melee && item.mag <= 0) {
      p.startReload();
      return;
    }
    p.fireCooldown = w.fireRate;
    p.attacking = 0.18;
    p.character.muzzle.getWorldPosition(this.tmpMuzzle);

    if (w.melee) {
      if (w.rangedMelee) this.chanclaThrow(w);
      else this.meleeAttack(w);
      return;
    }

    if (item.mag !== Infinity) item.mag--;
    const spread = w.spread + (p.grounded ? 0 : 0.025) + (p.aiming ? -w.spread * 0.45 : 0);
    this.effects.muzzle(this.tmpMuzzle);
    this.effects.sparksAt(this.tmpMuzzle, 0xffd166, 2, 2, 0.4);
    this.shake = Math.max(this.shake, (w.recoil || 0.02) * 1.2);

    if (w.flame) {
      this.flameAttack(w);
    } else if (w.projectileSpeed) {
      this.spawnProjectile(w);
    } else {
      const pellets = w.pellets || 1;
      const per = w.pellets ? w.damage / w.pellets : w.damage;
      for (let i = 0; i < pellets; i++) {
        this.hitscan(w, Math.max(0.002, spread), per, i === 0);
      }
    }

    // Recoil de cámara
    p.pitch = clamp(p.pitch + (w.recoil || 0.012) * 0.5, -0.52, 0.95);
    p.yaw += (Math.random() - 0.5) * (w.recoil || 0.01) * 0.5;

    if (item.mag === 0 && item.reserve > 0) p.startReload();
  }

  hitscan(w, spread, damage, showTracer = true) {
    const origin = this.camera.position.clone();
    const dir = this.getAimDir(spread);
    const range = w.range || 100;
    const end = origin.clone().addScaledVector(dir, range);
    const wall = this.world.segmentHit(origin, end);
    let bestT = wall.hit ? wall.t * range : range;
    let hitBot = null, hitHead = false;

    for (const b of this.bots) {
      if (!b.alive || b.dropping) continue;
      const tBody = raySphere(origin, dir, b.chest, 0.42);
      const tHead = raySphere(origin, dir, b.head, 0.24);
      let t = -1, head = false;
      if (tHead > 0 && (tBody < 0 || tHead < tBody)) { t = tHead; head = true; }
      else if (tBody > 0) { t = tBody; }
      if (t > 0 && t < bestT) { bestT = t; hitBot = b; hitHead = head; }
    }

    // Pollos
    let hitChicken = null;
    const ch = this.hazards.hitChicken(origin, dir, Math.min(range, bestT));
    if (ch) { hitChicken = ch.chicken; bestT = ch.t; hitBot = null; }

    const point = origin.clone().addScaledVector(dir, bestT);
    if (showTracer) this.effects.tracer(this.tmpMuzzle.clone(), point, RARITY[w.rarity]?.glow || 0xffd166);

    if (hitBot) {
      let dmg = damage;
      let crit = false;
      if (hitHead && w.headshot) { dmg = w.headshot; crit = true; }
      if (w.melee && this.skin.meleeBonus) dmg *= 1 + this.skin.meleeBonus;
      this.applyHit(hitBot, dmg, w, point, crit);
    } else if (hitChicken) {
      this.hazards.killChicken(hitChicken, true);
      this.hud.hitmarker();
      this.effects.sparksAt(point, 0xffd166, 8, 4, 1);
    } else if (wall.hit) {
      this.effects.sparksAt(point, 0xffd166, 4, 3, 0.8);
    }
  }

  applyHit(bot, damage, w, point, crit) {
    if (!bot.alive) return;
    this.damageDealt += damage;
    bot.takeDamage(damage, this.player, w.name);
    this.hud.hitmarker(crit);
    this.effects.sparksAt(point, crit ? 0xffd166 : 0xff5a5a, crit ? 14 : 7, 5, 1);
    if (w.stun) bot.stun = Math.max(bot.stun, w.stun);
    if (w.knockback) {
      const dir = new THREE.Vector3(bot.pos.x - this.player.pos.x, 0, bot.pos.z - this.player.pos.z).normalize();
      bot.applyKnockback(dir, w.knockback);
    }
  }

  meleeAttack(w) {
    const p = this.player;
    const origin = p.chest.clone();
    const dir = this.getAimDir(0);
    let hitAny = false;
    let best = null, bestD = w.range + 0.5;
    for (const b of this.bots) {
      if (!b.alive || b.dropping) continue;
      const to = b.chest.clone().sub(origin);
      const d = to.length();
      if (d > bestD) continue;
      to.normalize();
      if (to.dot(dir) < 0.3) continue;
      best = b; bestD = d;
    }
    this.effects.ring(p.pos.clone().addScaledVector(new THREE.Vector3(Math.sin(p.yaw), 0, Math.cos(p.yaw)), 1.2), 1.8, 0xffd166);
    this.shake = Math.max(this.shake, 0.12);
    if (best) {
      let dmg = w.damage * (1 + (this.skin.meleeBonus || 0));
      this.damageDealt += dmg;
      best.takeDamage(dmg, p, w.name);
      best.applyKnockback(new THREE.Vector3(Math.sin(p.yaw), 0, Math.cos(p.yaw)), w.knockback || 3);
      if (w.stun) best.stun = Math.max(best.stun, w.stun);
      this.hud.hitmarker();
      this.effects.sparksAt(best.chest, 0xff5a5a, 10, 5, 1);
      hitAny = true;
    }
    if (!hitAny) this.effects.sparksAt(origin.clone().addScaledVector(dir, 1.5), 0xffffff, 4, 2, 0.6);
  }

  chanclaThrow(w) {
    const p = this.player;
    const dir = this.getAimDir(0.005);
    const origin = p.chest.clone();
    const range = 50;
    let bestT = range, hitBot = null, hitChicken = null;
    const wall = this.world.segmentHit(origin, origin.clone().addScaledVector(dir, range));
    if (wall.hit) bestT = wall.t * range;
    for (const b of this.bots) {
      if (!b.alive || b.dropping) continue;
      const t = raySphere(origin, dir, b.chest, 0.45);
      if (t > 0 && t < bestT) { bestT = t; hitBot = b; }
    }
    const ch = this.hazards.hitChicken(origin, dir, bestT);
    if (ch) { hitChicken = ch.chicken; bestT = ch.t; hitBot = null; }
    const end = origin.clone().addScaledVector(dir, bestT);

    // Visual del búmeran
    const mesh = new THREE.Mesh(
      new THREE.BoxGeometry(0.18, 0.05, 0.5),
      new THREE.MeshBasicMaterial({ color: 0xff4d9a, toneMapped: false })
    );
    mesh.position.copy(p.chest);
    this.scene.add(mesh);
    this.boomerangs.push({ mesh, from: p.chest.clone(), to: end.clone(), t: 0, phase: 'out', target: hitBot, chicken: hitChicken });

    if (hitBot) {
      const dmg = w.damage * (1 + (this.skin.meleeBonus || 0));
      this.damageDealt += dmg;
      hitBot.takeDamage(dmg, p, w.name);
      hitBot.applyKnockback(dir.clone().setY(0).normalize(), 4);
      this.hud.hitmarker();
      this.effects.sparksAt(end, 0xff4d9a, 12, 5, 1);
    } else if (hitChicken) {
      this.hazards.killChicken(hitChicken, true);
    }
    this.shake = Math.max(this.shake, 0.14);
  }

  flameAttack(w) {
    const p = this.player;
    const origin = p.chest.clone();
    const dir = this.getAimDir(0.03);
    const muzzle = this.tmpMuzzle.clone();
    const end = origin.clone().addScaledVector(dir, 16);
    this.effects.smokeAt(muzzle, 0xff7a2f, 2, 1);
    this.effects.sparksAt(muzzle.clone().addScaledVector(dir, 3), 0xff7a2f, 4, 3, 1.4);
    for (const b of this.bots) {
      if (!b.alive || b.dropping) continue;
      const to = b.chest.clone().sub(origin);
      const d = to.length();
      if (d > 18) continue;
      to.normalize();
      if (to.dot(dir) < 0.82) continue;
      const wall = this.world.segmentHit(muzzle, b.chest);
      if (wall.hit) continue;
      this.damageDealt += w.damage;
      b.takeDamage(w.damage, p, w.name);
      this.hud.hitmarker();
      this.effects.sparksAt(b.chest, 0xff7a2f, 3, 2, 0.8);
    }
  }

  spawnProjectile(w) {
    const dir = this.getAimDir(w.spread || 0.01);
    const origin = this.tmpMuzzle.clone();
    const color = w.id === 'memes' ? 0xb06bff : 0xff7a2f;
    const mesh = new THREE.Mesh(
      new THREE.IcosahedronGeometry(w.id === 'memes' ? 0.18 : 0.28, 0),
      new THREE.MeshBasicMaterial({ color, toneMapped: false })
    );
    mesh.position.copy(origin);
    this.scene.add(mesh);
    this.projectiles.push({
      mesh, pos: origin.clone(), vel: dir.multiplyScalar(w.projectileSpeed),
      damage: w.damage, aoe: w.aoe || 1.5, weapon: w, life: 4,
      color, gravity: w.id === 'm79' ? 9 : 0,
    });
  }

  updateProjectiles(dt) {
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const pr = this.projectiles[i];
      pr.life -= dt;
      pr.vel.y -= pr.gravity * dt;
      pr.pos.addScaledVector(pr.vel, dt);
      pr.mesh.position.copy(pr.pos);
      pr.mesh.rotation.x += dt * 10;
      if (Math.random() < 0.7) this.effects.smokeAt(pr.pos, pr.color, 1, 0.3);

      let explode = pr.life <= 0;
      if (pr.pos.y <= this.world.heightAt(pr.pos.x, pr.pos.z)) explode = true;
      for (const b of this.bots) {
        if (!b.alive || b.dropping) continue;
        if (b.chest.distanceTo(pr.pos) < 0.8) { explode = true; break; }
      }
      if (!explode) {
        const wall = this.world.segmentHit(pr.pos.clone().addScaledVector(pr.vel, -dt), pr.pos);
        if (wall.hit) explode = true;
      }
      if (explode) {
        this.explode(pr.pos.clone(), pr.aoe, pr.damage, pr.weapon, pr.color);
        this.scene.remove(pr.mesh);
        pr.mesh.geometry.dispose();
        pr.mesh.material.dispose();
        this.projectiles.splice(i, 1);
      }
    }
  }

  explode(pos, radius, damage, w, color = 0xff7a2f) {
    this.effects.explosion(pos, radius, color);
    this.shake = Math.max(this.shake, 0.35);
    for (const b of this.bots) {
      if (!b.alive || b.dropping) continue;
      const d = b.chest.distanceTo(pos);
      if (d < radius) {
        const falloff = Math.max(0.35, 1 - d / radius);
        const dmg = damage * falloff;
        this.damageDealt += dmg;
        b.takeDamage(dmg, this.player, w.name);
        b.applyKnockback(b.pos.clone().sub(pos).setY(0).normalize(), 8 * falloff);
        this.hud.hitmarker(dmg >= 100);
      }
    }
    // El jugador también puede recibir su propia explosión si está muy cerca
    if (this.player.pos.distanceTo(pos) < radius * 0.7 && this.player.alive) {
      this.player.takeDamage(damage * 0.25, 'Tu propia explosión', w.name);
    }
  }

  /* ───────── especiales ───────── */
  useSpecial() {
    const p = this.player;
    if (!p.alive || p.dropping) return;
    const w = p.weapon;
    if (!w.special || p.specialCooldown > 0) return;
    p.specialCooldown = w.special.cooldown;
    this.hud.banner(w.special.name.toUpperCase(), w.special.desc, 2.2, '#ff4d6d');
    this.shake = Math.max(this.shake, 0.3);
    p.attacking = 0.3;

    if (w.special.type === 'smash') {
      const dir = this.getAimDir(0);
      let best = null, bestD = 5;
      for (const b of this.bots) {
        if (!b.alive || b.dropping) continue;
        const d = b.chest.distanceTo(p.chest);
        if (d < bestD) { best = b; bestD = d; }
      }
      this.effects.ring(p.pos, 4, 0xff4d6d);
      this.effects.sparksAt(p.pos.clone().add(new THREE.Vector3(0, 0.8, 0)), 0xff4d6d, 22, 9, 1.5);
      if (best) {
        this.damageDealt += w.special.damage;
        best.takeDamage(w.special.damage, p, w.special.name);
        best.applyKnockback(dir.clone().setY(0).normalize(), w.special.knockback || 10);
        best.stun = Math.max(best.stun, 1.2);
        this.effects.explosion(best.chest, 2, 0xff4d6d);
      }
    } else if (w.special.type === 'flurry') {
      const fwd = new THREE.Vector3(Math.sin(p.yaw), 0, Math.cos(p.yaw));
      p.pos.addScaledVector(fwd, 4.5);
      p.pos.y = this.world.heightAt(p.pos.x, p.pos.z);
      this.effects.ring(p.pos, 3, 0xffd166);
      this.effects.beam(p.chest, p.chest.clone().addScaledVector(fwd, 6), 0xffd166, 2);
      for (const b of this.bots) {
        if (!b.alive || b.dropping) continue;
        if (b.chest.distanceTo(p.chest) < 6) {
          for (let k = 0; k < w.special.hits; k++) {
            const dmg = w.special.damage;
            this.damageDealt += dmg;
            b.takeDamage(dmg, p, w.special.name);
          }
          b.applyKnockback(fwd, 8);
          this.effects.sparksAt(b.chest, 0xffd166, 14, 6, 1.2);
          this.hud.hitmarker(true);
        }
      }
    } else if (w.special.type === 'laser') {
      const dir = this.getAimDir(0);
      const origin = this.camera.position.clone();
      const end = origin.clone().addScaledVector(dir, 120);
      const wall = this.world.segmentHit(origin, end);
      let bestT = wall.hit ? wall.t * 120 : 120;
      let hitBot = null;
      for (const b of this.bots) {
        if (!b.alive || b.dropping) continue;
        const t = raySphere(origin, dir, b.chest, 0.5);
        if (t > 0 && t < bestT) { bestT = t; hitBot = b; }
      }
      const point = origin.clone().addScaledVector(dir, bestT);
      this.effects.beam(this.tmpMuzzle, point, 0xff3ea5, 2.5);
      this.effects.beam(this.tmpMuzzle, point, 0x35f0ff, 1.2);
      this.effects.explosion(point, 2, 0xb06bff);
      if (hitBot) {
        this.damageDealt += w.special.damage;
        hitBot.takeDamage(w.special.damage, p, w.special.name);
        this.hud.hitmarker(true);
      }
      this.addBurnZone(point, 4, w.special.burn, w.special.duration, 0xff3ea5);
    } else if (w.special.type === 'aoe') {
      const dir = this.getAimDir(0);
      const origin = this.camera.position.clone();
      const wall = this.world.segmentHit(origin, origin.clone().addScaledVector(dir, 60));
      const point = origin.clone().addScaledVector(dir, wall.hit ? wall.t * 60 : 60);
      point.y = Math.max(point.y, this.world.heightAt(point.x, point.z));
      this.explode(point, w.special.radius, w.special.damage, w.special, 0xff7a2f);
      this.effects.smokeAt(point, 0x2a2a2a, 16, 4);
    }
  }

  addBurnZone(pos, radius, dps, duration, color) {
    const mesh = new THREE.Mesh(
      new THREE.CylinderGeometry(radius, radius, 0.08, 28, 1, true),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.35, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending })
    );
    mesh.position.set(pos.x, Math.max(0.4, pos.y), pos.z);
    this.scene.add(mesh);
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(radius * 0.92, radius, 32),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.8, side: THREE.DoubleSide, depthWrite: false })
    );
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(pos.x, Math.max(0.42, pos.y + 0.05), pos.z);
    this.scene.add(ring);
    this.burnZones.push({ mesh, ring, pos: pos.clone(), radius, dps, until: this.time + duration, tick: 0 });
    this.hud.toast(`🔥 Zona láser activa · ${dps} daño/s durante ${duration}s`);
  }

  updateBurnZones(dt) {
    for (let i = this.burnZones.length - 1; i >= 0; i--) {
      const z = this.burnZones[i];
      if (this.time > z.until) {
        this.scene.remove(z.mesh, z.ring);
        z.mesh.geometry.dispose(); z.mesh.material.dispose();
        z.ring.geometry.dispose(); z.ring.material.dispose();
        this.burnZones.splice(i, 1);
        continue;
      }
      z.mesh.material.opacity = 0.25 + Math.sin(this.time * 6) * 0.1;
      z.ring.material.opacity = 0.5 + Math.sin(this.time * 4) * 0.25;
      z.tick -= dt;
      if (z.tick <= 0) {
        z.tick = 0.5;
        for (const b of this.bots) {
          if (!b.alive) continue;
          if (b.chest.distanceTo(z.pos) < z.radius) {
            const dmg = z.dps * 0.5;
            this.damageDealt += dmg;
            b.takeDamage(dmg, this.player, 'Láser Nostálgico');
          }
        }
      }
    }
  }

  updateBoomerangs(dt) {
    for (let i = this.boomerangs.length - 1; i >= 0; i--) {
      const b = this.boomerangs[i];
      b.t += dt;
      if (b.phase === 'out') {
        const k = Math.min(1, b.t / 0.35);
        b.mesh.position.lerpVectors(b.from, b.to, k);
        if (k >= 1) { b.phase = 'back'; b.t = 0; }
      } else {
        const k = Math.min(1, b.t / 0.4);
        b.mesh.position.lerpVectors(b.to, this.player.chest, k);
        if (k >= 1) {
          this.scene.remove(b.mesh);
          b.mesh.geometry.dispose(); b.mesh.material.dispose();
          this.boomerangs.splice(i, 1);
          continue;
        }
      }
      b.mesh.rotation.x += dt * 22;
      b.mesh.rotation.y += dt * 12;
    }
  }

  /* ───────── daño / muertes ───────── */
  aliveEntities() {
    return [this.player, ...this.bots];
  }

  damageEntity(e, amount, source, weaponName) {
    if (!e || !e.alive) return;
    if (e === this.player) e.takeDamage(amount, source, weaponName);
    else e.takeDamage(amount, source, weaponName);
  }

  botShoot(bot, target, w) {
    if (!target || !target.alive) return;
    const from = bot.chest.clone().add(new THREE.Vector3(0, 0.25, 0));
    const to = target === this.player ? target.chest : target.chest;
    const los = this.world.segmentHit(from, to);
    if (los.hit && los.t < 0.98) return;

    const dist = from.distanceTo(to);
    let chance = bot.accuracy;
    if (target === this.player) {
      const speed = Math.hypot(this.player.vel.x, this.player.vel.z);
      chance *= clamp(1 - speed / 22, 0.45, 1);
      if (this.player.dropping) return;
    } else {
      chance *= 1.2;
    }
    chance *= clamp(1.25 - dist / (w.range * 1.4), 0.25, 1);
    if (w.melee) chance = dist < w.range ? 0.85 : 0;
    if (w.pellets) chance *= 0.55;

    const muzzle = bot.pos.clone().add(new THREE.Vector3(Math.sin(bot.yaw) * 0.35, 0.55, Math.cos(bot.yaw) * 0.35));
    this.effects.muzzle(muzzle);
    const hit = Math.random() < chance;
    const point = hit ? to.clone() : to.clone().add(new THREE.Vector3(rand(-2, 2), rand(-1, 2), rand(-2, 2)));
    this.effects.tracer(muzzle, point, 0xff5a5a);

    if (hit) {
      let dmg = w.damage;
      if (w.pellets) dmg *= 0.5;
      if (target === this.player) {
        this.player.takeDamage(dmg, bot.name, w.name);
      } else {
        target.takeDamage(dmg * 1.35, bot, w.name);
      }
      this.effects.sparksAt(to, 0xff5a5a, 4, 3, 0.7);
    } else {
      this.effects.sparksAt(point, 0xffd166, 2, 2, 0.6);
    }
  }

  killBot(bot, source, weaponName = '') {
    if (!bot.alive) return;
    bot.alive = false;
    bot.mesh.visible = false;
    this.aliveCount = Math.max(1, this.aliveCount - 1);
    this.effects.explosion(bot.pos.clone().add(new THREE.Vector3(0, 0.5, 0)), 1.4, 0xff5a5a);
    this.effects.smokeAt(bot.pos, 0x6a5a5a, 6, 1.5);
    this.dropLoot(bot);

    if (source === this.player) {
      this.kills++;
      this.hud.kill(this.playerName, bot.name, weaponName || 'el caos', true);
      this.hud.chat(`💀 <b>${this.playerName}</b> eliminó a <b>${bot.name}</b> con ${weaponName}`, '');
      this.hud.toast(`💀 Eliminaste a ${bot.name}`);
    } else if (source && source.name) {
      this.hud.kill(source.name, bot.name, weaponName || 'el caos');
    } else {
      this.hud.kill(source || '☠️ El caos', bot.name, weaponName || '');
    }

    if (this.aliveCount === 1 && this.player.alive && this.state !== 'over') {
      setTimeout(() => this.win(), 700);
    }
  }

  dropLoot(bot) {
    const r = Math.random();
    const pos = bot.pos;
    if (r < 0.62) {
      const id = randomWeapon(Math.random, 0.12);
      this.addPickup('weapon', pos.x + rand(-0.5, 0.5), pos.z + rand(-0.5, 0.5), pos.y, id);
    } else if (r < 0.84) {
      this.addPickup('health', pos.x + rand(-0.5, 0.5), pos.z + rand(-0.5, 0.5), pos.y);
    } else {
      this.addPickup('ammo', pos.x + rand(-0.5, 0.5), pos.z + rand(-0.5, 0.5), pos.y);
    }
    // color de la nueva instancia
    const idx = this.pickups.length - 1;
    if (idx >= 0 && idx < this.pickupCap) {
      const p = this.pickups[idx];
      const col = this.pickupColor(p);
      this.pickupMesh.setColorAt(idx, col);
      this.beamMesh.setColorAt(idx, col);
      if (this.pickupMesh.instanceColor) this.pickupMesh.instanceColor.needsUpdate = true;
      if (this.beamMesh.instanceColor) this.beamMesh.instanceColor.needsUpdate = true;
    }
  }

  killPlayer(source, weaponName = '') {
    if (!this.player.alive) return;
    const placement = this.aliveCount;
    this.player.alive = false;
    this.player.hp = 0;
    this.aliveCount = Math.max(1, this.aliveCount - 1);
    this.state = 'over';
    this.input.setEnabled(false);
    document.exitPointerLock?.();
    this.player.character.rig.rotation.z = 1.45;
    this.player.character.rig.rotation.x = -0.3;
    this.player.character.rig.position.y = -0.15;
    this.effects.explosion(this.player.pos.clone().add(new THREE.Vector3(0, 0.6, 0)), 1.6, 0xff3b4e);
    this.hud.kill(source, this.playerName, weaponName || 'el caos', true);
    this.hud.chat(`☠️ <b>${this.playerName}</b> fue eliminado por ${source}`, 'event');
    this.hud.hide();
    this.showEnd({
      win: false,
      placement,
      reason: weaponName ? `${source} te eliminó con ${weaponName}` : `${source} te eliminó`,
    });
  }

  win() {
    if (this.state === 'over') return;
    this.state = 'over';
    this.input.setEnabled(false);
    document.exitPointerLock?.();
    this.hud.hide();
    for (let i = 0; i < 6; i++) {
      setTimeout(() => {
        const p = this.player.pos.clone().add(new THREE.Vector3(rand(-6, 6), rand(1, 5), rand(-6, 6)));
        this.effects.explosion(p, 2.5, [0xffd166, 0xff3ea5, 0x35f0ff][i % 3]);
      }, i * 180);
    }
    this.showEnd({ win: true, placement: 1, reason: 'El último meme en pie' });
  }

  showEnd({ win, placement, reason }) {
    const end = $('end-screen');
    $('end-kicker').textContent = win ? 'ÚLTIMO EN PIE' : 'PARTIDA TERMINADA';
    $('end-title').textContent = win ? '¡VICTORIA!' : 'ELIMINADO';
    $('end-title').classList.toggle('win', win);
    $('end-sub').textContent = win
      ? 'Miguel sobrevivió al caos, a los pollos y al meteorito.'
      : 'Los memes te recordarán. O no.';
    $('end-place').textContent = `#${placement}`;
    $('stat-kills').textContent = this.kills;
    $('stat-damage').textContent = Math.round(this.damageDealt);
    $('stat-chickens').textContent = this.hazards?.chickenKills || 0;
    $('stat-time').textContent = `${String(Math.floor(this.time / 60)).padStart(2, '0')}:${String(Math.floor(this.time % 60)).padStart(2, '0')}`;
    $('end-reason').textContent = reason;
    end.classList.remove('hidden');
  }

  /* ───────── pausa ───────── */
  pause() {
    if (this.state !== 'playing' && this.state !== 'drop') return;
    this.pausedFrom = this.state;
    this.state = 'paused';
    this.input.setEnabled(false);
    $('pause').classList.remove('hidden');
    document.exitPointerLock?.();
  }

  resume() {
    if (this.state !== 'paused') return;
    this.state = this.pausedFrom;
    $('pause').classList.add('hidden');
    this.input.setEnabled(true);
    this.input.requestLock();
  }

  quit() {
    this.dispose();
    this.opts.onExit?.();
  }

  /* ───────── cámara / HUD ───────── */
  resize() {
    this.camera.aspect = innerWidth / innerHeight;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(innerWidth, innerHeight, false);
  }

  updateCamera(dt, snap = false) {
    const p = this.player;
    if (!p) return;
    const target = p.pos.clone().add(new THREE.Vector3(0, 0.9, 0));
    const aiming = p.aiming && !p.dropping;
    const w = p.weapon;
    const dist = p.dropping ? 6.8 : aiming ? (w.scope ? 1.5 : 2.25) : 3.5;
    const fovTarget = p.dropping ? 74 : aiming ? (w.scope ? 38 : 56) : 70;
    this.camera.fov += (fovTarget - this.camera.fov) * Math.min(1, dt * 9);
    this.camera.updateProjectionMatrix();

    const wobble = this.aimWobble;
    this.aimWobble = Math.max(0, this.aimWobble - dt * 1.5);
    const wx = (Math.random() - 0.5) * wobble * 0.05;
    const wy = (Math.random() - 0.5) * wobble * 0.05;
    const yaw = p.yaw + wx;
    const pitch = clamp(p.pitch + wy, -0.52, 0.95);
    const fwd = new THREE.Vector3(Math.sin(yaw) * Math.cos(pitch), Math.sin(pitch), Math.cos(yaw) * Math.cos(pitch));
    const horiz = new THREE.Vector3(Math.sin(yaw), 0, Math.cos(yaw));
    const desired = target.clone()
      .addScaledVector(horiz, -dist * Math.cos(pitch * 0.55))
      .add(new THREE.Vector3(0, 0.55 + Math.max(0, pitch) * 1.5 + (p.dropping ? 2.4 : 0), 0));

    const hit = this.world.segmentHit(target, desired);
    if (hit.hit) desired.copy(hit.point).lerp(target, 0.18);
    const gy = this.world.heightAt(desired.x, desired.z) + 0.35;
    if (desired.y < gy) desired.y = gy;

    if (snap) this.camera.position.copy(desired);
    else this.camera.position.lerp(desired, Math.min(1, dt * 16));

    this.shake = Math.max(0, this.shake - dt * 3.5);
    if (this.shake > 0.01) {
      this.camera.position.x += (Math.random() - 0.5) * this.shake * 0.35;
      this.camera.position.y += (Math.random() - 0.5) * this.shake * 0.35;
      this.camera.position.z += (Math.random() - 0.5) * this.shake * 0.35;
    }

    const look = target.clone().addScaledVector(fwd, 14);
    this.camera.lookAt(look);
  }

  updateHUD() {
    const p = this.player;
    const w = p.weapon;
    const item = p.item;
    const zone = this.hazards.safe;
    const outside = Math.hypot(p.pos.x - zone.x, p.pos.z - zone.z) > zone.r;
    const inLava = this.hazards.lavaAt(p.pos.x, p.pos.z);
    const zoneDanger = (outside || inLava) && this.time > 80;
    let zoneTime = this.hazards.zoneLabel(this.time);
    if (this.map.lava && this.time < 120) zoneTime = `🌋 ${Math.ceil(120 - this.time)}s`;
    else if (this.hazards.erupted) zoneTime = 'LAVA';

    const enemies = this.bots.filter((b) => b.alive).map((b) => ({ x: b.pos.x, z: b.pos.z }));
    const loot = [];
    for (let i = 0; i < this.pickups.length; i += 2) {
      const pk = this.pickups[i];
      if (!pk.taken && pk.type === 'weapon') loot.push({ x: pk.x, z: pk.z });
    }

    this.hud.update(1 / 60, {
      hp: p.hp,
      ammo: item ? item.mag : 0,
      reserve: item ? item.reserve : 0,
      weapon: w,
      slots: p.slots.map((s) => WEAPONS[s.id]),
      slotIndex: p.slotIndex,
      alive: this.aliveCount,
      timer: this.time,
      specialRemaining: p.specialCooldown,
      specialTotal: w.special?.cooldown || 1,
      reloading: p.reloading,
      zoneDanger,
      maskTime: p.maskTime,
      funado: p.funado,
      zoneTime,
      minimap: {
        safe: zone,
        hazardRadius: this.hazards.erupted ? this.hazards.lavaRadius : 0,
        player: { x: p.pos.x, z: p.pos.z, yaw: Math.PI - p.yaw },
        enemies,
        loot,
      },
    });
  }

  /* ───────── loop ───────── */
  loop(now) {
    if (this.disposed) return;
    this.raf = requestAnimationFrame(this.loop);
    const dt = this.lastFrame ? Math.min(0.05, (now - this.lastFrame) / 1000) : 0.016;
    this.lastFrame = now;

    if (this.state === 'playing' || this.state === 'drop') {
      this.time += dt;
      const input = this.input.sample();
      if (input.pause) this.pause();

      this.player.update(dt, input);
      if (this.player.alive) {
        if (input.interact && this.nearPickup) this.takePickup(this.nearPickup);
        if (input.special) this.useSpecial();
      }
      for (const b of this.bots) b.update(dt);
      this.hazards.update(dt, this.time);
      this.updateProjectiles(dt);
      this.updateBurnZones(dt);
      this.updateBoomerangs(dt);
      this.updatePickups(dt);
      this.updateBotShadows();
      this.effects.update(dt);

      // Chat ambiental
      this.ambientTimer -= dt;
      if (this.ambientTimer <= 0) {
        this.ambientTimer = 18 + Math.random() * 16;
        const name = this.bots.find((b) => b.alive)?.name || 'Cheems';
        this.hud.chat(`💬 <b>${name}:</b> ${CHAT_LINES[Math.floor(Math.random() * CHAT_LINES.length)]}`, '');
      }

      // Si el jugador muere, el estado cambia dentro de la actualización
      if (this.state === 'over') {
        this.updateHUD();
        this.updateCamera(dt);
        this.renderer.render(this.scene, this.camera);
        return;
      }

      this.updateCamera(dt);
      this.updateHUD();
      this.hud.updateFloats(dt, this.camera);
    } else {
      // En pausa / fin: no avanzar el mundo
      this.updateCamera(dt);
    }

    this.renderer.render(this.scene, this.camera);

    // Monitor de FPS y bajada automática de resolución
    this.fpsAcc += dt; this.fpsFrames++; this.fpsCheck += dt;
    if (this.fpsCheck > 2.5) {
      const fps = this.fpsFrames / this.fpsAcc;
      this.fpsAcc = 0; this.fpsFrames = 0; this.fpsCheck = 0;
      if (fps < 47 && this.renderer.getPixelRatio() > 0.85 && !this.downgraded) {
        const pr = Math.max(0.85, this.renderer.getPixelRatio() - 0.2);
        this.renderer.setPixelRatio(pr);
        this.renderer.setSize(innerWidth, innerHeight, false);
        this.downgraded = pr <= 0.86;
        this.hud.toast('⚙️ Calidad ajustada para mantener 60 FPS');
      }
    }
  }

  dispose() {
    if (this.disposed) return;
    this.disposed = true;
    cancelAnimationFrame(this.raf);
    this.input?.setEnabled(false);
    this.input?.dispose?.();
    this.ac.abort();
    this.hud?.destroy();
    this.hazards?.dispose();
    this.effects?.dispose();
    for (const b of this.bots) b.dispose();
    this.player?.dispose();
    this.world?.dispose();
    this.scene.clear();
    $('end-screen').classList.add('hidden');
    $('pause').classList.add('hidden');
    this.hud?.hide();
  }
}

