() => {
 const g=window.__game,p=g.player;
 if(!g) return 'no game';
 p.dropping=false; p.grounded=true; p.spawnGuard=0; g.state='playing';
 const b=g.bots.find(b=>b.alive);
 b.dropping=false; b.alive=true; b.pos.set(20, g.world.heightAt(20,0), 0); b.mesh.position.copy(b.pos);
 p.pos.set(20, b.pos.y, 8); p.yaw=0; p.pitch=0; // bot at z0, player z8, yaw 0 looks +z? Wait yaw=0 forward is +z. To look at -z, yaw=PI.
 p.yaw=Math.PI; p.pitch=0;
 p.item.mag=999; p.fireCooldown=0;
 g.updateCamera(0.016,true);
 const hp0=b.hp;
 for(let i=0;i<5;i++){ g.playerShoot(); }
 return {hp0, hp1:b.hp, yaw:p.yaw, cam:[g.camera.position.x,g.camera.position.y,g.camera.position.z], botPos:[b.pos.x,b.pos.y,b.pos.z], playerPos:[p.pos.x,p.pos.y,p.pos.z], dist:p.pos.distanceTo(b.pos)};
